  FT["PH-H3531"] = {"id":"PH-H3531","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4329_1965.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在南莱特省Macrohon市镇设立省级动物繁育站并授权为此拨款的法案","en":"An Act Providing for the Establishment of a Provincial Animal Breeding Station in the Municipality of Macrohon, Province of Southern Leyte, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of a Provincial Animal Breeding Station in the Municipality of Macrohon, Province of Southern Leyte, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4329","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4329_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3531-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Director of Animal Industry, a provincial animal breeding in the Municipality of Macrohon, Province of Southern Leyte."}},{"id":"PH-H3531-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Director of Animal Industry shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H3531-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of the said animal breeding station, said sum to be spent by the Director of Animal Industry subject to the approval of the Secretary of Agriculture and Natural Resources; for the purchase of breeding animals, sheds, corrals and other structures; for the establishment of a water system; for the salaries and wages of personnel; and for such other expenses as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H3531-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of a Provincial Animal Breeding Station in the Municipality of Macrohon, Province of Southern Leyte, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
