  FT["PH-H3536"] = {"id":"PH-H3536","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4334_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为阿克兰省增设2个Assistant 省立 Fiscal职位，为此修订《行政法典》第1674条（经修正）的法案","en":"An Act Creating Two Additional Positions of Assistant Provincial Fiscal for the Province of Aklan, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","orig":"An Act Creating Two Additional Positions of Assistant Provincial Fiscal for the Province of Aklan, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4334","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4334_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3536-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provision of Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Aklan is further amended to read as follows:\n\"Aklan, four assistant provincial fiscals;\""}},{"id":"PH-H3536-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect on the first day of January, nineteen hundred and sixty-six.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Two Additional Positions of Assistant Provincial Fiscal for the Province of Aklan, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3537"] = {"id":"PH-H3537","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4335_1965.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Binmaley市","en":"An Act Converting the Binmaley School of Fisheries in the Municipality of Binmaley, Province of Pangasinan, into a College to be Known as the Pangasinan College of Fisheries, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Converting the Binmaley School of Fisheries in the Municipality of Binmaley, Province of Pangasinan, into a College to be Known as the Pangasinan College of Fisheries, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật chuyển đổi Binmaley School of Fisheries thành Pangasinan College of Fisheries","th":"พระราชบัญญัติเปลี่ยนสถานะ Binmaley School of Fisheries เป็น Pangasinan College of Fisheries","id":"Undang-Undang mengubah Binmaley School of Fisheries menjadi Pangasinan College of Fisheries","ms":"Akta menukar Binmaley School of Fisheries kepada Pangasinan College of Fisheries"},"level":"law","status":"active","topics":["environment","education"],"docNumber":"Republic Act No. 4335","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4335_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3537-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Binmaley School of Fisheries in the Municipality of Binmaley, Province of Pangasinan, is hereby converted into a college to be known as the Pangasinan College of Fisheries to offer, in addition to the secondary fishery curriculum, a four-year teacher education course, a four-year technical fisheries curriculum and a two-year technical fisheries curriculum."}},{"id":"PH-H3537-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Pangasinan College of Fisheries shall be headed by a Superintendent and shall be under the supervision of the Director of Vocational Education."}},{"id":"PH-H3537-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Director of Vocational Education is hereby empowered to reorganize said school accordingly."}},{"id":"PH-H3537-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"In addition to the appropriation for the Binmaley School of Fisheries in the General Appropriations Act, the sum of six hundred thousand pesos is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, for the conversion, operation and maintenance of said college during the fiscal year nineteen hundred sixty-six. Thereafter, the necessary sum for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3537-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50"};
  FT["PH-H3538"] = {"id":"PH-H3538","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4336_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating One Hundred Thousand Pesos to Defray the Expenses of Holding the Convention of the Asian People's Anti-Communist League at Manila in the Year Nineteen Hundred and Sixty-Five","orig":"An Act Appropriating One Hundred Thousand Pesos to Defray the Expenses of Holding the Convention of the Asian People's Anti-Communist League at Manila in the Year Nineteen Hundred and Sixty-Five"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4336","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4336_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3538-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby appropriated the sum of one hundred thousand pesos, out of any funds in the National Treasury not otherwise appropriated, to defray the expenses for the holding of the convention of the Asian People’s Anti-Communist League at Manila, in nineteen hundred and sixty-five: Provided, However, That whatever resolutions passed or communiqués agreed upon by the conferees should not necessarily be interpreted as in accordance with the foreign policy of the Republic of the Philippines.\nThe sum herein appropriated shall be available immediately upon the approval of this Act, and be at the disposal of the Department of National Defense exclusively for the Philippine Anti-Communist Movement: Provided, However, That no part of this Appropriation shall be used in the purchase of equipment: And, Provided, further, That any and all expenses out of this appropriation shall be subject to the usual government auditing procedures."}},{"id":"PH-H3538-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50"};
  FT["PH-H3539"] = {"id":"PH-H3539","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4337_1965.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"设立打拉技术学院的法案","en":"An Act Establishing the Tarlac College of Technology","orig":"An Act Establishing the Tarlac College of Technology","vi":"Đạo luật thành lập Cao đẳng Công nghệ Tarlac","th":"พระราชบัญญัติจัดตั้งวิทยาลัยเทคโนโลยี Tarlac","id":"Undang-Undang membentuk Sekolah Tinggi Teknologi Tarlac","ms":"Akta menubuhkan Kolej Teknologi Tarlac"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4337","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4337_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3539-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established in the Municipality of Tarlac, Province of Tarlac, a college to be known as the Tarlac College of Technology; by converting the present Tarlac School of Arts and Trades, located at Tarlac, Tarlac, and the Tarlac National Agricultural School, located at Camiling, Tarlac, as such."}},{"id":"PH-H3539-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Tarlac College of Technology is an effective institution for the Government’s moral regeneration and socio-economic programs, as well as for the educational mandate, Article XIV, Section V of the Philippine Constitution. The college aims, among their things, the following:\n(1) To train and develop junior technicians (skilled workers and craftsmen), technicians and technologists needed by industries;\n(2) To train and develop rural industrial leadership for barrio and community industries; and\n(3) To increase productivity by upgrading the technical skills and related knowledge of workers, foremen, supervisors, managers, and executives of industries through adult technical and technological extension courses."}},{"id":"PH-H3539-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"No student shall be denied admission to the Tarlac College of Technology by reason of age, sex, nationality, religious belief, or political affiliation."}},{"id":"PH-H3539-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"On or before the tenth day of June of each year the Board of Trustees shall file with the President of the Philippines a detailed report setting forth the progress, condition, and needs of the College."}},{"id":"PH-H3539-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Government of the College is vested in a Board of Trustees to be known as the Board of Trustees of the Tarlac College of Technology. The Board of Trustees shall be composed of the Secretary of Education, who shall be ex-officio chairman of the Board, the Chairman of the Committee on Education of the Senate, the Chairman of the Committee on Education of the House of Representatives, the Secretary of Agriculture and Natural Resources, the Secretary of Labor, the Secretary of Public Works and Communications, the president of the biggest labor union in the service area, the president of the industrial management group in the service area, the Governor of Tarlac, the Director of Vocational Education, and the President of the College, as members.\nThe members of the Board of Trustees shall serve without compensation other than actual and necessary expenses incurred either in attendance upon meetings of the Board or upon other official business authorized by resolution of the Board."}},{"id":"PH-H3539-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Board of Trustees shall have the following powers and duties, in addition to its general powers of administration:\n(a) To receive and appropriate to the ends specified by law such sums as may be provided by law for the support of the College;\n(b) To provide for the establishment of a College of Arts and Trades, a College of Agriculture, College of Engineering, a College of Architecture and Fine Arts, a College of Forestry, and such other colleges and schools as the Board of Trustees may deem necessary.\n(c) To establish Chairs in the colleges mentioned in paragraph (b) and to provide for the maintenance or endowment of such Chairs, as well as to provide for such other positions as professors, assistant professors, instructors, tutors, and lecturers as the progress of the College may make necessary, and to fix the compensation pertaining to such position;\n(d) To appoint on the recommendation of the President of the College, professors, instructors, lecturers, teachers and other employees of the college; to fix their compensation, hours of service, and such other duties and conditions as it may deem proper; to grant to them in its discretion leave of absence under such regulations as it may promulgate, any provision of law to the contrary notwithstanding, and to remove them only for cause after an investigation and a hearing have been had;\n(e) To approve the courses of study and rules of discipline drawn up by the College Council as hereinafter provided; to fix the tuition fees required of students, as well as matriculation fees, graduation fees, and fees for laboratory courses, and all special fees; and to remit the same in special cases;\n(f) To provide fellowships and scholarships and to award the same to students showing special evidence of merit;\n(g) To prescribe rules for its own government, and to enact for the government of the College such general ordinances and regulations, not contrary to law, as are consistent with the purposes of the College as defined in Section two of this Act;\n(h) To receive in trust legacies, gifts, and donations, real and personal property of all kinds, and to administer the same for the benefit of the College or of a department thereof, or for aid of any student, or students, in accordance with the direction or instruction of the donor, and, in default thereof, in such manner as the Board of Trustees may in its discretion determine."}},{"id":"PH-H3539-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"A quorum of the Board of Trustees shall consist of a majority of all the members. All processes against the Board of Trustees shall be served on the Chairman or secretary thereof."}},{"id":"PH-H3539-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The head of the institution shall be known as the President of the Tarlac College of Technology. He shall be appointed by the President of the Philippines upon recommendation of the Board of Trustees, subject to the confirmation of the Commission on Appointments."}},{"id":"PH-H3539-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"There shall be a College Council, consisting of the President of the College and of all instructors of the College. The Council alone shall have the power to recommend students or others to be recipients of degrees. Through its president or committee, it shall have disciplinary power over the students within the limits prescribed by the rules of discipline approved by the Board of Trustees."}},{"id":"PH-H3539-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The body of instructors of each college shall constitute its faculty, and as presiding officer of each faculty there shall be a dean elected from members of such faculty by the Board of Trustees on nomination by the President of the College. In the appointment of professors, instructors, teachers, and other employees of the College, no religious test shall be applied nor shall the religious opinions or affiliations of the instructors of the College be made a matter of examination or inquiry: Provided, However, That no instructor in the College shall inculcate sectarian tenets in any of the teachings, nor attempt, either directly or indirectly under penalty of dismissal by the Board of Trustees, to influence students or attendants at the College for or against any particular church or religious sect."}},{"id":"PH-H3539-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Professors, instructors and other personnel of the College shall be exempt from any civil service examination or regulations as a requisite to appointment and from the Wage Position Classification Office rules and regulations as to salary scales and promotions."}},{"id":"PH-H3539-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"There shall be a secretary of the College to be appointed by the Board of Trustees. He shall be the secretary of that Board and also of the College, and shall keep such records of the College as may be assigned to him by the Board."}},{"id":"PH-H3539-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The Treasurer of the Philippines shall be ex-officio treasurer of the College and all accounts and expenses thereof shall be audited by the Auditor General, and all disbursements shall be made in accordance with the rules and regulations prescribed by him."}},{"id":"PH-H3539-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Head of bureaus and offices of the National, provincial, municipal governments and government corporations and other instrumentalities, upon request of the President of Tarlac College of Technology, are hereby authorized to loan or make available without cost, laboratory apparatus, shop tools, instruments and equipment and to make available their shop and laboratory and facilities for instructional purposes, and to detail employees for duty at the Tarlac College of Technology, when in the judgment of the head of the bureau or office such employees can be spared without serious detriment to the public service. Employees so detailed shall perform such duty as is required under such detail, and the time so employed shall count as part of their regular official service."}},{"id":"PH-H3539-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The President of the Philippines, the President of the Senate, and Speaker of the House of Representatives shall constitute a Board of Visitors of the College whose duty shall be to attend the commencement exercises of the College and to make visits at such other times as they may deem proper, to examine the property, course of study, discipline, and the state of finances of the College, to inspect all books and accounts of the institution, and to make reports to the Congress of the Philippines thereon with such recommendations as they may find necessary."}},{"id":"PH-H3539-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The Tarlac School of Arts and Trades in the Municipality of Tarlac and the Tarlac National Agricultural School in the Municipality of Camiling, both in the Province of Tarlac, are hereby abolished."}},{"id":"PH-H3539-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"The present faculty and employees of the Tarlac School of Arts and Trades and the Tarlac National Agricultural School, including all unexpended appropriations, records, assets, liabilities, properties and equipment, are transferred to the Tarlac College of Technology. Salaries of the personnel shall be adjusted at the discretion of the Board within the amount available for appropriation: Provided, However, That no personnel of the converted schools shall be laid off, demoted in rank or reduced in salary."}},{"id":"PH-H3539-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"In addition to the present appropriations for the Tarlac School of Arts and Trades and Tarlac National Agricultural School, one million pesos is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the Tarlac College of Technology during the fiscal year nineteen hundred sixty-six. Thereafter, such sums as may be necessary for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H3539-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing the Tarlac College of Technology","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3540"] = {"id":"PH-H3540","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4338_1965.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在打拉省Mayantoc市镇设立淡水示范渔场与苗种场并授权为此拨款的法案","en":"An Act to Establish a Fresh-Water Demonstration Fish Farm and Nursery in the Municipality of Mayantoc, Province of Tarlac, and to Authorize the Appropriation of Funds Therefor","orig":"An Act to Establish a Fresh-Water Demonstration Fish Farm and Nursery in the Municipality of Mayantoc, Province of Tarlac, and to Authorize the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 4338","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4338_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3540-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Philippine Fisheries Commission, a fresh-water demonstration fish farm and nursery in the Municipality of Mayantoc, Province of Tarlac."}},{"id":"PH-H3540-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said fresh-water demonstration fish farm and nursery for fiscal year nineteen hundred sixty-six. Thereafter, such sums as may be necessary for the same purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H3540-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Establish a Fresh-Water Demonstration Fish Farm and Nursery in the Municipality of Mayantoc, Province of Tarlac, and to Authorize the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3541"] = {"id":"PH-H3541","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4339_1965.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予 Iglesia ni Cristo 设立私人电信无线电台的特许经营权法案","en":"An Act Granting the Iglesia ni Cristo a Franchise to Establish Radio Stations for Private Telecommunication","orig":"An Act Granting the Iglesia ni Cristo a Franchise to Establish Radio Stations for Private Telecommunication","vi":"Đạo luật cấp quyền khai thác cho Iglesia ni Cristo để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Iglesia ni Cristo เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada Iglesia ni Cristo untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio di Filipina","ms":"Akta memberikan francais kepada Iglesia ni Cristo untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio di Filipina"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 4339","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4339_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3541-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and the provisions not inconsistent herewith of Act Numbered Three thousand eight hundred and forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, there is hereby granted to the Iglesia ni Cristo, its successors or assigns, and hereunder referred to as the \"grantee,\" the right and privilege of constructing, installing, establishing and operating in the Philippines, at such places as the grantee may select and the Secretary of Public Works and Communications may approve, radio stations in the domestic private fixed point-to-point base, non-commercial broadcasting, aeronautical and land-mobile stations, including coastal marine service with the corresponding relay stations for the reception and transmission of wireless messages on radiotelegraph and/or radiotelephone and other types of emissions, or both, with vessels at sea and aircraft in the air, without or within the Philippines."}},{"id":"PH-H3541-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace or order, to take over and operate the said stations or to authorize the temporary use and operation thereof by any department of the Government without compensating the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H3541-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the construction of said stations or any of them on any land of the public domain upon such terms and conditions as he may prescribe."}},{"id":"PH-H3541-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date the first of said stations shall be placed in operation, and is granted upon the express condition that the same shall be void unless the construction of said station be begun within two years from the date of the approval of this Act and be completed within four years from said date."}},{"id":"PH-H3541-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"(a) This franchise shall not take effect nor shall any power thereunder be exercised by the grantee until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder and determined the stations to and from which each frequency and wave length may be used, and issued to the grantee a license for such use.\n(b) The Secretary of Public Works and Communications, on reasonable notice to the grantee, may at any time change, or cancel, or modify, in whole or in part, any or all of the allotments of frequencies or wave lengths to be used. He may take such action: (1) whenever in his judgment such frequencies and wave lengths have been used, or there is danger that they will be used by the grantee to impair electrical communications, or stifle competition, or to obtain a monopoly in electrical communication, or to violate otherwise the laws or public policy of the Republic of the Philippines; (2) whenever in his judgment the public interests of the Republic of the Philippines require that such frequencies or wave lengths should be used for other purposes than those of the grantee, either by the Government of the Philippines or by other individuals or corporations licensed by it; and (3) whenever in his judgment, for any reason, the public interests of the Philippines so require."}},{"id":"PH-H3541-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The stations of the grantee shall be so constructed and operated and the wave lengths so selected as to avoid interference with existing stations and to permit the expansion of the grantee’s services."}},{"id":"PH-H3541-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall hold the national, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H3541-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"No private property shall be taken for any purpose by the grantee without proper condemnation proceedings and just compensation paid or tendered therefor, and any authority to take and occupy land contained herein shall not apply to the taking, use or occupation of any land except such as is required for the actual necessary purpose for which this franchise is granted."}},{"id":"PH-H3541-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H3541-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall file a bond in the amount of twenty-five thousand pesos to guarantee the full compliance and fulfillment of the conditions under which this franchise is granted. If after four years from the date of the approval of this Act, the grantee shall have fulfilled said conditions, or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Government."}},{"id":"PH-H3541-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This franchise shall not be interpreted to mean as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H3541-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Iglesia ni Cristo a Franchise to Establish Radio Stations for Private Telecommunication","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3542"] = {"id":"PH-H3542","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4340_1965.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予 Lektron Corporation 在菲律宾境内建设、维护和运营私人固定点对点、陆基与陆上移动无线电台的临时许可的法案","en":"An Act Granting Lektron Corporation a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land-Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting Lektron Corporation a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land-Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","vi":"Đạo luật cấp giấy phép tạm thời cho Lektron Corporation để xây dựng, duy trì và vận hành trạm vô tuyến cố định điểm-điểm, trên mặt đất và di động mặt đất tư nhân để nhận và truyền thông tin vô tuyến tại Philippines","th":"พระราชบัญญัติให้ใบอนุญาตชั่วคราวแก่ Lektron Corporation ในการก่อสร้าง บำรุงรักษา และดำเนินการสถานีวิทยุแบบจุดต่อจุดประจำที่、ภาคพื้นดินและเคลื่อนที่ภาคพื้นดินของเอกชนสำหรับรับและส่งการสื่อสารทางวิทยุในฟิลิปปินส์","id":"Undang-Undang memberikan izin sementara kepada Lektron Corporation untuk membangun, memelihara, dan mengoperasikan stasiun radio titik-ke-titik tetap, berbasis darat dan mudah alih darat swasta untuk penerimaan dan pengiriman komunikasi radio di Filipina","ms":"Akta memberikan permit sementara kepada Lektron Corporation untuk membina, menyelenggarakan dan mengendalikan stesen radio titik-ke-titik tetap, berasas darat dan mudah alih darat persendirian untuk penerimaan dan penghantaran komunikasi radio di Filipina"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4340","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4340_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3542-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Lektron Corporation a temporary permit to construct, maintain and operate in the Philippines, at Manila and/or at such places as the said corporation may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point and land-based and land mobile radio stations for the reception and transmission of wireless messages on radiotelegraph or radiotelephone, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H3542-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar services at the places selected by the grantee, but not exceeding twenty-five years, and is granted upon the express condition that the same shall be void unless the construction or installation of said stations be begun within one year from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H3542-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, its successors or assigns, shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, maintain and operate private fixed point-to-point and land-based and land mobile radio stations in such places within the Philippines as the interest of the grantee may justify."}},{"id":"PH-H3542-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No fees shall be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H3542-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, its successors or assigns, shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H3542-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall hold the national, provincial, city and municipal governments harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H3542-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H3542-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee is authorized to operate its private fixed point-to-point and land-based and land mobile radio stations in the medium frequency, high frequency, and very high frequency that may be assigned to it by the Secretary of Public Works and Communications."}},{"id":"PH-H3542-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had."}},{"id":"PH-H3542-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public, peril, emergency, calamity or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H3542-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H3542-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Lektron Corporation a Temporary Permit to Construct, Maintain and Operate Private Fixed Point-to-Point and Land-Based and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3543"] = {"id":"PH-H3543","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4341_1965.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"授权为菲律宾大学内规划学院的建筑物、设施与营运费用拨款并为其他目的法案","en":"An Act Authorizing the Appropriation of Funds for Buildings, Facilities, and Operating Expenses of the Institute of Planning Within the University of the Philippines, and for Other Purposes","orig":"An Act Authorizing the Appropriation of Funds for Buildings, Facilities, and Operating Expenses of the Institute of Planning Within the University of the Philippines, and for Other Purposes"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4341","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4341_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3543-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"It is hereby declared as a national policy to strengthen and assist government and local government agencies and private organizations in the study and solution of their development problems, to facilitate the realization of development proposals at all levels, to improve human settlements and their environments by the integration of social, economic, physical and administrative considerations to produce coordinated and comprehensive development studies and plans; and to make available a pool of capable professional urban and regional planners to assist in the achievement of this policy."}},{"id":"PH-H3543-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Pursuant to this policy, the University of the Philippines is hereby authorized to established an Institute of Planning, for which there is hereby authorized to be appropriated four hundred thousand pesos, out of the general funds of the National Treasury not otherwise appropriated, for the construction of buildings and the purchase of equipment and facilities necessary for the establishment of the Institute: Provided, However, That an additional amount of four hundred thousand pesos shall be appropriated annually under the National Economic Council budget in the General Appropriations Act over the five-year period as counterpart fund beginning with the next succeeding fiscal year for the Institute and three hundred fifty thousand pesos annually beginning with the next succeeding fiscal year for operational expenses of the Institute."}},{"id":"PH-H3543-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"An Advisory Council is hereby established composed of the Dean of the University of the Philippines Graduate School of Public Administration, the Dean of the College of Engineering, the Chief of the Division of Planning of the National Economic Council and three members to be appointed by the Board of Regents on recommendation of the President of the University of the Philippines. The Council shall advise the Institute on technical and policy matters."}},{"id":"PH-H3543-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The different departments, agencies, and subdivisions of the Government as well as the government-owned or controlled corporations of the Philippine Government are hereby authorized to utilize savings from any item or items of their appropriation to cover such fees, transportation and other necessary expenses as may be required by their respective officials and employees who shall undergo training in the Institute of Planning."}},{"id":"PH-H3543-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The University of the Philippines may seek or obtain the services of any professional or technical personnel of any agency of the Philippine Government to provide instruction, perform research, and such other activities as may be necessary for the Institute. Such personnel may be given addition compensation in the form of honoraria to be determined by the University of the Philippines upon recommendation of the Institute, any law to the contrary notwithstanding."}},{"id":"PH-H3543-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Appropriation of Funds for Buildings, Facilities, and Operating Expenses of the Institute of Planning Within the University of the Philippines, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3544"] = {"id":"PH-H3544","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4342_1965.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Dueñ 市","en":"An Act Converting Dueñas High School in the Municipality of Dueñas, Province of Iloilo, into a National High School to be Known as Dueñas General Comprehensive High School, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Converting Dueñas High School in the Municipality of Dueñas, Province of Iloilo, into a National High School to be Known as Dueñas General Comprehensive High School, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật chuyển đổi Dueñas High School thành Dueñas General Comprehensive High School","th":"พระราชบัญญัติเปลี่ยนสถานะ Dueñas High School เป็น Dueñas General Comprehensive High School","id":"Undang-Undang mengubah Dueñas High School menjadi Dueñas General Comprehensive High School","ms":"Akta menukar Dueñas High School kepada Dueñas General Comprehensive High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4342","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4342_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3544-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Dueñas High School is hereby converted into a national high school, to be known as Dueñas General Comprehensive High School. Comprehensive curriculum which includes both academic and industrial arts and handicraft courses shall be offered. The Secretary of education is hereby empowered to reorganize the said school accordingly."}},{"id":"PH-H3544-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon organization of Dueñas General Comprehensive High School, the assets, liabilities, personnel, equipment and records of Dueñas High School shall stand transferred to said Dueñas General Comprehensive High School."}},{"id":"PH-H3544-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of the said school in addition to its matriculation and tuition fees, and other revenues."}},{"id":"PH-H3544-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50"};
  FT["PH-H3545"] = {"id":"PH-H3545","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4343_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将阿克兰省班加市镇文图兰萨村文图兰萨村学校的名称变更为Don Edecio S. Venturanza纪念学校的法案","en":"An Act Changing the Name of Venturanza Barrio School in the Barrio of Venturanza, Municipality of Bañga, Province of Aklan, to Don Edecio S. Venturanza Memorial School","orig":"An Act Changing the Name of Venturanza Barrio School in the Barrio of Venturanza, Municipality of Bañga, Province of Aklan, to Don Edecio S. Venturanza Memorial School","vi":"Đạo luật đổi tên Venturanza Barrio School tại Barrio Venturanza, Thị trấn Bañga, Tỉnh Aklan thành Don Edecio S. Venturanza Memorial School","th":"พระราชบัญญัติเปลี่ยนชื่อ Venturanza Barrio School ในบารริโอ Venturanza, เทศบาล Bañga, จังหวัด Aklan เป็น Don Edecio S. Venturanza Memorial School","id":"Undang-Undang mengubah nama Venturanza Barrio School di Barrio Venturanza, Kotamadya Bañga, Provinsi Aklan menjadi Don Edecio S. Venturanza Memorial School","ms":"Akta menukar nama Venturanza Barrio School di Barrio Venturanza, Perbandaran Bañga, Wilayah Aklan menjadi Don Edecio S. Venturanza Memorial School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4343","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4343_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3545-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Venturanza Barrio School in the barrio of Venturanza, Municipality of Bañga, Province of Aklan, is hereby changed to Don Edecio S. Venturanza Memorial School."}},{"id":"PH-H3545-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Venturanza Barrio School in the Barrio of Venturanza, Municipality of Bañga, Province of Aklan, to Don Edecio S. Venturanza Memorial School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3546"] = {"id":"PH-H3546","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4344_1965.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"授予 Jesus B. Pacquing 在达沃省及民答那峨其他省建设、维护和运营广播电台、电视台及国内外无线电通信的特许权法案","en":"An Act Granting the Jesus B. Pacquing a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations, Television Stations and Domestic and International Radio Telecommunications in Davao Province and Other Provinces in Mindanao","orig":"An Act Granting the Jesus B. Pacquing a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations, Television Stations and Domestic and International Radio Telecommunications in Davao Province and Other Provinces in Mindanao","vi":"Đạo luật cấp quyền khai thác cho Jesus B. Pacquing để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh và truyền hình tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Jesus B. Pacquing เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงและวิทยุโทรทัศน์ในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada Jesus B. Pacquing untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio dan televisi di Filipina","ms":"Akta memberikan francais kepada Jesus B. Pacquing untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio dan televisyen di Filipina"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 4344","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4344_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3546-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, Jesus B. Pacquing is hereby granted a franchise, which shall continue in force during the time that the Government has not established similar services in places selected by the grantee, but not to exceed twenty-five years, to construct, maintain and operate for commercial purposes and in the public interest, radio broadcasting stations, television stations, and domestic and international radio telecommunications in Davao Province and in Mindanao: Provided, That this franchise shall be void unless the construction of at least one radio broadcasting station and television station be begun within two years from the date of approval of this Act and be completed within four years from the said date: Provided, further, That the grantee shall provide adequate public service time to enable the Government, through the said radio broadcasting stations, television stations, domestic and international radio telecommunications, to reach the population on important issues; shall assist in the functions of public information and education; shall conform to the ethics of honest enterprise; and shall not use his stations and domestic and international radio telecommunications for the broadcasting and/or telecasting of obscene or indecent language or speech, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of public health, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H3546-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Such provisions of Act Numbered Thirty-eight hundred and forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Thirty-nine hundred and ninety-seven, known as the Radio Broadcasting Law, Commonwealth Act Numbered One hundred and forty-six, known as the Public Service Act, and their amendments, as are applicable to radio broadcasting stations shall be applied, as far as practicable, to the radio broadcasting and television stations referred to in Section one hereof."}},{"id":"PH-H3546-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guarantee full compliance and fulfillment of the conditions under which this franchise is granted."}},{"id":"PH-H3546-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on his real estate, buildings and personal property, exclusive of the franchise, as other persons or corporations are now paying or hereafter may be required by law to pay.\n(b) The grantee shall be liable to pay further all other taxes that may be imposed by the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H3546-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"In the event that the Government should desire to maintain and operate for itself any or all of the stations herein authorized, the grantee shall turn over such station or stations to the Government with all the serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H3546-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play or other matter to be broadcast and/or telecast from his stations; but if any such speech, play or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play or other matter: Provided, That the grantee during any broadcast and/or telecast, may cut off from the air the speech, play or other matter during any broadcast and/or telecast, if the tendency thereof is to propose and/or incite treason, rebellion, or sedition, or the language used therein, or the theme thereof is indecent or immoral."}},{"id":"PH-H3546-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the previous approval of the Congress of the Philippines. Any corporation to which this franchise is sold, transferred or assigned shall be subject to all the conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, or corporation or other commercial or legal entity."}},{"id":"PH-H3546-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Jesus B. Pacquing a Franchise to Construct, Maintain and Operate Radio Broadcasting Stations, Television Stations and Domestic and International Radio Telecommunications in Davao Province and Other Provinces in Mindanao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3547"] = {"id":"PH-H3547","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4345_1965.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":"将奎松省 Lucban 市镇的菲律宾工匠学校与 Lucban 市镇初级中学合并为国立中学，并划拨第 3530 号共和国法授权的一十五万比索予该校","en":"An Act Merging the School for Philippine Craftsmen and the Lucban Municipal Junior High School, Both in the Municipality of Lucban, Province of Quezon, into a National High School and Transferring Thereto the Sum of One Hundred Fifty Thousand Pesos Authorized to be Appropriated Under Republic Act Numbered Thirty-Five Hundred and Thirty","orig":"An Act Merging the School for Philippine Craftsmen and the Lucban Municipal Junior High School, Both in the Municipality of Lucban, Province of Quezon, into a National High School and Transferring Thereto the Sum of One Hundred Fifty Thousand Pesos Authorized to be Appropriated Under Republic Act Numbered Thirty-Five Hundred and Thirty"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4345","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4345_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3547-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The school for Philippine craftsmen created under Republic Act Numbered thirty-five hundred and thirty and the Lucban Municipal Junior High School both in the Municipality of Lucban, Province of Quezon, are hereby merged into a national high school to be known as Lucban National High School under the direct supervision of the Director of Public Schools."}},{"id":"PH-H3547-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The said national high school shall offer general secondary courses."}},{"id":"PH-H3547-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of Education is hereby empowered to promulgate rules and regulations in connection with the operation and administration of the said national high school."}},{"id":"PH-H3547-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All assets and liabilities of the aforesaid school for Philippine craftsmen as well as those of the Lucban Municipal Junior High School are hereby transferred to the Lucban National High School."}},{"id":"PH-H3547-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Subject to civil service laws and regulations, all teachers and employees now employed by the Lucban Municipal Junior High School shall be retained upon merging of the aforesaid two schools into a national high school: Provided, That all teachers and employees to be employed by the Lucban National High School shall receive their compensation in accordance with the classification to be made by the Wage and Position Classification Office."}},{"id":"PH-H3547-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The sum of one hundred fifty thousand pesos authorized to be appropriated under Republic Act Numbered Thirty-five hundred and thirty out of any funds in the National Treasury not otherwise appropriated, is hereby transferred to Lucban National High School for its maintenance and operation. Thereafter, such sums as may be necessary to carry out the purpose of this Act shall be included in the annual General Appropriations Act."}},{"id":"PH-H3547-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Merging the School for Philippine Craftsmen and the Lucban Municipal Junior High School, Both in the Municipality of Lucban, Province of Quezon, into a National High School and Transferring Thereto the Sum of One Hundred Fifty Thousand Pesos Authorized to be Appropriated Under Republic Act Numbered Thirty-Five Hundred and Thirty","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3548"] = {"id":"PH-H3548","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4346_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将甲米地省拜伦市镇的名称变更为埃米利奥·阿吉纳尔多将军市镇的法案","en":"An Act Changing the Name of the Municipality of Bailen in the Province of Cavite to the Municipality of General Emilio Aguinaldo","orig":"An Act Changing the Name of the Municipality of Bailen in the Province of Cavite to the Municipality of General Emilio Aguinaldo","vi":"Đạo luật đổi tên Thị trấn Bailen tại Tỉnh Cavite thành Thị trấn General Emilio Aguinaldo","th":"พระราชบัญญัติเปลี่ยนชื่อเทศบาล Bailen ในจังหวัด Cavite เป็นเทศบาล General Emilio Aguinaldo","id":"Undang-Undang mengubah nama Kotamadya Bailen di Provinsi Cavite menjadi Kotamadya General Emilio Aguinaldo","ms":"Akta menukar nama Perbandaran Bailen di Wilayah Cavite menjadi Perbandaran General Emilio Aguinaldo"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4346","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4346_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3548-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of Bailen in the Province of Cavite is hereby changed to the Municipality of General Emilio Aguinaldo."}},{"id":"PH-H3548-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Municipality of Bailen in the Province of Cavite to the Municipality of General Emilio Aguinaldo","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3549"] = {"id":"PH-H3549","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4347_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将甲米地省罗萨里奥市镇特赫罗村特赫罗村学校的名称改为特赫罗斯会议小学的法案","en":"An Act to Modify the Name of Tejero Barrio School in Barrio Tejero, Municipality of Rosario, Province of Cavite to Tejeros Convention Elementary School","orig":"An Act to Modify the Name of Tejero Barrio School in Barrio Tejero, Municipality of Rosario, Province of Cavite to Tejeros Convention Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4347","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4347_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3549-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Tejero Barrio School in Barrio Tejero, Municipality of Rosario, Province of Cavite, is hereby changed to Tejeros Convention Elementary School."}},{"id":"PH-H3549-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Modify the Name of Tejero Barrio School in Barrio Tejero, Municipality of Rosario, Province of Cavite to Tejeros Convention Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3550"] = {"id":"PH-H3550","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4348_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将甲米地省罗萨里奥市镇特赫罗村的名称变更为特赫罗斯会议村的法案","en":"An Act Changing the Name of Barrio Tejero in the Municipality of Rosario, Province of Cavite, to Barrio Tejeros Convention","orig":"An Act Changing the Name of Barrio Tejero in the Municipality of Rosario, Province of Cavite, to Barrio Tejeros Convention","vi":"Đạo luật đổi tên Barrio Tejero tại Thị trấn Rosario, Tỉnh Cavite thành Barrio Tejeros Convention","th":"พระราชบัญญัติเปลี่ยนชื่อบารริโอ Tejero ในเทศบาล Rosario, จังหวัด Cavite เป็นบารริโอ Tejeros Convention","id":"Undang-Undang mengubah nama Barrio Tejero di Kotamadya Rosario, Provinsi Cavite menjadi Barrio Tejeros Convention","ms":"Akta menukar nama Barrio Tejero di Perbandaran Rosario, Wilayah Cavite menjadi Barrio Tejeros Convention"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4348","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4348_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3550-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Barrio Tejero in the Municipality of Rosario, Province of Cavite, is hereby changed to Barrio Tejeros Convention."}},{"id":"PH-H3550-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of Barrio Tejero in the Municipality of Rosario, Province of Cavite, to Barrio Tejeros Convention","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3551"] = {"id":"PH-H3551","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4349_1965.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"设立Estancia市","en":"An Act Converting the Western Visayas School of Fisheries in the Municipality of Estancia, Province of Iloilo, into a College to be Known as the Western Visayas College of Fisheries, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Converting the Western Visayas School of Fisheries in the Municipality of Estancia, Province of Iloilo, into a College to be Known as the Western Visayas College of Fisheries, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật chuyển đổi Western Visayas School of Fisheries thành Western Visayas College of Fisheries","th":"พระราชบัญญัติเปลี่ยนสถานะ Western Visayas School of Fisheries เป็น Western Visayas College of Fisheries","id":"Undang-Undang mengubah Western Visayas School of Fisheries menjadi Western Visayas College of Fisheries","ms":"Akta menukar Western Visayas School of Fisheries kepada Western Visayas College of Fisheries"},"level":"law","status":"active","topics":["environment","education"],"docNumber":"Republic Act No. 4349","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4349_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3551-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Western Visayas School of Fisheries located in the Municipality of Estancia, Province of Iloilo, is hereby converted into a college to be known as the Western Visayas College of Fisheries."}},{"id":"PH-H3551-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Western Visayas College of Fisheries shall offer, in addition to the secondary fishery curriculum, collegiate course leading to the title of Association in Fishery Education and the degree of Bachelor of Science in Fisheries. It shall also offer special courses, such as fishpond management, fisheries homemaking, fish culture, fish capture and fish preservation."}},{"id":"PH-H3551-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Western Visayas College of Fisheries shall be headed by a superintendent of fishery and shall be under the Bureau of Vocational Education. The superintendent shall have the direct administration and supervision of this college."}},{"id":"PH-H3551-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The physical and financial assets, liabilities, personnel, equipment, and records of the Western Visayas School of Fisheries are hereby transferred to the Western Visayas College of Fisheries."}},{"id":"PH-H3551-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The sum of five hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the conversion, operation and maintenance of the said college in addition to the present appropriation of the Western Visayas School of Fisheries for the fiscal year nineteen hundred sixty-six. Thereafter, the sum needed for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3551-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50"};
  FT["PH-H3552"] = {"id":"PH-H3552","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4350_1965.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订宿务市修订宪章的法案","en":"An Act Amending the Revised Charter of the City of Cebu","orig":"An Act Amending the Revised Charter of the City of Cebu","vi":"Đạo luật sửa đổi Hiến chương Thành phố Cebu (bản sửa đổi)","th":"พระราชบัญญัติแก้ไขเพิ่มเติมกฎบัตรเมือง Cebu (ฉบับแก้ไข)","id":"Undang-Undang mengubah Piagam Kota Cebu (Revisi)","ms":"Akta meminda Piagam Bandar Cebu (Semakan)"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4350","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4350_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3552-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section forty-one of Republic Act Numbered Thirty-eight hundred and fifty-seven, otherwise known as the Revised Charter of the City of Cebu, is amended to read as follows:\n\"Sec. 41. The clerk of city court—his duties—deputy clerks of court.— The clerk of the city court shall keep its seal and affix it to all orders, judgments, certificates, records and other documents issued by the court. He shall keep a docket of the trials in the court, in which he shall record in a summary manner the name of the defendant, the charge against him, the names of the prosecuting witnesses, the date of arrest, the appearance of the defendant, the date of the trial, and the nature of the judgment, together with the fines and costs adjudged or collected in accordance with said judgment. He shall have the power to administer oaths. He shall receive a salary of seven thousand eight hundred pesos per annum.\n\"The clerk of the city court shall be assisted by three deputy clerks of court, who shall each receive a salary of five thousand four hundred pesos per annum, and such other assistants and employees as the City Council shall provide.\""}},{"id":"PH-H3552-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The clerk of court and his deputies appointments have already been approved by the authorities concerned prior to the approval of this Act, shall automatically be entitled to the benefits of this Act without further needs of appointment."}},{"id":"PH-H3552-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending the Revised Charter of the City of Cebu","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3553"] = {"id":"PH-H3553","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4351_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将三描礼士省圣克鲁斯市镇卢卡蓬村Lucapon北小学的名称变更为Don Brigido Miraflor小学的法案","en":"An Act to Change the Name of Lucapon North Elementary School in Barrio Lucapon, Municipality of Santa Cruz, Province of Zambales, to Don Brigido Miraflor Elementary School","orig":"An Act to Change the Name of Lucapon North Elementary School in Barrio Lucapon, Municipality of Santa Cruz, Province of Zambales, to Don Brigido Miraflor Elementary School","vi":"Đạo luật đổi tên Trường Tiểu học Lucapon North tại Barrio Lucapon, Đô thị Santa Cruz, Tỉnh Zambales thành Trường Tiểu học Don Brigido Miraflor","th":"พระราชบัญญัติเปลี่ยนชื่อโรงเรียนประถมศึกษา Lucapon North ในบารังไกย์ Lucapon เทศบาล Santa Cruz จังหวัด Zambales เป็นโรงเรียนประถมศึกษา Don Brigido Miraflor","id":"Undang-Undang Mengubah Nama Sekolah Dasar Lucapon North di Barrio Lucapon, Kotamadya Santa Cruz, Provinsi Zambales menjadi Sekolah Dasar Don Brigido Miraflor","ms":"Akta Menukar Nama Sekolah Rendah Lucapon North di Barrio Lucapon, Perbandaran Santa Cruz, Wilayah Zambales kepada Sekolah Rendah Don Brigido Miraflor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4351","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4351_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3553-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of Lucapon North Elementary School in Barrio Lucapon, Municipality of Santa Cruz, Province of Zambales, is hereby changed to Don Brigido Miraflor Elementary School."}},{"id":"PH-H3553-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Change the Name of Lucapon North Elementary School in Barrio Lucapon, Municipality of Santa Cruz, Province of Zambales, to Don Brigido Miraflor Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3554"] = {"id":"PH-H3554","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4352_1965.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在南莱特省Sogod市镇设立国立贸易学校，名称为Sogod国立贸易学校，并授权为此拨款的法案","en":"An Act to Provide for the Establishment of a National Trade School in the Municipality of Sogod, Province of Southern Leyte, to be Known as Sogod National Trade School, and to Authorize the Appropriation of Funds Therefor","orig":"An Act to Provide for the Establishment of a National Trade School in the Municipality of Sogod, Province of Southern Leyte, to be Known as Sogod National Trade School, and to Authorize the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["trade","education"],"docNumber":"Republic Act No. 4352","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4352_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3554-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Director of Vocational trade school in the Municipality of Sogod, Province of Southern Leyte, to be known as Sogod National Trade School."}},{"id":"PH-H3554-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Director of Vocational Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H3554-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said school for fiscal year nineteen hundred sixty-six. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H3554-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide for the Establishment of a National Trade School in the Municipality of Sogod, Province of Southern Leyte, to be Known as Sogod National Trade School, and to Authorize the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3555"] = {"id":"PH-H3555","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4353_1965.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予圣奥古斯丁大学在伊洛伊洛市设立、维护和运营无线电广播站的特许经营权法案","en":"An Act Granting the University of San Agustin a Franchise to Establish, Maintain and Operate a Radio Broadcasting Station in the City of Iloilo","orig":"An Act Granting the University of San Agustin a Franchise to Establish, Maintain and Operate a Radio Broadcasting Station in the City of Iloilo","vi":"Đạo luật cấp quyền khai thác cho University of San Agustin để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh tại Thành phố Iloilo","th":"พระราชบัญญัติให้สัมปทานแก่ University of San Agustin เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงในเมือง Iloilo","id":"Undang-Undang memberikan waralaba kepada University of San Agustin untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio di Kota Iloilo","ms":"Akta memberikan francais kepada University of San Agustin untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio di Bandaraya Iloilo"},"level":"law","status":"active","topics":["investment","education"],"docNumber":"Republic Act No. 4353","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4353_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3555-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to provisions of the Constitution, as well as of Act Numbered thousand eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Three thousand nine hundred ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act and their amendments, and other applicable laws not inconsistent with this Act, San Agustin University is hereby granted a franchise to establish, maintain and operate a radio broadcasting station in the City of Iloilo."}},{"id":"PH-H3555-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the approval of this Act, and is granted upon the express condition that it shall be void unless the construction of such radio station be begun within six months from the date of approval of this Act and competed within two years from said date."}},{"id":"PH-H3555-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This franchise is likewise granted upon the express condition that the grantee shall contribute to the public welfare, assist in the function of public information and education, conform to the ethics of honest enterprises, and shall not use its station for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of public health, or to incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H3555-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee’s radio broadcasting station shall not be put in actual operation until the Secretary of Public Works and Communications shall have allotted to the grantee the frequency and wave length to be used under this franchise and issued to the grantee a license for such use."}},{"id":"PH-H3555-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The radio broadcasting station of the grantee shall be so constructed and operated and the wave length so selected as to avoid interference with existing radio stations and thereby permit the expansion of the grantee’s service."}},{"id":"PH-H3555-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace or order, to cause the closing of said station or to authorize the temporary use and operation thereof by any department of the Government without compensating the grantee for such use during the period when they shall be so operated."}},{"id":"PH-H3555-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall be liable to pay the same taxes, unless exempted therefrom, on its real estate, buildings, and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay."}},{"id":"PH-H3555-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H3555-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Acceptance of this franchise shall be given to writing by the grantee within six months after the approval of this Act. When so accepted, the grantee shall be empowered to exercise the privilege granted thereby."}},{"id":"PH-H3555-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall not lease, transfer grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first hand."}},{"id":"PH-H3555-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the University of San Agustin a Franchise to Establish, Maintain and Operate a Radio Broadcasting Station in the City of Iloilo","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3556"] = {"id":"PH-H3556","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4354_1965.html","fetchedAt":"2026-10-06","articleCount":70,"structureMode":"ARTICLE","title":{"zh":"达沃市宪章（修订）","en":"An Act to Reverse the Charter of the City of Davao and for Other Purposes","orig":"An Act to Reverse the Charter of the City of Davao and for Other Purposes","vi":"Hiến chương Thành phố Davao (sửa đổi)","th":"กฎบัตรเมือง Davao (ฉบับแก้ไข)","id":"Piagam Kota Davao (Revisi)","ms":"Piagam Bandaraya Davao (Semakan)"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4354","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 70 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4354_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3556-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act shall be known as the Revised Charter of the City of Davao.\nThe City as a Public Corporatio n"}},{"id":"PH-H3556-A2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Territory of the City. The City of Davao as created by Commonwealth Act Numbered Fifty-one, as amended, shall comprise the territories of the former Municipality of Davao and then Municipal District of Guianga and shall include the following barrios: Agdao Beach, Bucana, Baguio, Biao Joaquin, Cadalian, Calinan Carmen, Cawayan, Dacudao, Dalag, Dominga, Gumalang, Dalagdag, Lacson, Lamanan, Lampianao, Malagos, Malamba, Marilog, Pangyan, Riverside, Salaysay, Sirib, Suawan, Subasta, Suminao, Talomo River, Tambobong, Tamugan, Tamayong, Tawan-Tawan, Wangan, Wines, Alambre, Atan Awe, Bago Gallera, Baliok, Bangkas Heights, Baracatan, Bato, Bayabas, Binugao, Camansi, Catigan, Crossing Bayabas, Daliao, Dumoy, Eden, Lizada, Kilate, Langub, Lubogan, Ma-a, Magtuod, Marapangi, Matina Crossing, Matina Aplaya, Matina Pangi, Mulig, Sibulan, Sirawan, Tagluno, Tagurano, Talomo, Tibuloy, Toril, Tungkalan, Daliaon Plantalion, Acacia, Fatima (Binowang) Buhangin, Bunawan, Cabantian, Colasas, Communal, Gatungan, Ilang, Indangan, Lasang, Lumiad, Mabuhay, Mahayag, Malabog, Mandug, Mapula, Mudiang, Pampanga, Panacan, Panalom, Paquibato, Paradise Ombac, Pandaitan, Salapawan, San Isidro, Basa, Tapak, Tibungco, Tigatto, Bago Oshiro, Balengaeng, Biao Escuela, Biao, Guianga, Callawa, Catalunan Grande, Catalunan Pequeno, Manambulan, Manuel Guianga, Matina Biao, Mintal, New Carmen, New Valencia, Tacunan, Talandang, Tagakpan, Tugbok, Los Amigos, and Ula."}},{"id":"PH-H3556-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Corporate character. The City of Davao constitutes a political body corporate and as such is endowed with the attribute of perpetual succession and possessed of the powers which pertain to a municipal corporation, to be exercised in conformity with the provisions of this charter."}},{"id":"PH-H3556-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE I"},"text":{"en":"General powers. The City shall have a common seal and may alter the same at pleasure, and may take, purchase, receive, hold, lease, convey, and dispose of real and personal property for the general interests of the city, condemn private property for public use, contract and be contracted with, sue and be sued, and prosecute as well as defend to final judgment and execution, actions where its interests are involved, and exercise all the powers hereinafter conferred."}},{"id":"PH-H3556-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Liability for damages. The city shall not be liable or held for damages or injuries to persons or property arising from the failure of the mayor, the city council or any other city officer or employee, to enforce the provisions of this charter, or of any other law or ordinance, or from the negligence of said mayor, or council or other city officers or employees while enforcing or attempting to enforce said provisions: Provided , That nothing herein contained shall prevent any aggrieved party from filing a personal action in the proper court against any official or employee of the city government for any act or omission in the performance of the duties in accordance with law."}},{"id":"PH-H3556-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Jurisdiction of the city. The jurisdiction of the City of Davao for police purposes only shall be co-extensive with its territorial jurisdiction; and shall extend to three miles from the shores of the city; and for the purpose of protecting and insuring the purity of the water supply of the city, such police jurisdiction shall also extend over all territory within the drainage area of such water supply, or within one hundred meters of any reservoir, conduit, canal, aqueduct or pumping station used in connection with the city water service. The city court of the city shall have concurrent jurisdiction with the municipal court of the respective municipalities to try crimes and misdemeanors committed within said drainage area, or within said spaces of one hundred meters. The court first taking jurisdiction of such an offense shall thereafter retain exclusive jurisdiction thereof. The police force of the several municipalities concerned shall have concurrent jurisdiction with the police force of the city for the maintenance of good order and the enforcement of ordinances throughout said zone, area and spaces. But any license that may be issued within said zone, area or spaces shall be granted by the proper authorities of the municipality concerned, and the fees arising therefrom shall accrue to the treasury of the said municipality concerned and not to that of the city.\nThe Mayor and the Vice-Mayor"}},{"id":"PH-H3556-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE II"},"text":{"en":"The Mayor. The Mayor shall be the chief executive of the city. He shall be elected at large by the qualified voters of the city. No person shall be eligible for the position of mayor unless at the time of the election he is at least twenty-five years of age, a resident of the city for at least two years prior to his election, and a qualified voter therein. He shall hold office for four years, unless sooner removed, and shall receive a salary of eighteen thousand pesos per annum. In addition to his salary, he shall be entitled to a commutable allowance for representation and quarters which shall not be less than ten thousand pesos per annum."}},{"id":"PH-H3556-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE II"},"text":{"en":"The Vice-Mayor. There shall be elected a vice-mayor who shall perform the duties and exercise the powers of the Mayor, in the event of the death, sickness, absence or other temporary incapacity of the Mayor, or in the event of a definite vacancy in the position of Mayor, until said office shall be filled, in accordance with law. The Vice-Mayor shall be elected in the same manner as the Mayor and shall at the time of his election possess the same qualifications as the mayor.\nIf for some reason the vice-mayor is incapacitated from assuming the office of mayor or refuses to assume such office, the councilor who obtained the largest number of votes in the local elections immediately preceding shall assume the office of mayor. If for some reason the councilors who obtained the highest number of votes in the local elections immediately preceding is incapacitated from assuming the office of mayor or refuses to assume such office, the councilor who obtained the next largest number of votes in the local elections immediately preceding shall assume the office of mayor, and so on until the permanent vacancy in the office of the mayor is filled.\nShould the mayor-elect die before assumption of office or failed to qualify for any reason, the vice-mayor-elect shall assume the office of mayor, but in the latter case, he shall hold office only until after the mayor-elect qualifies. If for some reason the vice-mayor is incapacitated from assuming the office of mayor or refuses to assume such office, the councilor-elect who obtained the largest number of votes in the local elections immediately preceding shall assume office of mayor, and so on until the office of mayor is filled.\nIn the event of temporary incapacity of the mayor to perform the duties of his office on account of absence on leave, sickness or any temporary incapacity, the vice-mayor shall perform the duties and exercise the powers of the mayor except the power to appoint, suspend or dismiss employees. In the event the vice-mayor is temporarily incapacitated to perform the duties of the office of mayor, the councilor who obtained the largest number of votes among the incumbent councilors in the local elections immediately preceding shall assume the duties and exercise the powers of the mayor except the power to appoint, suspend or dismiss employees.\nThe vice-mayor shall perform, such other duties as may be assigned to him by the mayor or prescribed by law or ordinance. He shall receive a salary of fifteen thousand pesos per annum."}},{"id":"PH-H3556-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE II"},"text":{"en":"General powers and duties of the Mayor. As chief executive of the city government, the mayor shall have immediate control over the executive and administrative functions of the different departments, subject to the supervision of the President of the Philippines, and shall be held accountable for the administration of all affairs of the city. He shall have the following powers and duties:\n(a) To comply with and enforce and give the necessary orders for the faithful and proper enforcement and execution of the laws and city ordinances and resolutions in effect within the jurisdiction of the city.\n(b) To safeguard all the lands, buildings, records, moneys, credits, and other property and rights of the city, and have control of all its property.\n(c) To see that all taxes and other revenues of the city are collected, and the city funds applied in accordance with appropriations to the payment of the municipal expenses.\n(d) To cause to be instituted judicial proceedings to recover property and funds of the city wherever found, to cause to be defended all suits against the city, and otherwise to protect the interest of the city.\n(e) To see that the officers and employees of the city properly discharge their respective duties.\n(f) To examine and inspect the books, records, and papers of all executive or administrative officers, agents, and employees of the city whenever occasion arises, and at least once a year. For this purpose he shall be provided by the City Council with such clerical and other assistance as may be necessary.\n(g) To give such information and recommend such measures to the Council as he shall deem advantageous to the city.\n(h) To represent the city in all its business matters, and sign on its behalf all its bonds, contracts, and obligations made in accordance with law or ordinance.\n(i) To submit to the City Council on or before the thirtieth day of April of each year a budget or receipts and expenditures of the city.\n(j) To receive, hear, and decide as he may deem proper the petitions, complaints, and claims concerning all classes of municipal matters of an administrative or executive character.\n(k) To grant or refuse municipal licenses or permits of all classes and to revoke same, in conformity with the provisions of laws and ordinances, or for violation of the conditions upon which they were granted, or if acts prohibited by law or municipal ordinances are being committed under the protection of such licenses or in the premises in which the business for which the same have been granted is carried on, or for any other good reason of general interest.\n(l) To determine according to law or ordinance the time, manner, and place of payment of the salaries and wages of the officers and employees of the city.\n(m) To exempt, with the concurrence of the division superintendent of schools, deserving poor pupils from the payment of school fees or any part thereof.\n(n) To make all appointments of city officials and employees except as otherwise provided in this charter.\n(o) To take such emergency measures as may be necessary to avoid fires, floods, and the effects of storms and other public calamities.\n(p) To render an annual report to the office of the President of the Philippines.\n(q) To exercise the power of veto, but any vetoed ordinance or resolution may be repassed by a two-thirds vote of all the members of the Council.\n(r) To perform such other duties and exercise such other executive powers as may be prescribed by law or ordinance."}},{"id":"PH-H3556-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE II"},"text":{"en":"City secretary. There shall be a city secretary who shall be appointed by the mayor; and who shall receive a salary of twelve thousand pesos per annum. He shall be considered as head of a city department and as such he shall have the following duties:\n(a) He shall act as secretary of the City Board of Assessment Appeals, and such other boards or committees as may hereafter be created by law or ordinance, and shall keep a journal of their proceedings.\n(b) He shall have charge of all records and documents of the city for which provision is not otherwise made.\n(c) He shall keep the corporate seal and affix the same with his signature to all official acts of the mayor and to all other official documents and papers of the government of the city as may be required by custom or usage, in the discretion of the mayor.\n(d) He shall be the local civil registrar and shall keep a civil register for the city and record therein all births, marriages, and deaths with their respective dates.\n(e) He shall perform such other duties as the mayor may direct or as may be required of him by law or ordinance.\n(f) He shall attest all orders, proclamation, ordinances and resolutions signed by the mayor.\n(g) He shall, on demand, furnish certified copies of all records and documents in his charge which are not of a confidential character and shall collect twenty centavos for each one hundred words including the certification, and all receipts shall be paid into the city treasury. He shall likewise perform with respect to his office, the duties similar to those imposed on heads of departments of the city government by Section nineteen hereof.\nThe City Council"}},{"id":"PH-H3556-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Constitution and organization of the City Council. The City Council shall be the legislative body of the city, and shall be composed of the vice-mayor, who shall be its presiding officer, and ten councilors who shall be elected at large by the qualified voters of the city.\nIf the vice-mayor or a member of the City Council shall be a candidate for office in any election, he shall be disqualified to act with said body in the performance of the duties thereof relative to such election, and if, for such reason, the number of members should be unduly reduced, the President shall appoint any disinterested voter of the city, belonging to the political party of the disqualified member, to act in his place in such matters.\nThe members of the City Council shall each receive a salary of twelve thousand pesos per annum."}},{"id":"PH-H3556-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Qualifications, election, suspension and removal of members. The members of the City Council shall, at the time of their election, be qualified electors of the city, residents thereof for at least two years immediately prior to their election and not less than twenty-three years of age. Such members may be suspended or removed from office under the same circumstances, in the same manner, and with the same effect, as elective provincial officers, and the provisions of law governing the suspension or removal of elective provincial officers are hereby made applicable in the suspension or removal of said members.\nElections for members of the Council shall be held on the date of the regular election for provincial and city officials, and elected members shall assume office on the first day of January next following their election, upon qualifying and shall hold office for four years. The ten candidates receiving the highest number of votes shall be declared elected.\nA vacancy of the City Council shall be filled in accordance with the provisions of the Revised Election Code."}},{"id":"PH-H3556-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE III"},"text":{"en":"The presiding officer of the City Council. The vice-mayor shall be the presiding officer of the Council. In his absence, the Council shall elect one of its members as temporary presiding officer. He shall sign all ordinances, and all resolutions and motions directing the payment of money or creating liability, enacted or adopted by the Council."}},{"id":"PH-H3556-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Secretary of the City Council. The City Council shall have a secretary who shall be elected by the Council to serve during the term of office of the members unless sooner removed. His compensation as secretary shall be not less than twelve thousand pesos per annum. The secretary shall have the following duties:\n(a) He shall act as secretary of the City Council and shall be in charge of the records thereof.\n(b) He shall keep a full record of the proceedings of the Council and shall file all documents relative thereto.\n(c) He shall record in a book kept for the purpose all ordinances and resolutions and motions directing the payment of money or creating liability enacted or adopted by the Council, with the dates of approval of the same, and of the publication of the ordinances.\n(d) He shall keep a seal, circular in form with the inscription \"City Council City of Davao\" and affix the same, with his signature, to all ordinances and official acts of the council, which he shall present for signature to the presiding officer of the Council.\n(e) He shall cause each ordinance passed by the Council to be published.\n(f) He shall furnish on demand, certified copies of all records of public character in his charge, and collect and receive therefor such fees as may be prescribed by ordinance or resolution of the Council.\n(g) He shall keep his office and all records therein which are not of a confidential character open to public inspection during the usual business hours."}},{"id":"PH-H3556-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Legislative procedure. The Council shall hold two regular sessions for the transaction of its business during each week on days which it shall fix by resolution, and such special sessions as may be called by the mayor and/or vice-mayor as public interest so requires. It shall sit with open doors unless otherwise ordered by the affirmative vote of a majority of all the members. It shall keep a record of all its proceedings and determine its rules of procedure not herein set forth. A majority of all the members of the Council shall constitute a quorum for the transaction of business, but a smaller number may adjourn from day to day and may compel the immediate attendance of any member who is absent without good cause by issuing to the police of the city an order for his arrest and production at the session under such penalties as shall have been previously prescribed by ordinance. The affirmative votes of a majority of all the members shall be necessary for the passage of any ordinance, or of any resolution or motion directing the payment of money or creating liability, but other measures shall prevail upon the majority votes of the members present at any session duly called and held. The ayes and nays shall be taken and recorded upon the passage of all ordinances, upon all resolutions or motions directing the payment of money or creating liability, and, at the request of any member, upon any other resolution or motion. Each approved ordinance, resolution or motion shall be sealed with the seal of the City Council, and recorded in a book kept for the purpose and shall, on the day following its passage, be posted by the secretary at the main entrance of the city hall and in at least two other public places; and shall take effect and be in force on and after the tenth day following its passage unless otherwise stated in said ordinance, resolution or motion or vetoed by the mayor as hereinafter provided. A vetoed ordinance, if repassed, shall take effect ten days after the veto is overridden by the required votes unless otherwise stated in the ordinance, resolution or motion or again disapproved by the mayor.\nEach ordinance and each resolution or motion directing the payment of money or creating liability, enacted or adopted by the Council, shall be forwarded to the mayor for his approval. Within ten days after the receipt of the ordinance, resolution or motion, the mayor shall return it with his approval or veto. If he does not return it within that time, it shall be deemed to be approved. If he returns it with his veto, his reasons therefor in writing shall accompany it. It may then again be enacted by a two-thirds vote of all the members of the Council, and again forwarded to the mayor for his approval, and if within ten days after its receipt he does not return it with his veto, it shall be deemed to be approved. If within said time he again returns it with his veto, it shall be forwarded forthwith to the President for his approval or disapproval which shall be final.\nThe mayor shall have the power to veto any particular item or items of an appropriation ordinance, or of an ordinance, resolution or motion directing the payment of money or creating liability, but the veto shall not affect the item or items to which he does not object. The item or items objected to shall not take effect except in the manner heretofore provided in this section as to ordinances, resolutions or motions returned to the City Council with his veto; but should an item or items in an appropriation ordinance be disapproved by the mayor, the corresponding item or items in the appropriation ordinances of the previous year shall be deemed re-enacted."}},{"id":"PH-H3556-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Legislative powers. The City Council shall have the following legislative powers:\n(a) To provide for the levy and collection of taxes for general and special purposes in accordance with law, including specifically the power to levy real property tax not to exceed two per centum on the assessed value of the real property.\n(b) To fix the number and salaries of officials and employees of the city not otherwise provided for in this Act.\n(c) To fix the tariff of fees and charges for all services rendered by the city or any of its departments, branches or officials.\n(d) To provide for the erection and maintenance or the rental, in case of need, of the necessary buildings for the use of the city.\n(e) To establish and maintain or aid in the establishment and maintenance of vocational schools and institutions of higher learning conducted by the National Government or any of its subdivisions or agencies; and, with the approval of the Director of Public Schools, to fix reasonable tuition fees for instruction in the vocational schools and in the institutions of higher learning supported by the city.\n(e-1) To provide for the establishment and maintenance of high school, and, except as otherwise provided by law, to fix, with the approval of the Director of Public Schools, reasonable matriculation and/or tuition fees for intermediate and secondary institution therein and to acquire sites for schoolhouses for primary and intermediate classes through purchases or conditional or absolute donations.\n(f) To provide for and maintain an efficient police force for the maintenance of law and order in the city, and make all necessary police ordinances, with a view to the confinement and reformation of vagrants, disorderly persons, mendicants, prostitutes and persons convicted of violating any of the ordinances of the city.\n(g) To maintain the city court established by law which shall have jurisdiction of all criminal cases under the ordinances of the city, and such further jurisdiction as may be herein or hereafter conferred by law or ordinance.\n(h) To provide for and maintain a city fire department and to establish and maintain engine houses, fire engines, hose trucks, hooks and ladders, and other equipment for the prevention and extinguishment of fires, and to regulate the management and use of the same.\n(i) To establish fire zones, determine the kinds of buildings or structures that may be erected within their limits, regulate the manner of constructing and repairing the same, and fix the fees for permits for the construction, repair, or demolition of buildings and other structures.\n(j) To regulate the use of lights and installation of stables, lights in shops, and other buildings used for industrial, commercial establishments and other public places, to regulate and restrict the issuance of permits for the building of bonfires and rockets, and other pyrotechnic displays, and to fix the fees for such permits.\n(k) To make regulations to protect the public from conflagrations and to prevent and mitigate the effects of famine, floods, storms and other public calamities, and provide relief for victims thereof.\n(l) To tax, regulate and fix the amount of the license fees for the following: hawkers, peddlers, hucksters, barbers, collecting agencies, manicurists, hair dressers, tattooers, jugglers, acrobats, wrestlers and boxers; shooting galleries, merry-go-rounds and other similar riding devices, and the keeping, preparation, and sale of meat, poultry, fish, game, butter, cheese, lard, vegetable, bread, and other similar foodstuffs, and to impose occupation or professional tax, not to exceed fifty pesos per annum, on lawyers, medical practitioners, land surveyors, architects, public accountants, civil, electrical, chemical, mechanical, or mining engineers, radio engineers or technicians, veterinarians, dental surgeons, opticians and optometrists, insurance agents and sub-agents, business agents and business consultants, professional appraisers or connoisseurs of tobacco or other domestic or foreign products, music teachers, piano tuners, nurses, and midwives, embalmers, auctioners, plumbers, electrical contractors, building contractors, masseurs, physical culture instructors, chiropodists, money changers, real estate, commercial and other brokers, and persons engaged in the transportation of passengers or freight by hire, including common carriers and transportation contracts: Provided , That persons exercising their professions or occupations only as salaried employees and not as independent practitioners shall be exempt from the municipal occupation tax herein prescribed.\n(m) To tax, fix the license fee and regulate the business of hotels, restaurants, refreshment places, cafes, lodging houses, brewers, distillers, rectifiers, laundries, dyeing and cleaning establishment, beauty parlors, physical or beauty culture and fashion schools, clubs, livery garages, public warehouses, pawnshops, theaters, cinematographs, and the letting or subletting of lands and buildings, whether for commercial, industrial or residential purposes; and further to fix the location of, and to tax, fix the license fee on, and regulate the business of, livery stables, boarding stables, embalmings, billiard and pool parlors, public pool tables, bowling alleys, dance halls, public dancing halls, cabarets, night clubs, circuses and other similar shows, public vehicles, public ferries, cockpits, dealers in second hand materials or merchandise, junk dealers, theatrical performances, boxing contests, public exhibitions, blacksmith shops, foundries, steam boilers, lumber yards, shipyards, the storage and sale of gunpowder, tar, pitch resin, coal, oil, gasoline, benzine, turpentine, hemp, cotton, nitroglycerin, petroleum or any of the products thereof and of all other highly combustible or explosive materials, and other establishments likely to endanger the public safety or give rise to conflagrations or explosions, and, subject to the provisions of rules and regulations issued by the Bureau of Health Services in accordance with law, tanneries, fats and oils factories, tallow chandleries, bone factories, and soap factories: Provided , That no license shall be granted to any theater or cinematograph unless the applicant for said license agrees to exhibit pictures made in the Philippines to the extent of five per centum of their annual exhibitions: And, provided, further , That any violation of this condition shall cause the revocation of said license.\n(n) To tax and fix the license fees on printers or bookbinders or both, tailor shops, milliners, manufacturers of jewelry, embroideries, sail or awnings or both, ropes, papers, leather goods, including shoes, slippers, sandals, harnesses and valises or bags, sporting goods, rubber goods, plastics and celluloid products, hardware including glasswares, cooking utensils, electrical goods and construction materials, chemical products including drugs, perfumes, toilet articles, paints, dyes and inks, textiles, shell lamps or lamp shades or both, statuettes or tombstones or both, sacks, furniture of all kinds, including rattan goods, wire, brass beds or both, clothing, hats, eyeglasses or optical goods or both, fertilizers or buttons.\n(o) To tax and fix the license fee on dealers in general merchandise, including importers and indentors, except those dealers who may be expressly subject to the payment of some other municipal tax under the provisions of this section.\nDealers in general merchandise shall be classified as (a) wholesale dealers and (b) retail dealers. Dealers shall pay the license tax as such, as may be provided by ordinance.\nFor purposes of this section, the term \"general merchandise\" shall include poultry and livestock, agricultural products, fish and other allied products.\n(p) To tax, fix the license fee on and regulate the sale, trading in or disposal of alcoholic or malt beverages, wines, and mixed or fermented liquors, including tuba, basi, and tapuy, offered for retail sale.\n(q) To impose a tax on all products or commodities manufactured or produced in the city and removed therefrom.\n(r) To impose a sales tax of not exceeding one per centum of the gross value in money of all articles sold, bartered, exchanged or transferred within the city.\n(s) To regulate the methods of using steam engines and boilers, and all other motive powers other than marine, or belonging to the Government of the Philippines, to provide for the inspection thereof, and fix a reasonable fee for such inspection and to regulate and fix the fees for the licenses of the engineers engaged in operating the same.\n(t) To provide for the prohibition and suppression of riots, affrays, disturbances, and disorderly assemblies; houses of ill-fame and other disorderly houses; gambling houses; gambling and all fraudulent devices for the purpose of obtaining money or property; prostitution, vagrancy, intoxication, fighting, quarreling, and all disorderly conduct; and printing, circulation, exhibition, possession or sale of obscene or pornographic pictures, books, or publications, and for the maintenance and preservation of peace and good morals.\n(u) To regulate and fix the license fees for the keeping of dogs, and to authorize their impounding and destruction when running at large contrary to ordinances, and to tax and regulate the keeping or training of fighting cocks.\n(v) To establish and maintain municipal pounds; to regulate, restrain, and prohibit the running at large of domestic animals, and provide for the distraining, impounding, and sale of the same for the penalty incurred, and the cost of the proceedings; and to impose penalties upon the owners of said animals for the violation of any ordinance in relation thereto.\n(w) To prohibit and provide for the punishment of cruelty to animals.\n(x) To require property owners by ordinance to construct or repair, at their expense, sidewalks along the street or streets adjacent to their lots in accordance with the specifications of the city engineer as to quality, width and grade, and subject to his supervision and approval, providing that, in case of failure or inability of the property owners to comply with the requirement within a specified period of time after demand, the city engineer shall cause the work to be done and the cost thereof collected as a special assessment from such owners, who may choose to pay the same in full, or in ten equal yearly installments which shall be due and payable to the City of Davao in the same manner as the annual tax levied on real estate and shall be made subject to the same penalties for delinquency, and enforceable by the same remedies, as such annual tax; and all said sums and amounts shall, from the day in which they are assessed, constitute liens on the property against which the same were assessed and shall take precedence over any and all other liens which may exist upon such property excepting only such as may have been attached as a result of the non-payment of said annual tax.\n(y) To regulate the inspection, weighing, and measuring of brick, hollow blocks, lumber, coal and other articles or merchandise.\n(z) Subject to the provisions of existing law, to provide for the laying out, construction and improvement, and to regulate the use of streets, avenues, alleys, sidewalks, wharves, piers, parks, cemeteries, and other public places; to provide for lighting, cleaning, and sprinkling of streets, and public places; to regulate, fix license fees for and prohibit the use of the same for processions and/or parades, signs, signposts, awning, awning posts, and the carrying or displaying of banners, placards, advertisements, or hand bills, or the flying of sign, flags or banners whether along, across, over or from building along the same to prohibit the placing, throwing, depositing, or leaving of obstacles of any kind, garbage, refuse, or other offensive matter or matters liable to cause damage in the street and other public places and to provide for the collection and disposition thereof; to provide for the inspection of, fix the license fees for and regulate the openings in the same for the laying of water, sewer and other pipes, the building and repair of tunnels, sewers and drains, and all structures in and under the same and the erecting of poles and the stringing of wires therein; to provide for and regulate crosswalks, curbs and gutters therein; to name streets without a name and provide for and regulate the numbering of houses and lots fronting thereon or in the interior of the blocks; to regulate traffic and sales upon the streets and other public places; to provide for the abatement of nuisances in the same and punish the authors or owners thereof; to provide for the construction and maintenance, and regulate the use of bridges, viaducts, and culverts; to prohibit and regulate ball playing, kite-flying, hoop rolling, and other amusements which may annoy persons using the streets and public places, or frighten horses or other animals; to regulate the speed of horse and other animal-driven vehicle within the limits of the city.\n(aa) To provide for the construction and maintenance of, and regulate the navigation on, canals, and water courses within the city and provide for the cleaning and purification of the same; unless otherwise provided by law, to provide for the construction and maintenance, and regulate the use or public landing places, wharves, piers docks and levees, and those of private ownership; and to provide for or regulate the drainage and filling of private premises when necessary in the enforcement of sanitary rules and regulations issued in accordance with law.\n(aa-1) To provide for the establishment and maintenance of a telephone system, and, subject to the provisions of the Public Service Act, to fix the charges for the use of said service.\n(bb) Subject to the provisions of the Public Service Law, to fix the charges to be paid by all water crafts landing at or using public wharves, docks, levees, or landing places owned, operated, managed or controlled by the city.\n(cc) Any provision of law to the contrary notwithstanding, to provide for the maintenance of waterworks for the purpose of supplying water to the inhabitants of the city, and for the purification of the source of water supply and the places through which the same passes, and to regulate the consumption and use of water; to fix, subject to the provisions of the Public Service Law, and provide for the collection of rents therefor and to regulate the construction, repair and use of hydrants, pumps, cisterns and reservoirs.\n(dd) To provide for the establishment and maintenance and regulate the use of public drains, sewers, latrines and cesspools.\n(ee) Subject to the rules and regulations issued by the Director of Health Services in accordance with law, to provide for the establishment, maintenance and to fix the fees for the use of, and regulate stables, laundries and baths, and public markets and prohibit the establishment or operation within the city limits of public markets by any person, entity, association, or corporation other than the city.\n(ff) To establish or authorize the establishment of slaughterhouses, to provide for their veterinary or sanitary inspection, to regulate the use of the same, and to charge reasonable slaughter fees. No fees shall be charged for veterinary or sanitary inspection of meat from large cattle or other domestic animals slaughtered outside the city, when such inspection was had at the place where the animals were slaughtered.\n(gg) To regulate, inspect and provide measures preventing any discrimination or the exclusion of any race or races in or from any institution, establishments, or services open to the public within the city limits, or in the sale and supply of, gas or electricity, or in the telephone service; to fix and regulate charges therefor where the same has not been fixed by national law; to regulate and provide for the inspection of all gas, electric and telephone conduits, mains, meters, and other apparatus, and provide for the condemnation, substitution or removal of the same when defective or dangerous.\n(hh) To declare, prevent and provide for the abatement of nuisances; to regulate the ringing of bells and the making of loud or unusual noises; to provide that owners, agents, or tenants of buildings or premises keep and maintain the same in sanitary condition, and that, in case of failure to do so within sixty days from the date a written notice is served, the city health officer shall cause the same to be kept in a sanitary condition, and the cost thereof to be assessed against the owner to the extent of not to exceed sixty per centum of the assessed value, which cost shall constitute a lien against the property; and to regulate and/or prohibit, or fix the license fees for the use of property on or near public ways, grounds, or places, or elsewhere within the city, for display by electric signs or the erection or maintenance of billboards or structures of whatever materials erected, maintained, or used for the display of posters, signs, or other pictorial or reading matter, except signs displayed at the place or places where the profession or business advertised thereby is in whole or in part conducted.\n(ii) To provide for the enforcement of the rules and regulations issued by the Director of Health Services, and by ordinance to prescribe penalties for violation of such rules and regulations.\n(jj) To extend its ordinances over all waters within the city, and over any heat or other floating structures thereon and for the purpose of protecting and insuring the purity of the water supply of the city, over all territory within the drainage area of such water supply, and within one hundred meters of any reservoir, conduit, canal, aqueduct, or pumping station used in connection with the city water service.\n(kk) To regulate any other business or occupation being conducted within the city not specifically mentioned in the preceding paragraphs, and to impose a license fee upon all persons engaged in the same or who enjoy privileges in the city.\n(ll) To fix and regulate the size, speed, and operation of motor and other vehicles within the city; to regulate the lights used on such vehicles; to establish bus stops and terminals; and prohibit and regulate the entrance of provincial public utility vehicles into the city, except those passing through the city.\n(mm) To grant fishing and fishery privileges subject to the provisions of the Fisheries Act.\n(nn) To fix the date of the holding of a fiesta in the city not oftener than once a year and to alter, not oftener than once in three years, the date fixed for the celebration thereof.\n(oo) To enact all ordinances it may deem necessary and proper for the sanitation and safety, the furtherance of the prosperity, and the promotion of the morality, peace, good order, comfort, convenience, and general welfare of the city and its inhabitants, and such others as may be necessary to carry into the effect and discharge the powers and duties conferred by this Charter; and to fix penalties for the violation of ordinances, which shall not exceed a two hundred-peso fine or six months imprisonment, or both such fine and imprisonment for a single offense, in the discretion of the court.\n(pp) To have the power to issue subpoena and subpoena duces tecum in aid of its legislative function and committee hearings and investigations."}},{"id":"PH-H3556-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Restrictive provisions. No commercial sign, signboard, or billboard shall be erected or displayed on public lands, premises or buildings. If, after due investigation, and having given the owners an opportunity to be heard, the Mayor should consider any sign, signboard or billboard displayed or exposed to public view as offensive to the sight or is otherwise a nuisance, he may order the removal of such sign, signboard, or billboard, and if same is not removed within ten days after he has issued such order, he may himself cause its removal, and the sign, signboard, or billboard shall thereupon be forfeited to the city and the expenses incident to the removal of the same shall become a lawful charge against any person or property liable for the erection or display thereof.\nDepartments and offices of the city"}},{"id":"PH-H3556-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"City departments. There shall be the following city departments over which the Mayor shall have direct control and supervision, any existing law to the contrary notwithstanding:\n1. Department of Finance\n2. Department of Engineering and Public Works\n3. Law Department\n4. Department of Health\n5. Police Department\n6. Fire Department\n7. Department of Assessment\n8. Department of Public Services The City Council may from time to time make such readjustment of the duties of the several departments as the public interest may demand, and may consolidate any department, division or office of the city with any other department, division or office."}},{"id":"PH-H3556-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Powers and duties of heads of departments. Each head of department of the city government shall be in control of such department under the direction and supervision of the Mayor, and shall possess such powers as may be prescribed herein or by ordinance. He shall certify to the correctness of all payrolls and vouchers of his department covering the payment of money before payment, except as herein otherwise expressly provided. At least four months before the beginning of each fiscal year, he shall prepare and present to the Mayor an estimate of the receipts and appropriation necessary for the operation of his department for the ensuing fiscal year, and shall submit therewith such information for purposes of comparison as the Mayor may desire. He shall submit to the Mayor as often as required reports covering the operation of his department.\nIn case of the absence or sickness, or inability to act for any other reason, of the head of one of the city departments, or in case of temporary vacancy, the officer next in rank of that department shall perform the duties of the department head concerned."}},{"id":"PH-H3556-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Appointment and removal of officials and employees. The President of the Philippines, with the consent of the Commission on Appointments, shall appoint the city judges, the city treasurer, the city engineer, the city fiscal and his assistants, the chief of police, the city health officer, the city assessor, the chief of the fire department, the city superintendent of schools and his assistant, and other heads of such city department as may be created by law.\nSubject to the provisions of Civil Service Law, the Mayor shall appoint such other officers and employees, except public school teachers and city court employees and employees of the office of the city auditor, paid out of the city funds and they shall be suspended and removed in accordance with law."}},{"id":"PH-H3556-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Officers not to engage in certain transactions. It shall be unlawful for any city officer, directly or indirectly, individually or as a member of a firm, to engage in any business transaction with the city, or with any of its authorized officials, boards, agents or attorneys, whereby money is to be paid, directly or indirectly, out of the resources of the city to such person or firm; or to purchase any real estate or other property belonging to the city, or which shall be sold for taxes or assessments, or by virtue of legal process at the suit of the city; or to be surety for any person having a contract or doing business with the city, for the performance of which security may be required; or to be surety on the official bond of any officer of the city; and shall not be financially interested in any transaction or contract in which the national government or any subdivision or instrumentality thereof in an interested party."}},{"id":"PH-H3556-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Allowance. The head of a department and his assistant or the chief and assistant chief of an office shall be entitled to a commutable allowance in addition to their respective salaries, for quarters and representation which shall not be less than five thousand four hundred pesos for the heads or chiefs, and three thousand six hundred pesos for the assistants per annum.\nFor purposes of this section, the judges of the city court, the city auditor, the city superintendent of schools, the vice-mayor, the councilors, city council secretary and city secretary shall be considered as a chief of a department; and the city electrician, the city veterinarian, and the city agriculturist shall be considered as assistant chief of a department or an office.\nRelation to Bureaus and Offices"}},{"id":"PH-H3556-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE V"},"text":{"en":"The General Auditing Office. The Auditor General shall receive and audit all accounts of the city, in accordance with the provisions of law relating to Government accounts and accounting. The city auditor shall be appointed by the Auditor General and shall receive the same salary of the city treasurer per annum, one-half to be paid by the National Government and the other half by the city."}},{"id":"PH-H3556-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE V"},"text":{"en":"The Bureau of Public Schools. The Director of Public Schools shall exercise the same jurisdiction and powers in the city as elsewhere in the Philippines, and the city superintendent of schools, who shall receive a compensation of fifteen thousand pesos per annum, shall have all the powers and duties in respect to the schools of the city as are vested in division superintendents in respect to schools of their division: Provided , That the operational expenses of primary, intermediate and high schools shall be borne by the National Government, as provided for by law."}},{"id":"PH-H3556-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE V"},"text":{"en":"The Bureau of Supply Coordination. The procedure outlined in Republic Act Numbered Two thousand two hundred sixty-four relative to purchasing shall govern the purchase of materials, equipment and supplies. However, the Committee on Award shall be composed of the city mayor, as chairman, the city treasurer, the city auditor, the city fiscal and a councilor duly designated by the City Council, as members. These officers may act through their authorized representatives."}},{"id":"PH-H3556-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Reports to the Mayor concerning schools. The city superintendent of schools shall make a quarterly report of the conditions of the schools and school buildings of the city to the mayor, and such recommendations as seem to him wise relative to improving the schools or school buildings in the city.\nDepartment of Finance"}},{"id":"PH-H3556-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"The City Treasurer His powers and duties. These shall be a city treasurer who shall have charge of the Department of Finance and shall act as chief fiscal officer and financial adviser of the city and custodian of its funds. He shall receive a salary of fifteen thousand pesos per annum. He shall have the following general powers and duties:\n(a) He shall collect all taxes due the city, all licenses authorized by law or ordinance, all rents due for lands, markets and other property owned by the city, and all further charges of whatever nature fixed by law or ordinances; shall administer markets and slaughterhouses, and shall receive and issue receipts for all costs, fees, fines and forfeitures imposed by the city court.\n(b) He shall collect all miscellaneous charges made by the engineering department and by other departments of the city government, and all charges made by the city engineer for inspections, permits, licenses, and the installations, maintenance, and services rendered in the operation of the private privy system.\n(c) Unless otherwise specifically provided by law or resolution, he shall perform in and for the city the duties imposed by law or resolution upon provincial treasurers in general as well as other duties imposed upon him by law.\n(d) He shall purchase and issue all supplies, equipment or other property required by the city, through the purchasing agent, or otherwise, as may be authorized, subject to the general provisions of law relating thereto.\n(e) He shall be accountable for all funds and property of the city and shall render such accounts in connection therewith as may be prescribed by the Auditor General.\n(f) He shall deposit daily all city funds and collections in any bank duly designated as government depository.\n(g) He shall disburse the funds of the city in accordance with duly authorized appropriations, upon properly executed vouchers bearing the approval of the chief of the department concerned, and on or before the twentieth day of each month he shall furnish the mayor and the city Council, for their information, a statement of the appropriation, expenditures, and balances of all funds and accounts as of the last day of the month preceding.\nDepartment of Engineering and Public Works"}},{"id":"PH-H3556-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Engineer His powers and duties. There shall be a city engineer who shall have charge of the department of engineering and public works. He shall receive a salary of fifteen thousand pesos per annum. He shall have the following powers and duties:\n(a) He shall have charge of all the surveying and engineering works of the city, and shall perform such service in connection with public improvements, or any work entered upon or projected by the city, or any department thereof, as may require the skill and experience of a civil engineer.\n(b) He shall ascertain, record, and establish monuments of the city survey and from thence extend the surveys of the city, and locate, establish, and survey all city property, and also private property abutting on the same, whenever directed by the mayor.\n(c) He shall prepare and submit plans, maps, specifications and estimates for buildings, streets, bridges, docks, and other public works, and supervise the construction and repair of the same.\n(d) He shall make such tests and inspection of engineering materials used in construction and repair as may be necessary to protect the city from the use of materials of a poor or dangerous quality.\n(e) He shall prevent the encroachment of private buildings and fences on the streets and public places of the city.\n(f) He shall have general supervision and inspection of all private docks, wharves, piers, levees, and landing places and other property bordering on the harbor, river, esteros, and waterways of the city, and shall issue permits for the construction, repair and removal of the same, and enforce all ordinances relating to the same.\n(g) He shall supervise the laying of mains and connections for the purpose of supplying gas to the inhabitants of the city.\n(h) He shall inspect and report upon the conditions of public property and public works whenever required by the mayor.\n(i) He shall supervise and regulate the location and use of engines, boilers, forges, and other manufacturing and heating appliances in accordance with law and ordinance relating thereto. He is authorized to charge fees, at rates to be fixed by the city council, for the sanitation and transportation services and supplies furnished by his department.\n(j) He shall inspect and supervise the construction, repair, removal, and safety of private buildings, and regulate and enforce the numbering of houses in accordance with the ordinances of the city.\n(k) With the previous approval of the mayor in each case, he shall order the removal of buildings and structures erected in violation of the ordinances; shall order the removal of materials employed in the construction or repair of any building or structure made in violation of said ordinances; and shall cause buildings and structures dangerous to the public to be made secure or torn down.\n(l) He shall file and preserve all maps, plans, notes, surveys and other papers and documents pertaining to his office."}},{"id":"PH-H3556-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Execution of authorized public works and improvements. All repair or construction of any work or public improvements, except parks, boulevards, streets or alleys, involving an estimated cost of three thousand pesos or more shall be awarded by the mayor upon the recommendation of the city engineer to the lowest responsible bidder after public advertisement by posting notices of the call for bids in conspicuous places in the city hall and by publication in the local newspapers of general circulation, both for not less than ten days: Provided, however , That the city engineer may, with the approval of the President of the Philippines, upon the recommendation of the Secretary of Public Works and Communications, execute by administration any such public work costing three thousand pesos or more.\nIn case of public works involving an expenditure of less than three thousand pesos, it shall be discretionary with the city engineer either to proceed with the work himself or to let the contract to the lowest bidder after such publication and notice as shall be deemed appropriate or as may be, by regulations, prescribed.\nLaw Department"}},{"id":"PH-H3556-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The City Fiscal His powers and duties. There shall be a city fiscal who shall discharge his duties under the general supervision of the Secretary of Justice. The city fiscal shall receive a salary of fifteen thousand pesos per annum. The city fiscal shall be the chief legal adviser of the city and all offices and departments thereof. He shall have the following powers and duties:\n(a) He shall represent the city in all civil cases wherein the city or any officer thereof, in his official capacity, is a party.\n(b) He shall, when required, draw ordinances, contracts, bonds, leases, and other instruments involving any interest of the city, and inspect and pass upon any such instruments already drawn.\n(c) He shall give his opinion in writing, when requested by the mayor or the council, upon any question relating to the city or the rights or duties of any city officer.\n(d) He shall, whenever it is brought to his knowledge that any city officer is guilty of neglect or misconduct in office, or that any person, firm or corporation holding or exercising any franchise or public privilege from the city, has failed to comply with any condition, or to pay any consideration mentioned in the grant of such franchise or privilege, investigate or cause to be investigated the same and report to the Mayor.\n(e) He shall have charge of the prosecution of all crimes and misdemeanors and violations of city ordinances triable in the city court. He shall also have charge of all prosecution of crimes, misdemeanors, and violations of city ordinances appealed to or brought before, the Court of First Instance of Davao.\n(f) He shall investigate all charges of crimes, misdemeanors, and violations of city ordinances and prepare the necessary informations or make the necessary complaints against the persons accused, and discharge all other duties in respect to criminal prosecutions enjoined upon provincial fiscals generally.\n(g) He may conduct investigations in respect to crimes, misdemeanors, and violations of ordinances and for this purpose may, by subpoena, summon witnesses to appear and testify under oath before him, and the attendance of an absent or recalcitrant witness may be enforced by application to the city court or the Court of First Instance of the Province of Davao.\n(h) He shall cause to be investigated causes of sudden deaths which have not been satisfactorily explained and when there is suspicion that the causes arose from unlawful acts or omissions of other persons or from foul play. For that purpose he may cause autopsies to be made, in case it is deemed necessary, and shall be entitled to demand and receive for the purposes of such investigations or autopsies the aid of the city health officer.\n(i) He shall, when directed by the Mayor, institute and prosecute in the city's interest a suit on any bond, lease, or other contract and upon any breach or violation thereof."}},{"id":"PH-H3556-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"Assistant City Fiscals. There shall be ten assistant city fiscals who shall perform the duties of the city fiscal as assigned and directed by the city fiscal, with the following compensation per annum:\nFirst assistant city fiscal P12,000.00 Second assistant city fiscal 11,400.00 Third assistant city fiscal 11,100.00 Fourth assistant city fiscal 10,800.00 Fifth assistant city fiscal 9,600.00 Sixth assistant city fiscal 9,600.00 Seventh assistant city fiscal 9,600.00 Eighth assistant city fiscal 8,400.00 Ninth assistant city fiscal 7,200.00 Tenth assistant city fiscal 7,200.00 The incumbent special counsel, according to seniority of service, will automatically become sixth, seventh and eighth assistant city fiscals.\nDepartment of Health"}},{"id":"PH-H3556-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"The City Health Officer His powers and duties. There shall be a city health officer who shall have charge of the Department of Health and shall receive a salary of fifteen thousand pesos per annum. He shall have the following powers and duties:\n(a) He shall have general supervision over the health and sanitary conditions of the city, including the cleaning of crematories and cemeteries.\n(b) He shall execute and enforce all laws, ordinances and regulations relating to the public health.\n(c) He shall recommend to the City Council the passage of such ordinances as he may deem necessary for the preservation of public health.\n(d) He shall cause to be prosecuted all violations of sanitary laws, ordinances, or regulations.\n(e) He shall make sanitary inspections and may be aided therein by such members of the police force of the city or the national police as shall be designated as sanitary police by the chief of police or proper national police officer and such sanitary inspectors as may be authorized by law.\n(f) He shall have control and supervision over puericulture centers and social services of the city.\n(g) He shall perform such other duties, not repugnant to law or ordinance, with reference to the health and sanitation of the city as the Director of Health Services shall direct. In case of epidemic or when the inhabitants of the city are menaced by any infectious or contagious diseases, the Director of Disease Control shall assume full control of the health and sanitation services of the city until such condition shall have ceased to exist.\nPolice Department"}},{"id":"PH-H3556-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"ARTICLE X"},"text":{"en":"The chief of police His powers and duties. There shall be a chief of police who shall have charge of the police department and shall receive a salary of twelve thousand pesos per annum. He shall have the following powers and duties:\n(a) He may issue supplementary regulations not incompatible with law or general regulations promulgated by the proper department head of the National Government, in accordance with law, for the government of the city police and detective force.\n(b) He shall quell riots, disorders, disturbances of the peace, and shall arrest and prosecute through the city fiscal, violators of law or ordinances; shall exercise exclusive police supervision over all land and water within the police jurisdiction of the city; shall be charged with the protection of the rights of persons and property wherever found within the jurisdiction of the city, and shall arrest when necessary to prevent the escape of offenders and violators of any law or ordinance; and all who obstruct or interfere with him in the discharge of his duty; shall have charge of the city prison; and shall be responsible for the safekeeping of all prisoners until they shall be released from custody, in accordance with law, or delivered to the warden of the proper prison or penitentiary.\n(c) He shall have authority within the police limits of the city, to serve and execute criminal processes of any court.\n(d) He shall be the deputy sheriff of the city, and as such he shall, personally or by representative, attend the sessions of the city court, and shall execute promptly and faithfully, all writs and processes of said court.\n(e) He shall exercise supervision over the police training school established in accordance with the rules and regulations of the police department.\n(f) He shall have such further powers and perform such further duties as may be prescribed by law or ordinance."}},{"id":"PH-H3556-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Chief of secret service. There shall be a chief of the secret service who shall, under the chief of police, have charge of the detective work of the department and of the detective force of the city, and shall perform such other duties as may be assigned to him by the chief of police or prescribed by law or ordinance."}},{"id":"PH-H3556-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Peace Officers Their powers and duties. The Mayor, the chief of police, the deputy chief of police, the chief of the secret service, and all officers and members of the city police and detective force shall be peace officers. Such peace officers are authorized to serve and execute all processes of the city court and criminal processes of all other courts to whomsoever directed within the jurisdictional limits of the city or within the police limits as hereinbefore defined; within the same territory, to pursue and arrest without warrant, any person found in suspicious places or under suspicious circumstances reasonably tending to show that such person has committed, or is about to commit, a crime or breach of the peace; to arrest or cause to be arrested, without warrant, any offender when the offense is committed in the presence of a peace officer or within his view; and, in such pursuit or arrest, to enter any building, ship, boat, or vessel or take into custody any person therein suspected of being concerned in such crime or breach of the peace, and any property suspected of having stolen; and to exercise such other powers and perform such other duties as may be prescribed by law or ordinance. They shall detain an arrested person only in accordance with the provisions of existing laws relative to such detention. Whenever the mayor shall deem it necessary to ever danger or to protect life and property, in case of riot, disturbance, or public calamity, or when he has reason to fear any serious violation of law and order, he may call upon the provincial commander or other members of the Armed Forces of the Philippines. Except upon the occurrence of any such conditions, police jurisdiction and supervision and the preservation of peace and order shall pertain exclusively to the peace officers herein mentioned, existing law to the contrary notwithstanding.\nFire Department"}},{"id":"PH-H3556-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Chief of fire department. There shall be a chief of fire department who shall have the management and control of all matters relating to the administration, organization, government, discipline, and disposition of the fire forces. He shall receive a salary of twelve thousand pesos per annum, and shall have the following powers and duties;\n(a) He shall issue supplementary regulations not incompatible with law or general regulations issued by the proper department head of the National Government in accordance with law, for the governance of the fire force.\n(b) He shall have charge of the fire-engine houses, the fire engines, hose trucks, hooks and ladders, trucks and all other fire apparatus.\n(c) He shall have full police powers in the vicinity of fires.\n(d) He shall have authority to remove or demolish any building or other property whenever it shall become necessary to prevent the spreading of fire or to protect adjacent property.\n(e) He shall investigate and report to the mayor upon the origin and cause of all fires occurring within the city.\n(f) He shall inspect all buildings erected or under construction or repair within the city and determine whether they provide sufficient protection against fire and comply with the ordinance relating thereto.\n(g) He shall have charge of the city telegraph, telephone and fire alarm service.\n(h) He shall have exclusive power, any law to the contrary notwithstanding, to supervise and regulate the stringing, grounding, and installation of wires for all electrical connections with a view to avoiding conflagrations, interference with public traffic or safety, or the necessary operation of the fire department.\n(i) He shall condemn all defective electrical installations and shall take the necessary steps to effect immediate corrective action, informing the mayor of the action thus taken.\n(j) He shall supervise the manufacture, storage, and use of petroleum, gas, acetylene, gunpowder, and other highly combustible matter and explosives.\n(k) No permit for the construction or repair of buildings within the city shall be granted unless the plans relative thereto have been approved by the chief of the fire department. He shall have the power to alter or disapprove such plans as do not provide for adequate protection against the occurrence of fires.\n(l) He shall have such powers and perform such duties as may further be prescribed by law or ordinance.\nDepartment of Assessment"}},{"id":"PH-H3556-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"ARTICLE XII"},"text":{"en":"The City Assessor His powers and duties. There shall be a city assessor who shall have charge of the department of assessment and who shall receive a salary of fifteen thousand pesos per annum. He shall have the following powers and duties:\n(a) He shall annually assess and value for taxation the real estate of the city, and for this purpose, the city assessor and his authorized deputies are empowered to administer any oath authorized to be administered in connection with the valuation of real estate for the assessment and collection of taxes.\n(b) He shall make a list of all taxable real estate in the city and the names of the owners thereof, with a brief description opposite their names of the property owned by them and the cash value thereof. In making this list the city assessor shall take into consideration any sworn statement made by the owners of the property, but shall not be prevented thereby from considering other evidence on the subject, and exercising his own judgment in respect thereto. For the purpose of completing this list, he and his authorized deputies or representatives may enter upon the real estate for the purpose of examining and measuring it, and may summon witnesses, administer oaths to them, and subject them to examination concerning the ownership and the amount of real estate and its cost value.\n(c) He may, if necessary, examine the records of the register of deeds of the province or city showing the ownership of real estate in the city.\n(d) He shall attend all meetings of the Board of Assessments Appeals and furnish it with all written evidence in his possession relating to assessment and valuation. He shall likewise furnish the city treasurer with a copy of every tax declaration or cancellation thereof prepared by him from time to time, and such other information as the city treasurer may require for the collection of taxes.\n(e) Declaration to be made by person acquiring or improving real estate. It shall be the duty of each person who, at any time, acquired real estate in the city, and of each person who constructs or adds to any improvement on real estate owned by him in the city, to prepare and present to the city assessor within a period of sixty (60) days next succeeding such acquisition, construction or addition, a sworn declaration setting forth the value of the real estate acquired or the improvement constructed or addition made by him and a description such property sufficient to enable the city assessor readily to identify the same, and furnishing him with certified copy or duplicate original of deeds of conveyance or any proof of acquisition thereof, as well as original, subdivision or segregation maps or surveys and invoices. For this purpose, the register of deeds is hereby required to furnish the city assessor with a duplicate copy of every deed or instrument of conveyance presented for registration, and all surveyors, either public or private, are likewise required as soon as possible to furnish free the said city assessor with a blue or white print copy of all maps or surveys executed or made by them within the city. Any person having acquired real estate who fails to make and present the declaration herein required within the said period set forth above shall be deemed to have waived his right to notice of the assessment or revision of such property and the assessment or revision of the same in the name of its former owner shall, in all such cases, be valid and binding on all persons interested for all purposes, as though the same had been assessed in the name of its present owner.\n(f) Action when owner makes no declaration, or is unknown, or ownership is in dispute or in doubt, or when land and improvements are separately owned. If the owner of any real estate shall fail to make a declaration thereof, or if the city assessor is unable to discover the owner of any real estate, he shall nevertheless list the same for taxation, and charge the tax against the true owner, if known, and if unknown, then as against an unknown owner. In case of doubt or dispute as to the ownership of real estate, the taxes shall be levied against the possessor or possessors thereof. When it shall appear that there are separate owners of the land and the improvement thereon, separate assessment of the property of each shall be made.\n(g) Action in case real estate has escaped taxation. If it shall come to the knowledge of the city assessor that any taxable real estate in the city has escaped listing, it shall be his duty to list and value the same at the time and in the manner provided herein and to charge against the owner thereof the taxes due for the current year and last preceding four years, and the taxes thus assessed shall be legal collectible, and the penalties shall be added to such back taxes as though they had been assessed at the time when they should have been assessed.\n(h) When assessment may be increased or decreased. The City Assessor shall, during any part of the year, add to his list of taxable real estate in the city the value of the improvements placed upon such property during the preceding or current year, and any property which is taxable and which has theretofore escaped taxation. Likewise, with or without the presence of owners, he may revise and correct the assessed value of any or all parcels of real estate in the city which are not assessed at their true money value, by reducing or increasing the existing assessment as the case may be, the effectivity of which shall be the year next following."}},{"id":"PH-H3556-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"ARTICLE XII"},"text":{"en":"The City Board of Assessment Appeals. There shall be a City Board of Assessment Appeals which shall be composed of five members, three of whom are government officials, and the remaining two to be appointed by the city mayor. The three members of the Board shall be the city auditor, as chairman, the city engineer and the register of deeds as members, to serve without additional compensation.\nThe two other members shall be selected from among property owners in the city and they shall each receive a compensation of fifteen (P15.00) pesos for each day of session actually attended, and shall hold office for a term of four (4) years unless sooner removed by the city mayor. The chairman of the board shall have the power to designate any city official or employee to serve as the secretary of the board without additional compensation.\n(a) The members of the City Board of Assessment Appeals shall, before organizing as such, take the following oath before the judge of the city court, or some other officer authorized to administer oath:\n\"I do solemnly swear (or affirm) that I will well and truly hear and determine all matters and issues between the city assessor and taxpayers submitted for my decision. So help me God. (In case of affirmation, the last four words are to be stricken out.) (Signature) \"Subscribed and sworn to (or affirmed) before me this _____ day of _____________, 19___ .\n(Signature of officer administering oath)\"\n(b) The City Board of Assessment Appeals shall hold such number of sessions as may be authorized by the Secretary of Finance, and shall hear and decide all appeals duly transmitted to it. It shall have authority to cause to be amended the listing and valuation of the property in respect to which an appeal has been perfected by order signed by the Board or a majority thereof, and transmit it to the city assessor who shall amend the tax list in conformity with said order. It shall also have the power to revise and correct, with the approval of the Department Head first had, any and all erroneous or unjust assessments and valuations for taxation, and make a correct and just assessment and state the true valuation in each case when it decides that the assessment previously made is erroneous or unjust. The Assessment when so corrected shall be as lawful and valid for all purposes as though the assessment had been made within the time herein prescribed. Such reassessment and revaluation shall be made on due notice to the individual concerned who shall be entitled to be heard by the City Board of Assessment Appeals before any reassessment or revaluation is made. The decision of the City Board of Assessment Appeals shall be final unless the Department Head declares the decision reopened for review by him, in which case he may make such revision or revaluation as in his opinion the circumstances justify. Such revision when approved by the President of the Philippines shall be final."}},{"id":"PH-H3556-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"ARTICLE XII"},"text":{"en":"Taxes on real estate. A tax, the rate of per centum of ad valorem taxation not to exceed two per centum, to be determined by the City Council, shall be levied annually on or before the second Monday of December on the assessed values of all real estate in the city subject to taxation. Taxes on the said rate shall be due and payable annually on and after the first day of January of the ensuing year.\nDepartment of Public Services"}},{"id":"PH-H3556-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"City Public Service Officer. There shall be city public service officer, who must at least be a sanitary engineer, with a salary of eleven thousand four hundred pesos per annum. He shall have the following general powers and duties:\n(a) He shall have general supervision and control over the sanitary building and plumbing inspection service; care, custody and cleaning of all public streets, paths and monuments; public buildings including markets and slaughterhouses and buildings rented for city purposes; public toilets and cesspools, dockyards and all other offensive and dangerous substances within the city.\n(b) He shall have authority to charge, at rates to be fixed by the City Council with the approval of the Mayor, fees for public services and supplies furnished by his department to private parties.\n(c) He shall have authority to declare that any lot or ground within the City of Davao belonging to any person or corporation or to the National Government or any branch or political subdivision thereof, is so low, excavated or walled, diked or dammed as to admit or cause the formation on the surface thereof of stagnant or foul water, or that it is a nuisance or a menace to public health, unless filled in or its sanitary condition otherwise improved, and shall communicate same to the mayor.\n(d) He shall execute and enforce all laws, ordinances, and regulations relating to public services.\n(e) He shall recommend to the City Council the passage of ordinances as he may deem necessary for the better and more adequate extension of public services.\n(f) He shall cause to be prosecuted all violations of laws, ordinances or regulations relating to public services.\nTax allotments and special assessment for public improvements"}},{"id":"PH-H3556-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Allotment of internal revenue and other taxes. On the internal revenue accruing to the National Treasury under Chapter II, Title XII of Commonwealth Act Numbered Four hundred sixty-six, and other taxes collected by the National Government and alloted to the various provinces, as well as the national aid for schools, the city shall receive a share equal to what it would receive if it were a regularly organized province."}},{"id":"PH-H3556-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Power to levy special assessment for certain purposes. The City Council may, by ordinance, provide for the levying and collection, by special assessment of the land comprised within the district or section of the city specially benefited, or a part not to exceed sixty per centum of the cost of laying out, opening, constructing, straightening, widening, extending, grading, paving, curbing, enlarging, or improving public avenues, roads, streets, alleys, sidewalks, parks, plazas, bridges, landing places, wharves, piers, docks, levees, reservoirs, waterworks, watermains, water courses, esteros, canals, drains and sewers, including the cost of acquiring the necessary land and public improvements thereon, as hereinafter provided.\nIn case of national public works the City Council as an agency of the National Government, shall, when the President of the Philippines so directs it, provide for the levying and collection by special assessment of the land within the section or district of the city specially benefited of the cost or part thereof to be determined by the President, of laying out, opening, constructing, straightening, widening, extending, grading, paving, curbing, walling or deepening, or otherwise repairing, enlarging or improving national roads and other national public works within the city, including the cost of acquiring the necessary land and improvements thereon."}},{"id":"PH-H3556-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Basis of apportionment. The amount of the special assessment shall be apportioned and computed according to the assessed valuations of such lands as shown in the books of the city assessor. If the property has not been declared for taxation purposes, the city assessor shall immediately declare it for the owner and assess its value, and such value shall be the basis of the apportionment and computation of the special assessment due thereon."}},{"id":"PH-H3556-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Property subject to special assessment. All lands comprised within the section or district benefited, except those owned by the Republic of the Philippines, shall be subject to the payment of the special assessment."}},{"id":"PH-H3556-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Ordinances levying special assessment. The ordinance providing for the levying and collection of a special assessment shall describe with reasonable accuracy the nature, extent, and location of the work to be undertaken; the probable cost of the work; the percentage of the cost to be defrayed by special assessment; the district or section which shall be subject to the payment of the special assessment and shall describe with reasonable accuracy metes and bounds if practicable, and by other reasonable accurate means if otherwise, and the period, which shall not be less than five nor more than ten years, in which said special assessment shall be payable without interest. One uniform rate per centum for all lands in the entire district or section subject to the payment of all the special assessment need not be established, but different rates for different parts or sections of the city according as said property will derive greater or less benefit from the proposed work, may be fixed.\nIt should be the duty of the city engineer, to make the plans, specifications, and estimates of the public works contemplated to be undertaken."}},{"id":"PH-H3556-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Publications of proposed ordinance levying special assessment. The proposed special assessment ordinance shall be published, with a list of the owners of the lands affected thereby, once a week for four consecutive weeks in any newspaper published in the city, one in English, one in Spanish, and one in the local dialect, if there be any, and in default of local papers, in any newspaper of general circulation in the city. The said ordinance in English, Spanish, and the local dialect shall also be posted in places where public notices are generally posted in the city and also in the district or section where the public improvement is constructed or contemplated to be constructed.\nThe secretary of the city council shall, on application, furnish a copy of the proposed ordinance to each land-owner affected, or his agent and shall, if possible, send to all of them a copy of said proposed ordinance by ordinary mail or otherwise."}},{"id":"PH-H3556-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Protest against special assessment. Not later than thirty days after the last publication of the ordinance and the list of landowners, as provided in the preceding section, the landowners affected may file with the City Council a protest against the enactment of the ordinance. The protest shall be duly signed by them and shall set forth the addresses of the signers and the arguments in support of their objection or protest against the special assessment established in the ordinance. If no protest is filed within the time and under the condition above specified, the ordinance shall be considered approved as published."}},{"id":"PH-H3556-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Hearing of protest. The City Council shall designate a date and place for the hearing of the protest filed in accordance with the next preceding section and shall give reasonable time to all protestants who have given their addresses and to all landowners affected by any protest or protests, and shall order the publication once a week for two consecutive weeks, of a notice of the place and date of hearing in the same manner herein provided for the publication of the proposed special assessment ordinance. All pertinent arguments and evidences presented by the landowners interested or their attorney shall be attached to the proper records. After the hearing, the City Council shall either modify its ordinance or approve it in toto and send notice of its decision to all interested parties who have given their addresses, and shall order the publication of the ordinance as approved finally together with a list of the owners of the parcels of land affected by the special assessment, three times weekly, for three consecutive weeks, in the same manner hereinabove prescribed. The ordinance finally passed by said body shall be sent to the mayor with all the papers pertaining thereto, for his approval or veto as in the case of other city ordinances. If the Mayor approves it, the ordinance shall be published as above provided, but if he vetoes it, the procedure in similar cases provided in this Charter shall be observed."}},{"id":"PH-H3556-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"When ordinance is to take effect. Upon the expiration of thirty days from the date of the last publication of the ordinance as finally approved, the same shall be effective in all respects, if no appeal therefrom is taken to the proper authorities in the manner hereinafter prescribed."}},{"id":"PH-H3556-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Appeals. Any time before the ordinance providing for levying and collection of special assessment becomes effective in accordance with the preceding section, appeals from such assessment may be filed with the President of the Philippines in case of public works undertaken or contemplated to be undertaken by the National Government, and with the Secretary of Finance in the case of public works undertaken or contemplated to be undertaken by the city. In all cases, the appeal shall be in writing and signed by at least a majority of the owners of the lands situated in the special assessment zone whose holdings represent more than one-half of the total assessed value of the lands affected. The appellant or appellants shall immediately give the City Council a written notice of the appeal, and the Secretary of the City Council shall, within thirty days after receipt of the notice of appeal, forward to the officer who has jurisdiction to decide the appeal an excerpt from the minutes of the council relative to the proposed special assessment and all the documents in connection therewith."}},{"id":"PH-H3556-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Decision of the appeal. Only appeals made within the time and in the manner prescribed in this Act shall be entertained, and the officer to whom the appeal is made may call for further hearing or decide the same in accordance with its merits as shown in the papers or documents submitted to him. All appeals shall be decided within sixty days after receipt by the appellate officer of the docket of the case, and such decision shall be final."}},{"id":"PH-H3556-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Fixing of amount of special assessment. As soon as the ordinance is in full force and effect, the city treasurer shall determine the amount of the special assessment which the owner of each parcel of land comprised within the zone described in the ordinance levying the same is to pay each year during the prescribed period, and shall send to each landowner a notice thereof by ordinary mail. If upon completion of the public works it should appear that the actual cost thereof is smaller or greater than the estimated cost, the city treasurer shall without delay proceed to correct the assessment by increasing or decreasing, as the case may be, the special tax on each parcel of land affected, for the balance of the unpaid annual installments. If all annual installments have already been paid, the city treasurer shall fix the amount of credit to be allowed to, or the additional special tax to be levied upon, the land as the case may be. In all cases, he shall give notice of such rectifications to the parties interested."}},{"id":"PH-H3556-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Payment of special assessment. All sums due from any land owner or owners as the result of any action taken pursuant to this article shall be payable to the city treasurer in the same manner as the annual ordinary tax levied upon real property, and shall be subject to the same penalties for delinquency and be enforced in the same manner as said annual ordinary tax; and all said sums together with any of said penalties shall, from the dates on which they were assessed, constitute special liens on said land, with the sole exception of the lien for the nonpayment of the ordinary real property tax. If, upon recomputation of the amount of the special assessment in accordance with the next preceding section, it appears that the landowner has paid more than what is correctly due from him, the amount paid in excess shall be refunded to him immediately upon demand; in the other case, the landowner shall have one year within which to pay without penalty the amount still due from him. Said period shall be counted from the date the landowner received the proper notice."}},{"id":"PH-H3556-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Disposition of proceeds. The proceeds of the special assessment and penalties thereon shall be applied exclusively to the purpose or purposes for which the assessment were levied. It shall be the duty of the city treasurer to turn over to the National Treasury all collections made by him from special assessment levies for national public works.\nCity Budget"}},{"id":"PH-H3556-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"Annual Budget. At least four months before the beginning of each fiscal year, the city treasurer shall present to the Mayor a certified statement by department of all receipts and expenditures of the city pertaining to the preceding fiscal year, and to the first seven months of the current fiscal year together with an estimate of the receipts and expenditures for the remainder of the current fiscal year; and he shall submit with this statement a detailed estimate of the revenues and receipts of the city from all sources for the ensuing fiscal year. Upon receipt of this statement and estimate and the estimates of department heads as required by Section nineteen of this Charter, the Mayor shall formulate and submit to the City Council at least two and a half months before the beginning of the ensuing fiscal year, a detailed budget covering the estimated necessary expenditures for the said ensuing fiscal year, which shall be the basis of the annual appropriation ordinance: Provided, however , That in no case shall the aggregate amount of such appropriation exceed the estimate of revenues and receipts submitted by the city treasurer as provided above."}},{"id":"PH-H3556-A56","no":56,"noLabel":{"en":"Section 56."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"Supplemental budget. Supplemental budget formulated in the same manner as the annual budget may be adopted when special or unforeseen circumstances make such action necessary."}},{"id":"PH-H3556-A57","no":57,"noLabel":{"en":"Section 57."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"Failure to enact an appropriation ordinance. Whenever the City Council fails to enact an appropriation ordinance for any fiscal year before the end of the current fiscal year, the appropriation ordinance for such year shall be deemed reenacted, and shall go into effect on the first day of July of the new fiscal year as the appropriation ordinance for that year."}},{"id":"PH-H3556-A58","no":58,"noLabel":{"en":"Section 58."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"City funds. The city funds shall consist of the general fund and such special funds as may be created by law or ordinance. The general fund shall be devoted exclusively for local public purposes. Any provision of law to the contrary notwithstanding, the general fund of the city shall not be encumbered by way of contribution, aid, and transfer to other entities, local, national, or charitable, without securing first the approval of the City Council.\nCity Court"}},{"id":"PH-H3556-A59","no":59,"noLabel":{"en":"Section 59."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"Regular and acting judges of the City Court. There shall be a city court for the City of Davao which shall have three branches for which the three judges thereof shall be known, respectively, as judge of the first, second and third branch. The City Council may, when the circumstances so warrant and subject to the approval of the Secretary of Justice, appropriate the necessary amount for the establishment of other branch or branches of the city court, the judge or judges thereof to be appointed in the manner provided for by law.\nThe city judge may, upon proper application to the Secretary of Justice, be allowed a vacation of not more than thirty days every year with salary, which they shall enjoy in accordance with a rotation plan to be laid by the executive judge of the city court with the concurrence of the two other city judges, provided, however , that the total vacation and sick leave that may accumulate to their credit shall be made commutable until their voluntary resignation from office and/or their retirement.\nIn case of absence, incapacity or inability of any city judge or judges, the Secretary of Justice shall designate a municipal judge or judges of any of the adjoining municipalities to preside over the branch or branches concerned, and to hold office temporarily until the regular incumbent thereof, shall have resumed office, or until another judge shall have been appointed in accordance with law. The municipal judge so designated shall receive his salary as such municipal judge, plus thirty per centum of the salary of the city judge whose office he has temporarily assumed. The city judges of the city court of Davao shall each receive a salary of not less than fifteen thousand pesos per annum."}},{"id":"PH-H3556-A60","no":60,"noLabel":{"en":"Section 60."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"Clerk and employees of the City Court. There shall be a clerk of court who, except the present incumbent, must be a member of the Philippine Bar and shall be appointed by the city mayor upon recommendation of the executive judge whose salary shall be fixed by the city council. Notwithstanding the provisions of Republic Act Numbered Nine hundred fifteen, the clerk of court shall at the same time be sheriff of the city and shall have as such, the same powers and duties as assigned by existing law to provincial sheriffs: Provided, however , That the newspaper or newspapers in which notices of sales at auction of real property or other notices are to be published shall be designated by the interested party. There shall also be a deputy clerk-legal researcher, three deputy clerks, three deputy sheriffs and other clerks of the city court who shall be appointed by the executive judge whose salaries shall be fixed by the city council.\nThe clerk of the city court shall keep its seal and affix it to all orders, judgments, certificates, records and other documents issued by the court. He shall keep a docket of the trials in the court, in which he shall record in a summary manner the names of the parties and the various proceedings in civil cases, and in criminal cases, the name of the defendant, the charge against him, the names of the witnesses, the date of the trial, and the nature of the judgment, together with the fines and cost adjudged or collected in accordance with the judgment. He shall have the power to administer oaths."}},{"id":"PH-H3556-A61","no":61,"noLabel":{"en":"Section 61."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"Jurisdiction. The city court shall have the same jurisdiction in civil and criminal cases and the same incidental powers as conferred by law upon the same city courts of chartered cities and such additional jurisdiction and powers as may be conferred upon it by this Charter or by special law."}},{"id":"PH-H3556-A62","no":62,"noLabel":{"en":"Section 62."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"Procedure in city court in prosecutions for violation of laws and ordinances. In a prosecution for the violation of any ordinance, the first process shall be a summons; except that a warrant for the arrest of the offender may be issued in the first instance upon the affidavit of any person that such ordinance has been violated; and that the person making the complaint has reasonable grounds to believe that the party charged is guilty thereof, which warrant shall conclude: \"Against the ordinance of the city in such cases made and provided.\" All proceedings and prosecutions for offenses against the laws of the Philippines shall conform to the rules relating to process, pleading, practice, and procedure for the judiciary of the Philippines, and such rules shall govern the city court and its officers in all cases insofar as the same may be applicable. An appeal from the city court to the Court of First Instance and to appellate courts shall be governed by the provisions of the Revised Rules of Court and the Judiciary Act of 1948, as amended."}},{"id":"PH-H3556-A63","no":63,"noLabel":{"en":"Section 63."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"Costs, fees, fines and forfeitures in the City Court. There shall be taxed against and collected from the defendant, in case of his conviction in the city court, such costs and fees as may be prescribed by law in criminal cases in municipal courts. All costs, fees, fines and forfeitures shall be collected by the clerk of court, who shall keep a docket of those imposed and of those collected, and shall pay collections of the same to the city treasurer, for the benefit of the city, on the next business day after the same are collected, and take receipts therefor. The city judge shall examine said docket each day, compare the same with the amount receipted for by the city treasurer and satisfy himself that all such costs, fees, fines and forfeitures have been duly accounted for."}},{"id":"PH-H3556-A64","no":64,"noLabel":{"en":"Section 64."},"chapter":{"en":"ARTICLE XVI"},"text":{"en":"Commitment to prison. No person shall be confined in prison by sentence of the city court until the warden or officer in charge of the prison shall receive a written commitment showing the offense for which the prisoner was tried, the date of the trial, the exact terms of the judgment or sentence, and the date of the order of the commitment. The clerk shall, under seal of the court, issue such commitment in each case of sentence to imprisonment.\nFinal Provisions"}},{"id":"PH-H3556-A65","no":65,"noLabel":{"en":"Section 65."},"chapter":{"en":"ARTICLE XVII"},"text":{"en":"All elective officials of the city government shall continue in office until the expiration of the term to which they were elected. All appointive officials, officers and employees of the city government shall continue in office and shall automatically be entitled to the benefits and emoluments of this Act without further need of another appointment and confirmation."}},{"id":"PH-H3556-A66","no":66,"noLabel":{"en":"Section 66."},"chapter":{"en":"ARTICLE XVII"},"text":{"en":"Not withstanding the scale of salaries fixed by this Act, the higher rates of salaries that may be provided for by any national salary standardization law shall prevail."}},{"id":"PH-H3556-A67","no":67,"noLabel":{"en":"Section 67."},"chapter":{"en":"ARTICLE XVII"},"text":{"en":"Representative district Provincial Capital. Until otherwise provided by law, the Province of Davao and the City of Davao shall continue as one representative district and the capital of the Province, only for residential purposes of the Provincial Government, shall remain as heretofore."}},{"id":"PH-H3556-A68","no":68,"noLabel":{"en":"Section 68."},"chapter":{"en":"ARTICLE XVII"},"text":{"en":"Provincial buildings and properties. The buildings and properties which the province shall abandon upon the transfer of the capital to another place will be acquired and paid for by the City of Davao at a price to be fixed by the Auditor General."}},{"id":"PH-H3556-A69","no":69,"noLabel":{"en":"Section 69."},"chapter":{"en":"ARTICLE XVII"},"text":{"en":"Repealing clause. All existing laws or parts of law inconsistent with this Act are hereby repealed."}},{"id":"PH-H3556-A70","no":70,"noLabel":{"en":"Section 70."},"chapter":{"en":"ARTICLE XVII"},"text":{"en":"Effectivity. This Act shall take effect upon its approval, except with respect to the salaries provided herein which shall be retroactive as of July one, nineteen hundred sixty-four.\nApproved: June 19, 1965"}}],"pack":"ph-p50"};
  FT["PH-H3557"] = {"id":"PH-H3557","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4355_1965.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定在达沃省Bansalan市镇设立急诊医院，名称为南达沃急诊医院，并授权为此拨款的法案","en":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Bansalan, Province of Davao, to be Known as Southern Davao Emergency Hospital, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Bansalan, Province of Davao, to be Known as Southern Davao Emergency Hospital, and Authorizing the Appropriation of Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Cấp cứu tại Thị trấn Bansalan, Tỉnh Davao với tên gọi Bệnh viện Cấp cứu Southern Davao, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลฉุกเฉินในเทศบาล Bansalan จังหวัด Davao ในชื่อโรงพยาบาลฉุกเฉิน Southern Davao และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Gawat Darurat di Kotamadya Bansalan, Provinsi Davao dengan nama Rumah Sakit Gawat Darurat Southern Davao, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Kecemasan di Perbandaran Bansalan, Wilayah Davao dengan nama Hospital Kecemasan Southern Davao, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 4355","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4355_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3557-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the supervision of the Department of Health an emergency hospital in the Municipality of Bansalan, Province of Davao, to be known as Southern Davao Emergency Hospital, at a site to be determined by the Secretary of Health."}},{"id":"PH-H3557-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, operation and maintenance of said hospital during the fiscal year nineteen hundred and sixty-five, including the purchase of a site and hospital equipment. Thereafter, such sums as may be needed for its operation and maintenance shall be included in the annual General Appropriations Act, in accordance with the provisions of Republic Act Numbered One thousand nine hundred thirty-nine."}},{"id":"PH-H3557-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Establishment of an Emergency Hospital in the Municipality of Bansalan, Province of Davao, to be Known as Southern Davao Emergency Hospital, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3558"] = {"id":"PH-H3558","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4356_1965.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授予 Lourdes B. Gozar 设立、维护和运营无线电广播站及国内与国际电信无线电台的特许经营权法案","en":"An Act Granting Lourdes B. Gozar a Franchise to Establish, Maintain and Operate Radio Broadcasting Stations and Radio Stations for Domestic and International Telecommunications","orig":"An Act Granting Lourdes B. Gozar a Franchise to Establish, Maintain and Operate Radio Broadcasting Stations and Radio Stations for Domestic and International Telecommunications","vi":"Đạo luật cấp quyền khai thác cho Lourdes B. Gozar để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Lourdes B. Gozar เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada Lourdes B. Gozar untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio di Filipina","ms":"Akta memberikan francais kepada Lourdes B. Gozar untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio di Filipina"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 4356","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4356_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3558-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and the provisions of Act Numbered Three thousand eight hundred and forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, there is hereby granted to Lourdes B. Gozar a franchise to establish, maintain and operate in the Philippines and/or at such places as Lourdes B. Gozar may select, subject to the approval of the Secretary of Public Works and Communications, radio broadcasting stations and radio stations for domestic and international telecommunications for the reception and transmission of messages in the domestic and foreign public fixed point-to-point, public based, aeronautical and land mobile stations, including coastal marine service with the corresponding relay stations for the reception and transmission of wireless messages on radiotelegraphy and/or radiotelephony, radioteletype, radiophoto, facsimile, music, pictures, advertisements and such other types of emission from or to foreign countries and within the Philippines and with vessels at sea and aircrafts over the air, irrespective of whether such vessels and aircrafts are within or without the Philippines."}},{"id":"PH-H3558-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace or order, to take over and operate said stations or to authorize the temporary use and operation thereof by any department of the Government without compensating the grantee for such use during the period when they shall be so operated."}},{"id":"PH-H3558-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date the first of said stations shall be placed in operation, and is granted upon the express condition that the same shall be void unless the construction of the first station be begun within two years from the date of the approval of this Act and completed within ten years from said date."}},{"id":"PH-H3558-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"(a) This franchise shall not take effect nor shall any power thereunder be exercised by the grantee until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder and determined the stations to and from which each frequency and wave length may be used, and issued to the grantee a license for such use. (b) The Secretary of Public Works and Communications, upon reasonable notice to the grantee, may at any time change or alter or cancel, in whole or in part, any or all of the allotments of frequencies or wave lengths to be used. He may take such action: (1) when in his judgment such frequencies and wave lengths have been used, or there is danger that they will be used by the grantee to impair electrical communications, or stifle competition of to obtain a monopoly in electrical communication or to secure unreasonable rates for such communications, or to violate otherwise the laws of public policy of the Philippine Republic; and (2) whenever in his judgment the public interests so require that such frequencies or wave lengths be used for other purposes than those of the grantee, either by the Government of the Philippines or by other individuals or corporations licensed by it."}},{"id":"PH-H3558-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The stations of the grantee shall be so constructed and operated at the wave lengths so selected as to avoid interference with existing stations and to permit the expansion of the grantee’s services."}},{"id":"PH-H3558-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H3558-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"No private property shall be taken for any purpose by the grantee without proper condemnation proceedings and just compensation paid or tendered therefor, and any authority to take and occupy land contained herein shall not apply to the taking, use, or occupation of any land except what is required for the actual necessary purposes for which this franchise is granted."}},{"id":"PH-H3558-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall keep an account of the gross receipts of her business and shall furnish the Auditor General and the Treasurer of the Philippines with a copy of such account not later than the thirty-first day of January of each year for the preceding year. All the books and accounts of the grantee pertaining to her business shall be subject to the official inspection of the Auditor General or his authorized representatives and the audit and approval of such accounts shall be final and conclusive evidence as to the amount of said gross receipts, except that the grantee shall have the right to appeal to the courts under the terms and conditions provided for in the laws of the Philippines."}},{"id":"PH-H3558-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, or sell this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity nor merge with any other person, company or corporation organized for the same purpose, without obtaining prior approval of the Congress of the Philippines. Any corporation to which this franchise may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H3558-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H3558-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee shall file a bond in the amount of ten thousand pesos to guarantee the full compliance and fulfillment of the conditions under which this franchise is granted. If after four years from the date of the approval of this Act, the grantee shall have fulfilled said conditions, or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled."}},{"id":"PH-H3558-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"This franchise is likewise made upon the express condition that the grantee shall provide adequate public service time to enable the Government, through her stations, to reach the population on important issues; assist in the function of public information and education; conform to the ethics of honest enterprise, and shall not use her stations for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health and morals, or incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H3558-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act, or scene or other matter to be broadcast from her stations; but if any speech, play, act or scene or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene or other matter: Provided, That the grantee, during any broadcast may cut off from the air the speech, play, act or scene or other matter being broadcast and/or telecast if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or if the language used therein or the theme thereof is indecent or immoral."}},{"id":"PH-H3558-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on her real estate, buildings and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay. (b) The grantee shall further pay to the Treasurer of the Philippines each year, within ten days after the audit and approval of the accounts prescribed in this Act, five per centum of all gross receipts from the business transacted under this franchise by the said grantee."}},{"id":"PH-H3558-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H3558-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"This franchise shall not be interpreted to mean as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H3558-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Lourdes B. Gozar a Franchise to Establish, Maintain and Operate Radio Broadcasting Stations and Radio Stations for Domestic and International Telecommunications","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3559"] = {"id":"PH-H3559","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4357_1965.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Teodoro P. Alberto 设立国内与国际电信无线电台的特许经营权法案","en":"An Act Granting Teodoro P. Alberto a Franchise to Establish Radio Stations for Domestic and International Telecommunications","orig":"An Act Granting Teodoro P. Alberto a Franchise to Establish Radio Stations for Domestic and International Telecommunications","vi":"Đạo luật cấp quyền khai thác cho Teodoro P. Alberto để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh tại Philippines","th":"พระราชบัญญัติให้สัมปทานแก่ Teodoro P. Alberto เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงในฟิลิปปินส์","id":"Undang-Undang memberikan waralaba kepada Teodoro P. Alberto untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio di Filipina","ms":"Akta memberikan francais kepada Teodoro P. Alberto untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio di Filipina"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 4357","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4357_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3559-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and the provisions of Act Numbered Three thousand eight hundred and forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes\"; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, there is hereinafter granted to Teodoro P. Alberto, his successors or assigns, and hereunder referred to as the \"grantee,\" the right and privilege of constructing, installing, establishing and operating in the Philippines, at such places as the grantee may select subject to the approval of the Secretary of Public Works and Communications, radio stations for the reception and transmission of messages on radio stations in the foreign and domestic public fixed point-to-point and public based, aeronautical and land-mobile stations, including coastal marine service with the corresponding relay stations for the reception and transmission of wireless messages on radiotelegraphy and/or radiotelephony, radioteletype, radiophoto, facsimile, music, pictures, advertisement and such other types of emission from or to foreign countries and within the Philippines and with vessels at sea and aircrafts over the air, irrespective of whether such vessels and aircrafts are within or without the Philippines."}},{"id":"PH-H3559-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace or order, to take over and operate the said stations or to authorize the temporary use and operation thereof by any department of the Government without compensating the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H3559-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the construction of said stations or any of them on any land of the public domain upon such terms and conditions as he may prescribe."}},{"id":"PH-H3559-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date the first of said stations shall be placed in operation, and is granted upon the express condition that the same shall be void unless the construction of said station be begun within two years from the approval of this Act, and be completed within four years from said date."}},{"id":"PH-H3559-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"(a) This franchise shall not take effect nor shall any power thereunder be exercised by the grantee until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder and determined the stations to and from which each frequency and wave length may be used, and issued to the grantee a license for such use. (b) The Secretary of Public Works and Communications, or reasonable notice to the grantee, may at any time change, cancel, or modify, in whole or in part, any or all of the allotments of frequencies or wave lengths to be used. He may take such action: (1) whenever in his judgment such frequencies and wave lengths have been used, or there is danger that they will be used by the grantee to impair electrical communications, or stifle competition, or to obtain a monopoly in electrical communications or to secure unreasonable rates for such communications, or to violate otherwise the laws or public policy of the Philippine Republic; (2) whenever in his judgment the public interests of the Republic of the Philippines require that such frequencies or wave lengths should be used for purposes other than those of the grantee, either by the Government of the Philippines or by other individuals or corporations licensed by it; and (3) whenever in his judgment, for any reason, the public interests of the Philippines so require."}},{"id":"PH-H3559-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The stations of the grantee shall be so constructed and operated and the wave lengths so selected as to avoid interference with existing stations and to permit the expansion of the grantee’s services."}},{"id":"PH-H3559-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents of injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H3559-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"No private property shall be taken for any purpose by the grantee without proper condemnation proceedings and just compensation paid or tendered therefor, and any authority to take and occupy land mentioned therein shall not apply to the taking, use or occupation of any land except such as is required for the actual necessary purposes for which this franchise is granted."}},{"id":"PH-H3559-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall keep an account of the gross receipts of his business and shall furnish the Auditor General and the Treasurer of the Philippines with a copy of such account not later than the thirty-first day of January of each year for the preceding year. All the books and accounts of the grantee pertaining to his business shall be subject to the official inspection of the Auditor General or his authorized representatives, and the audit and approval of such accounts shall be final and conclusive evidence as to the amount of said gross receipts, except that the grantee shall have the right to appeal to the courts under the terms and conditions provided for in the laws of the Philippines."}},{"id":"PH-H3559-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H3559-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee, his successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H3559-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guarantee the full compliance and fulfillment of the conditions under which this franchise is granted. If after four years from the date of approval of this Act, the grantee shall have fulfilled said conditions, or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Government."}},{"id":"PH-H3559-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on her real estate, buildings and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay. (b) The grantee shall further pay to the Treasurer of the Philippines each year, within ten days after the audit and approval of the accounts prescribed in this Act three per centum of all gross receipts from the business transacted under this franchise by the said grantee."}},{"id":"PH-H3559-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H3559-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"This franchise shall not be interpreted to mean as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H3559-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Teodoro P. Alberto a Franchise to Establish Radio Stations for Domestic and International Telecommunications","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3560"] = {"id":"PH-H3560","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4358_1965.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"提高市镇官员薪金上限，为此修订第3982号共和国法的法案","en":"An Act to Increase the Maximum Limit of Salaries of Municipal Officers, Amending for the Purpose Republic Act Numbered Thirty-Nine Hundred and Eighty-Two","orig":"An Act to Increase the Maximum Limit of Salaries of Municipal Officers, Amending for the Purpose Republic Act Numbered Thirty-Nine Hundred and Eighty-Two"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4358","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4358_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3560-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section twenty-one hundred and eighty-four of the Revised Administrative Code, as amended by Republic Acts Numbered Twenty-three hundred and sixty-eight and Thirty-nine hundred and eighty-two, is hereby further amended to read as follows:\n\"Sec. 2184. Salaries of municipal officers.— (A) Except as otherwise specially provided herein, the annual salaries of municipal officers in first class, second class, and third class municipalities shall not exceed the amounts hereinbelow fixed:\n\"In municipalities of the first class that have obtained during the next preceding two fiscal years an average total annual revenue of two million five hundred thousand pesos or more (First Class-1): For the mayor, ten thousand eight hundred pesos; for the municipal treasurer, ten thousand two hundred pesos; for the municipal secretary and the chief of police, five thousand four hundred pesos; and for the chief of municipal fire department, four thousand and eighty pesos;\n\"In municipalities of the first class that have obtained during the next preceding two fiscal years an average total annual revenue of one million five hundred thousand pesos or more but less than two million five hundred thousand pesos (First Class-2): For the mayor, ten thousand two hundred pesos; for the municipal treasurer, nine thousand six hundred pesos; for the municipal secretary and the chief of police, five thousand one hundred pesos; and for the chief of municipal fire department, three thousand eight hundred and forty pesos;\n\"In municipalities of the first class that have obtained during the next preceding two fiscal years an average total annual revenue of one million pesos or more but less than one million five hundred thousand pesos (First Class-3); For the mayor, nine thousand six hundred pesos; for the municipal treasurer, nine thousand pesos; for the municipal secretary and the chief of police, four thousand eight hundred pesos; and for the chief of municipal fire department, three thousand six hundred pesos;\n\"In municipalities of the first class that have obtained during the next preceding two fiscal years an average total annual revenue of seven hundred thousand pesos or more but less than one million pesos (First Class-4): For the mayor, nine thousand pesos; for the municipal treasurer, eight thousand four hundred pesos; for the municipal secretary and the chief of police, four thousand five hundred pesos; and for the chief of municipal fire department, three thousand three hundred and sixty pesos;\n\"In municipalities of the first class that have obtained during the next preceding two fiscal years an average total annual revenue of five hundred thousand pesos or more but less than seven hundred thousand pesos (First Class-5): For the mayor, eight thousand four hundred pesos; for the municipal secretary and the chief of police, four thousand two hundred pesos; and for the chief of municipal fire department, three thousand one hundred and twenty pesos;\n\"In other municipalities of the first class with an average total annual revenue of three hundred thousand pesos or more but less than five hundred thousand pesos (First Class-6): For the mayor, seven thousand eight hundred pesos; for the municipal treasurer, seven thousand two hundred pesos; for the municipal secretary and the chief of police, three thousand nine hundred pesos; and for the chief of municipal fire department, two thousand nine hundred and forty pesos;\n\"In municipalities of the second class: For the mayor, seven thousand two hundred pesos; for the municipal treasurer, six thousand six hundred pesos; for the municipal secretary and the chief of police, three thousand six hundred pesos; and for the chief of municipal fire department, two thousand seven hundred and sixty pesos; and \"In municipalities of the third class: For the mayor, six thousand six hundred pesos; for the municipal treasurer, six thousand pesos; for the municipal secretary and the chief of police, three thousand three hundred pesos; and for the chief of municipal fire department, two thousand six hundred and forty pesos.\n\"(B) Subject to the provisions of the last paragraph hereof, the annual salaries of municipal officers in municipalities below third class shall not exceed the amounts hereinbelow fixed:\n\"In municipalities of the fourth class: For the mayor, six thousand pesos; for the municipal treasurer, five thousand four hundred pesos; for the municipal secretary and the chief of police, three thousand pesos; and for the chief of municipal fire department, two thousand four hundred pesos;\n\"In municipalities of the fifth class: For the mayor, five thousand four hundred pesos; for the municipal treasurer, four thousand five hundred and sixty pesos; for the municipal secretary and the chief of police, two thousand seven hundred pesos; and for the chief of municipal fire department, two thousand one hundred and sixty pesos;\n\"In municipalities of the sixth class: For the mayor, four thousand eight hundred pesos; for the municipal treasurer, four thousand and eighty pesos; and for the municipal secretary and the chief of police, two thousand two hundred and eighty pesos;\n\"In municipalities of the seventh class: For the mayor, three thousand six hundred pesos; for the municipal treasurer, three thousand three hundred and sixty pesos; and for the municipal secretary and the chief of police, one thousand nine hundred and twenty pesos.\n\"Two thirds of the salary of the municipal treasurer shall be paid out of municipal funds, in his capacity as such, and one-third thereof out of provincial funds, in his capacity as deputy of the provincial treasurer: Provided, That the provincial board concerned may, in its discretion, authorize as deputy of the provincial treasurer an amount more than the maximum portion fixed herein as payable from provincial funds, provided the corresponding maximum salary rate hereinabove fixed is not exceeded.\n\"Any provision of existing law to the contrary notwithstanding, a municipal treasurer who is appointed to the position of deputy assessor may be allowed additional compensation for his services in such capacity which shall not exceed twenty per centum of his total emolument as deputy provincial and municipal treasurer as hereinabove fixed: Provided, That two-thirds of such additional compensation shall be payable from provincial funds, and one-third thereof from municipal funds.\n\"With the approval of the Provincial Board, the annual salaries of municipal officers of a municipality which is the capital of a province or a sub-province may be fixed at rates higher than those authorized for the class to which the municipality belongs: Provided, That the salaries so fixed shall not exceed the maximum rates authorized for the corresponding officers in the next higher scale of salaries herein established: Provided, further, That in case no higher scale is provided herein, said salaries of officers and of provincial and subprovincial capitals, with the approval of the Provincial Board, be increased by not more than three hundred and sixty pesos per annum.\""}},{"id":"PH-H3560-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"For purposes of the schedule of salaries prescribed for municipal officers of first class municipalities, the Secretary of Finance shall, as of July first, nineteen hundred and sixty-five, and after each period of two consecutive fiscal years thereafter, sub-classify all first class municipalities as classified as such under the provisions of Section twenty-one hundred and seventy-one of the Revised Administrative Code, as amended by Republic Acts Numbered Twenty-three hundred and sixty-eight and Thirty-nine hundred and eighty-two, on the basis of their average annual income during the last two fiscal years immediately preceding the subclassification."}},{"id":"PH-H3560-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All Acts or parts thereof inconsistent with any of the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H3560-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Increase the Maximum Limit of Salaries of Municipal Officers, Amending for the Purpose Republic Act Numbered Thirty-Nine Hundred and Eighty-Two","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3561"] = {"id":"PH-H3561","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4359_1965.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"设立国家血吸虫病防治委员会并授权拨付必要经费的法案","en":"An Act to Create the National Schistosomiasis Control Commission, Authorizing the Necessary Funds Therefor","orig":"An Act to Create the National Schistosomiasis Control Commission, Authorizing the Necessary Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4359","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4359_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3561-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The National Schistosomiasis Control Program is hereby created under the Department of Health to serve as a liaison agency between the government of the Philippines and the WHO/UNICEF, and as a coordinating body to ensure the concerted effort of various agencies concerned in planning and implementing a comprehensive program for schistosomiasis control in endemic and potentially endemic areas of the country."}},{"id":"PH-H3561-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The membership of the Commission shall be composed of the following: The Secretary of Health as chairman, the Secretary of Education, the Secretary of Agriculture and Natural Resources, the Secretary of Public Works and Communications, the Chairman, National Economic Council, the Social Welfare Administrator, the Commissioner of Agricultural Productivity, the Director General of Program Implementation Agency, the National Irrigation Administrator, the Presidential Assistant on Community Development, the General Manager, National Waterworks & Sewerage Authority, the Budget Commissioner, and the President, Philippine Medical Association.\nThe chairman may designate the technical head of the schistosomiasis control program as executive secretary of the Commission. He may also secure the services on detail basis of officials and employees of other branches and agencies of the government to assist the Commission in the discharge of its duties and functions."}},{"id":"PH-H3561-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Commission shall create an executive committee and such other committees or sub-committees as may be necessary for the effective and efficient performance of its duties and proper exercise of its powers and responsibilities.\nUnder the executive committee there shall be created the secretariat and the necessary personnel provided therefor to carry out the administrative and general services functions of the National Schistosomiasis Control Commission."}},{"id":"PH-H3561-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The members of the National Schistosomiasis Control Commission will serve in honorary capacity and shall receive no compensation or remuneration, except traveling expenses and per diems when attending sessions of the Commission, its committees and sub-committees in such amount and under such conditions as the Secretary of Health may prescribe."}},{"id":"PH-H3561-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The National Schistosomiasis Control Commission shall have the following powers and duties:\n(a) Formulate and carry out a comprehensive national schistosomiasis control program.\n(b) Foster effective exchange of information and coordination of projects, programs and activities of various agencies connected with schistosomiasis control.\n(c) Establish effective liaison with participating agencies.\n(d) Submit recommendations to the President on administrative or legislative measures that will effectively carry out the national control program for the disease."}},{"id":"PH-H3561-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Commission, its committees and sub-committees shall meet regularly and may hold such special meetings as the exigencies of the undertaking may demand."}},{"id":"PH-H3561-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"To carry out the provisions of this Act, the sum of two hundred thousand pesos is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, which sum shall be placed at the disposal of the national schistosomiasis control program in the Philippines."}},{"id":"PH-H3561-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"All Acts or parts of Acts, rules and regulations, and executive orders inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H3561-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Create the National Schistosomiasis Control Commission, Authorizing the Necessary Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3562"] = {"id":"PH-H3562","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4360_1965.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"进一步修订《行政法典》第1659条的法案","en":"An Act Further Amending Section Sixteen Hundred and Fifty-Nine of the Administrative Code, as Amended","orig":"An Act Further Amending Section Sixteen Hundred and Fifty-Nine of the Administrative Code, as Amended","vi":"Đạo luật sửa đổi thêm Điều 1659 của Bộ luật Hành chính như đã được sửa đổi","th":"พระราชบัญญัติแก้ไขเพิ่มเติมอีกมาตรา 1659 แห่งประมวลกฎหมายปกครอง ซึ่งแก้ไขเพิ่มเติมแล้ว","id":"Undang-Undang mengubah lagi Pasal 1659 Kitab Undang-Undang Administrasi sebagaimana diubah","ms":"Akta meminda lagi Seksyen 1659 Kanun Pentadbiran sebagaimana dipinda"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4360","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4360_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3562-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section sixteen hundred fifty-nine of the Administrative Code, as amended by Republic Acts Numbered Nine hundred forty-five, Two thousand sixty-eight, Three thousand four hundred sixty five, Three thousand five hundred ninety-six, and Four thousand one hundred thirty-four, is further amended to read as follows:\n\"Sec. 1659. Chief Officials of the Office of the Solicitor General.— The Office of the Solicitor General shall have one chief to be known as the Solicitor General whose salary shall be the same as that of a Justice of the Court of Appeals. He shall be assisted by one First Assistant Solicitor General and six Assistant Solicitors General who shall have the same salary as that of a judge of the Court of First Instance. When the Solicitor General is unable to perform his duties or in case of vacancy in the Office, the First Assistant Solicitor General shall temporarily perform the functions of said Officer, or in his absence, the next Assistant Solicitor General who is senior in the service. There shall also be fifty-three Solicitors whose salaries shall be as follows:\n\"(a) Six Solicitors, each of whom shall receive an annual salary of six hundred pesos less than the annual salary of the Assistant Solicitor General;\n\"(b) Six Solicitors, each of whom shall receive an annual salary of six hundred pesos less than that provided for in the next preceding subparagraph (a);\n\"(c) Six Solicitor, each of whom shall receive an annual salary of six hundred pesos less than that provided for in the next preceding subparagraph (b);\n\"(d) Six Solicitors, whose salary shall each be six hundred pesos less than the salary provided for in the next preceding subparagraph (c);\n\"(e) Five Solicitors, whose salary shall each be six hundred pesos less than the salary provided for in the next preceding subparagraph (d);\n\"(f) Three Solicitors, whose salary shall each be six hundred pesos less than the salary provided for in the next preceding subparagraph (e);\n\"(g) Three Solicitors, whose salary shall each be six hundred pesos less than the salary provided for in the next preceding subparagraph (f );\n\"(h) Three Solicitors, whose salaries shall be six hundred pesos less than the salary provided for in the next preceding subparagraph (g);\n\"(i) Three Solicitors, whose salaries shall be six hundred pesos less than the salary provided for in the next preceding subparagraph (h);\n\"(j) Three Solicitors, whose salaries shall be six hundred pesos less than the salary provided for in the next preceding subparagraph (i);\n\"(k) Three Solicitors, whose salaries shall be six hundred pesos less than the salary provided for in the next preceding subparagraph (j);\n\"(l) Three Solicitors, whose salaries shall be six hundred pesos less than the salary provided for in the next preceding subparagraph (k);\n\"(m) Three Solicitors, whose salaries shall be six hundred pesos less than the salary provided for in the next preceding subparagraph (l).\n\"The rank, privileges, and qualifications for appointment to the position of Solicitor General shall be the same as an Associate Justice of the Court of Appeals; the rank, privileges, and qualifications for appointment to the position of the First Assistant Solicitor General and the Assistant Solicitors General shall be the same as those prescribed for Judges of Courts of First Instance, and those of Solicitors shall be the same as those prescribed for provincial fiscals.\""}},{"id":"PH-H3562-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section two Republic Act Numbered Three thousand five hundred ninety-six is amended to read as follows:\n\"Sec. 2. Any existing law to the contrary notwithstanding, there shall also be eight Trial Attorneys to be appointed by the Secretary of Justice upon recommendation of the Solicitor General, and whose salaries shall be as follows:\n\"(a) Two Trial Attorneys, seven thousand eight hundred pesos per annum each;\n\"(b) Two Trial Attorneys, seven thousand two hundred pesos per annum each;\n\"(c) Two Trial Attorneys, six thousand six hundred pesos per annum each;\n\"(d) Two Trial Attorneys, six thousand pesos per annum each.\n\"The incumbent Solicitor General, First Assistant Solicitor General, and all incumbent Assistant Solicitors General, Solicitors and Trial Attorneys occupying positions affected by the preceding section at the time of effectivity of this Act, shall continue to occupy their respective positions and receive the salary increased herein provided without the necessity of any new appointment.\""}},{"id":"PH-H3562-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In addition to such sums as may have been provided in the current Appropriations Act, there is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, such sums as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H3562-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Further Amending Section Sixteen Hundred and Fifty-Nine of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3563"] = {"id":"PH-H3563","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4361_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Eighty Thousand Pesos for Operational Expenses and Other Incidental Expenses of the Eastern Regional Organization for Public Administration for its Coming Consultative Meeting of the Representatives of Member Nations to be Held in Manila, Philippines, in September, 1965","orig":"An Act Appropriating Eighty Thousand Pesos for Operational Expenses and Other Incidental Expenses of the Eastern Regional Organization for Public Administration for its Coming Consultative Meeting of the Representatives of Member Nations to be Held in Manila, Philippines, in September, 1965"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4361","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4361_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3563-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"For the purpose of defraying the operational other incidental expenses including the expenses for a consultative meeting, and the living and transportation expenses of experts, of the holding of the Eastern Regional Organization for Public Administration (EROPA) in Manila in September, 1965, the sum of eighty thousand pesos is hereby appropriated out of any funds in the National Treasury not otherwise appropriated, which sum shall be disbursed by the Department of Foreign Affairs."}},{"id":"PH-H3563-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50"};
  FT["PH-H3564"] = {"id":"PH-H3564","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4362_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订《菲律宾非农业合作社法》第66条的法案","en":"An Act to Amend Section Sixty-Six of the Philippine Non-Agricultural Co-Operative Act","orig":"An Act to Amend Section Sixty-Six of the Philippine Non-Agricultural Co-Operative Act"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 4362","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4362_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3564-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subsection (2) of Section sixty-six of Republic Act Numbered Two thousand and twenty-three, otherwise known as the Philippine Non-agricultural Cooperative Act, is amended to read as follows:\n\"Sec. 66. Exemptions.— Co-operatives registered under this Act shall, notwithstanding the provisions of existing law to the country, enjoy the following exemptions:\n\"(1) Co-operatives with net assets of not more than five hundred thousand pesos shall be exempt from all taxes and government fees of whatever name and nature except those provided for under this Act: Provided, However, That co-operatives having net assets in excess of five hundred thousand pesos shall pay taxes as provided hereunder:\n(a) Income Tax— they shall pay tax at the full rate as provided under existing laws on the amount allocated for interest on capital;\n(b) Sales Tax— they shall pay fixed and percentage taxes at the full rate as provided under existing laws; and\n(c) They shall pay all other taxes, unless otherwise provided herein at the full rate as provided under existing laws.\n\"(2) They shall be exempt from the payment of documentary stamp tax, residence taxes, tax on banks and insurance companies and municipal or city taxes: Provided, However, That no co-operative organized under this Act shall be exempt from the payment of specific taxes levied by the National Internal Revenue Code on all articles or merchandise manufactured by such co-operative.\""}},{"id":"PH-H3564-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Section Sixty-Six of the Philippine Non-Agricultural Co-Operative Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3565"] = {"id":"PH-H3565","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4363_1965.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"进一步修订《修订刑法典》第360条的法案","en":"An Act Further Amend Article Three Hundred Sixty of the Revised Penal Code","orig":"An Act Further Amend Article Three Hundred Sixty of the Revised Penal Code"},"level":"law","status":"active","topics":["criminal"],"docNumber":"Republic Act No. 4363","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4363_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3565-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Article three hundred sixty of the Revised Penal Code, as amended by Republic Act Numbered Twelve hundred and eighty-nine, is further amended to read as follows:\n\"Art. 360. Persons responsible. Any person who shall publish, exhibit, or cause the publication or exhibition of any defamation in writing or by similar means, shall be responsible for the same.\n\"The author or editor of a book or pamphlet, or the editor or business manager of a daily newspaper, magazine or serial publication, shall be responsible for the defamations contained therein to the same extent as if he were the author thereof.\n\"The criminal and civil action for damages in cases of written defamations as provided for in this chapter, shall be filed simultaneously or separately with the court of first instance of the province or city where the libelous article is printed and first published or where any of the offended parties actually resides at the time of the commission of the offense: Provided, however , That where one of the offended parties is a public officer whose office is in the City of Manila at the time of the commission of the offense, the action shall be filed in the Court of First Instance of the City of Manila or of the city or province where the libelous article is printed and first published, and in case such public officer does not hold office in the City of Manila, the action shall be filed in the Court of First Instance of the province or city where he held office at the time of the commission of the offense or where the libelous article is printed and first published and in case one of the offended parties is a private individual, the action shall be filed in the Court of First Instance of the province or city where he actually resides at the time of the commission of the offense or where the libelous matter is printed and first published: Provided, further , That the civil action shall be filed in the same court where the criminal action is filed and vice versa: Provided, furthermore , That the court where the criminal action or civil action for damages is first filed, shall acquire jurisdiction to the exclusion of other courts: And provided, finally , That this amendment shall not apply to cases of written defamations, the civil and/or criminal actions to which have been filed in court at the time of the effectivity of this law.\n\"Preliminary investigation of criminal actions for written defamations as provided for in the chapter shall be conducted by the provincial or city fiscal of the province of city, or by the municipal court of the city or capital of the province where such actions may be instituted in accordance with the provisions of this article.\n\"No criminal action for defamation which consists in the imputation of a crime which cannot be prosecuted de officio shall be brought except at the instance of and upon complaint expressly filed by the offended party.\""}},{"id":"PH-H3565-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"If any section or sections of this Act shall be declared unconstitutional or invalid, it shall not invalidate the other sections hereof."}},{"id":"PH-H3565-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect only if and when, within thirty days from its approval, the newspapermen in the Philippines shall organize, and elect the members of, a Philippine Press Council, a private agency of the said newspapermen, whose function shall be to promulgate a Code of Ethics, for them and the Philippine press, investigate violations thereof, and censure any newspaperman or newspaper guilty of any violation of the said Code, and the fact that such Philippine Press Council has been organized and its members have been duly elected in accordance herewith shall be ascertained and proclaimed by the President of the Philippines.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Further Amend Article Three Hundred Sixty of the Revised Penal Code","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3566"] = {"id":"PH-H3566","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4364_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订选举法典","en":"The Revised Election Code","orig":"An Act to Amend Republic Act Numbered One Hundred Eighty Entitled \"The Revised Election Code\"","vi":"Bộ luật Bầu cử (sửa đổi)","th":"ประมวลกฎหมายการเลือกตั้ง (ฉบับแก้ไข)","id":"Kitab Undang-Undang Pemilihan Umum (Revisi)","ms":"Kanun Pilihan Raya (Semakan)"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4364","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4364_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3566-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Republic Act Numbered One Hundred eighty is hereby amended by inserting between Sections five and six thereof a new section, which shall read as follows:\n\"Sec. 5-A. Any provision of existing law to the contrary notwithstanding, the Commission on Elections may authorize the payment of compensation from appropriations provided for election to its officials and employees, and those assigned thereto, except the Chairman and members of the said Commission, for overtime services rendered on Saturdays, Sundays and holidays, or after required office hours on regular working days in connection with election, at rates to be fixed by the Commission on Elections which shall not exceed the rates of their regular monthly compensation. Such additional compensation shall not exceed, for any one month, the equivalent of their regular monthly compensation.\""}},{"id":"PH-H3566-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"The Revised Election Code","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3567"] = {"id":"PH-H3567","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4365_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将莱特省Bugho市镇的名称正式变更为Javier市镇的法案","en":"An Act Changing the Name of the Municipality of Bugho in the Province of Leyte, to the Municipality of Javier","orig":"An Act Changing the Name of the Municipality of Bugho in the Province of Leyte, to the Municipality of Javier","vi":"Đạo luật đổi tên Thị trấn Bugho tại Tỉnh Leyte thành Thị trấn Javier","th":"พระราชบัญญัติเปลี่ยนชื่อเทศบาล Bugho ในจังหวัด Leyte เป็นเทศบาล Javier","id":"Undang-Undang mengubah nama Kotamadya Bugho di Provinsi Leyte menjadi Kotamadya Javier","ms":"Akta menukar nama Perbandaran Bugho di Wilayah Leyte menjadi Perbandaran Javier"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4365","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4365_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3567-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Municipality of Bugho in the Province of Leyte is hereby changed to the Municipality of Javier."}},{"id":"PH-H3567-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Municipality of Bugho in the Province of Leyte, to the Municipality of Javier","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3568"] = {"id":"PH-H3568","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4366_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"农业土地改革法典","en":"Agricultural Land Reform Code","orig":"An Act to Amend the Third Paragraph of Subsection (2) of Section One Hundred Fifty-Eight of Republic Act Numbered Thirty-Eight Hundred Forty-Four, Otherwise Known as the \"Agricultural Land Reform Code\"","vi":"Bộ luật Cải cách Ruộng đất Nông nghiệp","th":"ประมวลกฎหมายปฏิรูปที่ดินเพื่อเกษตรกรรม","id":"Kitab Undang-Undang Reformasi Agraria","ms":"Kanun Pembaharuan Tanah Pertanian"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 4366","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4366_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3568-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The third paragraph of subsection two of Section one hundred fifty-eight of the \"Agricultural Land Reform Code,\" is hereby amended to read as follows:\n\"The Clerks of Court shall each receive an annual compensation of not less than seven thousand two hundred pesos. They shall exercise the same powers and perform the same duties on all matters within the jurisdiction of the Courts as those exercised by the Clerks of Court of the Courts of First Instance.\""}},{"id":"PH-H3568-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Agricultural Land Reform Code","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3569"] = {"id":"PH-H3569","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4367_1965.html","fetchedAt":"2026-10-06","articleCount":13,"structureMode":"ARTICLE","title":{"zh":"授予 Aldymac，Inc. 在 Legazpi 市设立、维护和运营无线电广播与电视站的特许经营权法案","en":"An Act Granting Aldymac, Inc. a Franchise to Establish, Maintain and Operate Radio Broadcasting and Television Stations in the City of Legazpi","orig":"An Act Granting Aldymac, Inc. a Franchise to Establish, Maintain and Operate Radio Broadcasting and Television Stations in the City of Legazpi","vi":"Đạo luật cấp quyền khai thác cho Aldymac, Inc. để xây dựng, lắp đặt, vận hành và duy trì hệ thống phát thanh và truyền hình tại Thành phố Legazpi","th":"พระราชบัญญัติให้สัมปทานแก่ Aldymac, Inc. เพื่อก่อสร้าง ติดตั้ง ดำเนินการ และบำรุงรักษาระบบวิทยุกระจายเสียงและวิทยุโทรทัศน์ในเมือง Legazpi","id":"Undang-Undang memberikan waralaba kepada Aldymac, Inc. untuk membangun, memasang, mengoperasikan, dan memelihara sistem penyiaran radio dan televisi di Kota Legazpi","ms":"Akta memberikan francais kepada Aldymac, Inc. untuk membina, memasang, mengendalikan dan menyelenggara sistem penyiaran radio dan televisyen di Bandaraya Legazpi"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 4367","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 13 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4367_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3569-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, as well as of Act Numbered Three thousand eight hundred forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Three thousand nine hundred ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, not inconsistent with this Act, Aldymac, Inc., is hereby granted a franchise to establish, maintain and operate radio broadcasting and television stations in the City of Legazpi."}},{"id":"PH-H3569-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This franchise shall continue for a period of twenty-five years from the date said stations shall be put in operation, and is granted upon the express conditions that the same shall be void unless the construction of at least one radio broadcasting stations or one television station be begun within one year from the date of approval of this Act and be completed within two years from said date."}},{"id":"PH-H3569-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This franchise is likewise made upon the express condition that the grantee shall provide adequate public service time to enable the government, thru its stations, to reach the population on important issues, shall assist in the functions of public information and education, shall conform to the ethics of honest enterprise, and shall not use its stations for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health and morals, or incite, encourage or assist in subversive or treasonable acts."}},{"id":"PH-H3569-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee’s radio broadcasting and television stations shall not be put in actual operation until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used under this franchise and issued to the grantee license for such use."}},{"id":"PH-H3569-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The radio broadcasting station and television stations of the grantee shall be so constructed and operated and wave lengths so selected as to avoid interference with existing radio stations and television stations and to permit the expansion of the grantee’s service."}},{"id":"PH-H3569-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace or order, to cause the closing of said stations or to authorize the temporary use and operation thereof by any department of the government without compensating the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H3569-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall be liable to pay the same taxes unless exempted therefrom, on its real estate, buildings and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay. It shall be liable further to pay all other taxes as provided in the National Internal Revenue Code by reason of this franchise."}},{"id":"PH-H3569-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Acceptance of this franchise shall be given in writing by the grantee within six months after the approval of this Act. When so accepted, the grantee shall be empowered to exercise the privileges granted thereby."}},{"id":"PH-H3569-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall file a bond in the amount of ten thousand pesos to guarantee the full compliance with fulfillment of the conditions under which this franchise is granted. If after two years from the date of acceptance of this franchise, the grantee shall have fulfilled said conditions or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H3569-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall not require any previous censorship of any speech, play, act, or scene of other matter to be broadcast and/or telecast from its stations; but if any speech, play, act, or scene or other matter should constitute a violation of the law or infringement of a private right,, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene or other matter: Provided, That the grantee, during any broadcast and/or telecast may cut off from the air the speech, play, act or scene or other matter being broadcast and/or telecast if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral."}},{"id":"PH-H3569-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and as completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H3569-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H3569-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Aldymac, Inc. a Franchise to Establish, Maintain and Operate Radio Broadcasting and Television Stations in the City of Legazpi","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3570"] = {"id":"PH-H3570","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4368_1965.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"设立国家历史委员会、界定其权力与职能、授权为此拨款并为其他目的法案","en":"An Act to Establish a National Historical Commission, to Define its Powers and Functions, Authorizing the Appropriation of Funds Therefor, and for Other Purposes","orig":"An Act to Establish a National Historical Commission, to Define its Powers and Functions, Authorizing the Appropriation of Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["culture"],"docNumber":"Republic Act No. 4368","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4368_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3570-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created a National Historical Commission which shall be composed of a Chairman and four regular members and two ex-officio members, namely, the Director of Public Libraries and the Director of the National Museum: Provided, That the ex-officio members shall not receive any compensation and shall not have the right to vote."}},{"id":"PH-H3570-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Chairman and four members shall be appointed by the President of the Philippines with the consent of the Commission on Appointments. No one shall be appointed to any of these positions unless he be a citizen of the Philippines, at least thirty years old, at least a holder of a four-year college degree, and has distinguished himself in historical research and writing. The Chairman shall receive a compensation of twelve thousand pesos per annum, and the four members shall each receive eight thousand four hundred pesos per annum."}},{"id":"PH-H3570-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The National Historical Commission shall be under the direct control and supervision of the Department of Education. The Chairman and the four members shall hold office during good behavior until they reach retirement age or until they shall have been incapacitated to discharge their duties effectively."}},{"id":"PH-H3570-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"It shall be the duty of the National Historical Commission:\n(a) To publish or cause to have written or published the works of our national heroes and other great an d good Filipinos;\n(b) To compile from various sources here and abroad data on Philippine history and prepare and publish there from source books on Philippine history;\n(c) For the purpose stated in subparagraph (a) and (b), to enter into negotiations or agreements, subject to the approval of the Secretary of Education, with institutions of learning, learned societies and individuals for the purpose of securing original documents of copies, photostat and microfilms thereof, dealing with the Philippines: Provided, That any acquisition involved in excess of fifty thousand pesos shall be with the approval of the President of the Philippines;\n(d) To gather and publish source books, reports, records and other valuable information relating to historic places, markets and events;\n(e) To identify, designate and appropriately mark historic places in the Philippines and to cause the construction or reconstruction and to maintain and care for national monuments, shrines and historic markets that have been or may hereafter be erected in pursuance of this Act: Provided, However, That the Commission shall enlist the assistance of the public;\n(f) To take charge of all historical activities or projects, not otherwise undertaken by any entity of the government;\n(g) To gather data on historical dates, personages, events, and documents presented for evaluation, and to acquire through purchase, donation, exchange or otherwise, important historical documents and materials;\n(h) To encourage researches in Philippine history and the writing and publication of textbooks on the subject, the research and writing of biographies of heroes, accounts of historical events, translation of important scholarly works of Filipino and foreigners by providing appropriate or adequate incentives, setting aside, for this purpose, such portions of its appropriation as the Commission may deem necessary; and\n(i) To work in coordination with the Institute of National Language for the translation of its works and materials to the National Language."}},{"id":"PH-H3570-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The publications and other reading materials distributed by the National Historical Commission shall be accepted by the Bureau of Post free of charge."}},{"id":"PH-H3570-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Philippine Historical Committee and the existing National Heroes Commission are hereby abolished and their functions shall be performed by the National Historical Commission. All personnel, documents, materials, equipment, and unexpected balances belonging to those agencies are hereby transferred to the National Historical Commission."}},{"id":"PH-H3570-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"To carry out the objectives of this Act the Department of Education is hereby empowered to designate existing agencies to implement the policies adopted and activities programmed by the National Historical Commission as stated in Section two hereof."}},{"id":"PH-H3570-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The Commission, upon the recommendation of the Chairman, shall appoint such personnel as may be deemed necessary; shall fix their compensation; prescribe their duties; and establish such methods and procedures as may ensure the efficient, honest and economical administration of the provisions and purpose of this Act."}},{"id":"PH-H3570-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"There is hereby authorized to be appropriated out of any funds in the National Treasury not otherwise appropriated, the sum of five hundred thousand pesos for the operation of the National Treasury not otherwise appropriated, the sum of five hundred thousand pesos for the operation of the National Historical Commission. This amount shall be included in the annual General Appropriations Act of the Philippine Government next fiscal year. Any unexpected balance of the appropriation of the Commission shall be reverted to the National Treasury."}},{"id":"PH-H3570-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"All laws, Acts, parts of acts, executive orders and administrative regulations which are inconsistent with this Act are hereby repealed."}},{"id":"PH-H3570-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Establish a National Historical Commission, to Define its Powers and Functions, Authorizing the Appropriation of Funds Therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3571"] = {"id":"PH-H3571","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4369_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"进一步修订经修正的第2957号法第2条的法案","en":"An Act to Further Amend Section Two of Act Numbered Twenty-Nine Hundred Fifty-Seven, as Amended","orig":"An Act to Further Amend Section Two of Act Numbered Twenty-Nine Hundred Fifty-Seven, as Amended","vi":"Đạo luật sửa đổi thêm Điều 2 của Đạo luật số 2957 như đã được sửa đổi","th":"พระราชบัญญัติแก้ไขเพิ่มเติมอีกมาตรา 2 แห่งพระราชบัญญัติที่ 2957 ซึ่งแก้ไขเพิ่มเติมแล้ว","id":"Undang-Undang mengubah lagi Pasal 2 Undang-Undang No. 2957 sebagaimana diubah","ms":"Akta meminda lagi Seksyen 2 Akta No. 2957 sebagaimana dipinda"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4369","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4369_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3571-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two of Act Numbered twenty-nine hundred fifty-seven, as amended, is hereby further amended to read as follows:\n\"Sec. 2. The Board of Textbooks shall be composed of seven members to be appointed by the President of the Philippines with the consent of the Commission on Appointments: Provided, That at least one of the seven shall be from among the Muslims and other national cultural minorities and the other two to be the Director of Public Schools and the Director of Private Schools. The members of the Board shall hold office for a period of six years and shall be entitled to a per diem in an amount to be fixed by the board and approved by the Secretary of Education, except those who are receiving a fixed salary from the government or any of its subdivisions and instrumentalities. In making the appointment of the first board, two members shall be appointed for a period of two years, two members for a period of four years, and one member for a period of six years. Every two years the board shall select a chairman from among its members.\nAll members of said board shall be citizens of the Philippines.\nIt shall be unlawful for the board to consider for adoption or to adopt any treatise, textbook, or manuscript in whose authorship, editorship, or preparation a member of the Board may have direct or indirect interest: Provided, That this prohibition shall not apply to the deliberation of the board to consider for adoption or to adopt any treatise, textbook, or manuscript written by any member thereof during the period of his incumbency who shall not participate in said deliberation: Provided, further, That said treatise, textbook, or manuscript shall be turned over to the government which may undertake the printing and distribution thereof. It shall likewise be unlawful for any member of the board, during the period of his incumbency, to own, directly or indirectly, any interest whatsoever in any firm, partnership, or corporation publishing or dealing in school textbooks."}},{"id":"PH-H3571-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Amend Section Two of Act Numbered Twenty-Nine Hundred Fifty-Seven, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3572"] = {"id":"PH-H3572","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4370_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第477号共和国法第8条的法案","en":"An Act to Amend Section Eight of Republic Act Numbered Four Hundred Seventy-Seven","orig":"An Act to Amend Section Eight of Republic Act Numbered Four Hundred Seventy-Seven","vi":"Đạo luật sửa đổi Điều 8 của Đạo luật Cộng hòa số 477","th":"พระราชบัญญัติแก้ไขเพิ่มเติมมาตรา 8 แห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 477","id":"Undang-Undang mengubah Pasal 8 Undang-Undang Republik No. 477","ms":"Akta meminda Seksyen 8 Akta Republik No. 477"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4370","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4370_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3572-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eight of Republic Act Numbered Four hundred seventy-seven is hereby amended to read as follows:\n\"Sec. 8. Except in favor of the Government or any of its branches, units, or institutions, and of any church, sect or denomination for its church and/or cemetery site, land acquired under the provisions of this Act or any permanent improvements thereon shall not be subject to encumbrance or alienation from the date of the award of the land or the improvements thereon and for a term of ten years from and after the date of issuance of the certificate of title, nor shall they become liable to the satisfaction of any debt contracted prior to the expiration of such period.\n\"Any occupant or applicant of lands under this Act who transfer whatever rights he has acquired on said lands and/or improvements thereon before the date of the award or signature of the contract of sale, shall not be entitled to apply for another piece of agricultural land or urban, homesite or residential lot, as the case may be, from the National Abaca and Other Fibers Corporation; and such transfer shall be considered null and void.\""}},{"id":"PH-H3572-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Section Eight of Republic Act Numbered Four Hundred Seventy-Seven","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3573"] = {"id":"PH-H3573","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4371_1965.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"进一步延长依第65号共和国法（经修正）申请教育福利的期限的法案","en":"An Act to Further Extend the Filing of Applications for Educational Benefits Under Republic Act Numbered Sixty-Five, as Amended","orig":"An Act to Further Extend the Filing of Applications for Educational Benefits Under Republic Act Numbered Sixty-Five, as Amended"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4371","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4371_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3573-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Officers and enlisted men and the widow or child of deceased veterans who although entitled to the benefits of Section two of Republic Act Numbered Sixty-five, as amended, have failed to establish their rights within the period set forth therein (as well as in the additional periods granted by Congress in Republic Acts Numbered Five hundred seventy-seven, Thirteen hundred sixty-two and Eighteen hundred eighty-six), are hereby granted an additional period of two years from the approval of this Act within which to file their applications for educational benefits under the provisions of the aforementioned Act."}},{"id":"PH-H3573-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon the approval of this Act, the Philippine Veterans Administration shall cause the widest possible dissemination of the provisions of Section one hereof so as to reach the greater number of the population and shall render to the claimants concerned such necessary assistance as may be deemed proper."}},{"id":"PH-H3573-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is hereby authorized to be appropriated out of any funds not otherwise appropriated the necessary sum as may be needed to implement the provisions of this Act, not to exceed twenty thousand pesos."}},{"id":"PH-H3573-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Extend the Filing of Applications for Educational Benefits Under Republic Act Numbered Sixty-Five, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3574"] = {"id":"PH-H3574","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4372_1965.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"修订第 1124 号共和国法（即设立国家教育委员会、负责制定普通教育政策并指导全国教育事务的法案）的法案","en":"An Act to Amend Republic Act Numbered Eleven Hundred and Twenty-Four Entitled \"An Act Creating a Board of National Education Charged with the Duty of Formulating General Educational Policies and Directing the Educational Interests of the Nation\"","orig":"An Act to Amend Republic Act Numbered Eleven Hundred and Twenty-Four Entitled \"An Act Creating a Board of National Education Charged with the Duty of Formulating General Educational Policies and Directing the Educational Interests of the Nation\"","vi":"Đạo luật sửa đổi Đạo luật Cộng hòa số 1124","th":"พระราชบัญญัติแก้ไขเพิ่มเติมพระราชบัญญัติแห่งสาธารณรัฐที่ 1124","id":"Undang-Undang mengubah Undang-Undang Republik No. 1124","ms":"Akta meminda Akta Republik No. 1124"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4372","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4372_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3574-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Eleven hundred and twenty-four is hereby amended to read as follows:\n\"Sec. 1. There is hereby created a Board of National Education which is hereby authorized to formulate general education objectives and policies, coordinate the offerings, activities and functions of all educational institutions in the country with a view to carry out the provisions of the constitution and to accomplishing an integrated, well rounded nationalistic and democracy-inspired educational system in the Philippines.\""}},{"id":"PH-H3574-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section two, of Republic Act Numbered Eleven hundred and twenty-four is hereby amended to read as follows:\n\"Sec. 2. The Board of National Education shall be composed of eight members as follows:\n(a) The Secretary of Education\n(b) The Chairman of the Committee on Education in the House of Representatives\n(c) The Chairman of the Committee on Education in the Senate\n(d) The President of the University of the Philippines; and\n(e) Four other members who shall be appointed by the President of the Philippines with the consent of the Commission of Appointment, one from each of the following groups:\n(a) Catholic Educational Association of the Philippines;\n(b) Muslim Association of the Philippines;\n(c) Philippine Association of Christian Schools;\n(d) Philippine Association of Colleges and Universities.\""}},{"id":"PH-H3574-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section three of the same Act is hereby amended to read as follows:\n\"Sec. 3. The Secretary of Education shall act as Chairman of the Board. A Vice-Chairman shall be elected from among the members of the Board who shall act as Chairman in the absence of the Secretary of Education. The Chairman and members of the Board shall be entitled to a per diem of fifty pesos (₱50) for actual attendance of the meeting of the Board which shall not exceed five hundred pesos (₱500) a month.\nThe Board shall have a regular meeting at least twice a month and may have as many social meetings as may be necessary at the call of the Chairman or any three members thereof.\""}},{"id":"PH-H3574-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section four of the same Act is hereby amended by adding and inserting therein, subsections (d), (e), (f), and (g) to read as follows:\n(d) To establish guidelines, policies, and criteria on the basis of which the examination, evaluation, and approval of textbooks by the Board of Textbooks shall be made.\n(e) To compile educational statistics, keep records on education, conduct researches, surveys, and studies on educational conditions and problems, evaluate the effects of national educational policies, and undertake such other activities as to effectivity carry out the purpose of this Act.\n(f) To secure data and information from all government offices and entities and educational institutions, public and private, and to consults and confer with the officers and personnel thereof, on such matter as may be necessary for the Board to discharge its functions.\n(g) To submit an annual report to the President and to Congress not later than January thirty-first of each year which shall include a compilation of the national educational policies formulated by the Board, an evaluation of the national educational system, and recommendations of the Executive and Legislative Branches of the government on the improvement of the educational system of the country."}},{"id":"PH-H3574-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section five of the same Act s hereby amended to read as follows:\n\"Sec. 5. It shall be the agency of the Government for the formulation of educational policies and the directly of the educational interest of the nation, subject only to the constitutional authority to the Congress and the President of the Republic over executive departments, bureaus and offices.\""}},{"id":"PH-H3574-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section seven of the same Act is amended to read as follows:\n\"Sec. 7. The Board shall appoint a Secretary who shall have the rank of undersecretary of a department and shall have a secretariat composed of an administrative, research, and technical staff as may be necessary to carry out its determined, whose qualification and compensation shall be determined by the Board subject to existing laws: Provided, That no officer or employee in the existing staff of the compensation lower than that now received by him or to which he is entitled under existing laws.\""}},{"id":"PH-H3574-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section nine of the same Act is hereby amended to read as follows:\n\"Sec. 9. The sum of One million pesos or so much thereof as may be necessary to carry out the purposes of this Act, is hereby appropriated out of any funds in the national Treasury not otherwise appropriated.\""}},{"id":"PH-H3574-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"All laws, rules and regulations contrary to the provisions of this Act are hereby repealed."}},{"id":"PH-H3574-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Republic Act Numbered Eleven Hundred and Twenty-Four Entitled \"An Act Creating a Board of National Education Charged with the Duty of Formulating General Educational Policies and Directing the Educational Interests of the Nation\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3575"] = {"id":"PH-H3575","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4373_1965.html","fetchedAt":"2026-10-06","articleCount":29,"structureMode":"ARTICLE","title":{"zh":"规范菲律宾社会工作执业及社会工作机构运营并为其他目的法案","en":"An Act to Regulate the Practice of Social Work and the Operation of Social Work Agencies in the Philippines and for Other Purposes","orig":"An Act to Regulate the Practice of Social Work and the Operation of Social Work Agencies in the Philippines and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4373","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 29 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4373_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3575-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"As used in this Act:\na. Social work is the profession which is primarily concerned with organized social service activity aimed to facilitate and strengthen basic social relationships and the mutual adjustment between individuals and their social environment for the good of the individual and of society by the use of social work methods.\nb. A \"social worker\" as used in this Act is a practitioner who by accepted academic training and social work professional experience possesses the skill to achieve the objectives as defined and set by the social work profession, through the use of the basic methods and techniques of social work (case work, group work, and community organization) which are designed to enable individuals, groups and communities to meet their needs and to solve the problems of adjustment to a hanging pattern of society and, through coordinated action, to improve economic and social conditions, and is connected with an organized social work agency which is supported partially or wholly from government or community solicited funds.\nc. A \"social work agency\" is a person, corporation or organization, private or governmental, that engages mainly and generally, or represents itself to engage in social welfare work, whether case work, group work, or community work, and obtains its finances, either totally or in part, from any agency or instrumentality of the government and/or from the community by direct or indirect solicitations and/or fund drives, and/or private endowment.\nOrganization of the Board of Examiners for Social Workers"}},{"id":"PH-H3575-A2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Name and Composition of the Board Within Sixty Days After the Approval of This Act.— there shall be created a Board of Examiners for Social Workers hereinafter to be referred to as the Board, composed of a Chairman and four members who shall be appointed by the President of the Philippines with the consent of the Commission on Appointments from among social workers of recognized standing in the Philippines, and who, at the time of their appointment shall:\na. Be a citizen and resident of the Philippines;\nb. Be at least thirty years of age and of good moral character;\nc. Possess a Master’s Degree in Social Work (M.S.S.W., M.S.S., M.A.S.W., or its equivalent) conferred by a reputable school, college or university duly recognized by the government and also by a duly accredited school, college or university abroad.\nd. Have had at least five years of practice in a social work agency in the case of a holder of Bachelor’s Degree in Social Work or its equivalent, or at least two years of social work practice in the case of a holder of a Master’s Degree in Social Work or its equivalent, after receiving the respective degree.\ne. Be a registered social worker duly qualified to practice social work under this Act: Provided, However, That this qualification shall not be required of the first appointees to the Board under this Act, and;\nf. Not be a member of the faculty of any school, college or university at the time of appointment; nor during the year immediately preceding the appointment to be a member of the Board conferring the Bachelor’s and/or Master’s degree in social work, or shall have any direct or indirect pecuniary interest in such institution."}},{"id":"PH-H3575-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Function and Duties of the Board.— The Board shall have the following function and duties:\na. To administer the provisions of this Act;\nb. To administer oaths in connection with the administration of this Act;\nc. To prepare the official seal of the Board ;\nd. To issue, suspend, and revoke certificates of registration for the practice of social work;\ne. To look into the conditions affecting the practice of social work in the Philippines, and, whenever necessary, adopt such measures as may be deemed proper for the maintenance of the good standing and the ethics of the profession of social work; and\nf. To investigate such violations of this Act or of the rules and regulations issued thereunder as may come to the knowledge of the Board , and, for this purpose, to issue subpoena and subpoena duces tecum to secure the appearance of witnesses and the production of documents in connection therewith."}},{"id":"PH-H3575-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Term of Office.— The members of the Board shall hold office for a term of three years or until their successors shall have been appointed and duly qualified: Provided, That the members of the first Board appointed under this Act shall hold office for the following terms: the Chairman for three years, two members for two years, and two members for one year, which shall be specified in their appointment. Any vacancy occurring within the term of a member shall be filled for the unexpired portion of the term only. Each member of the Board shall qualify by taking the proper oath of office prior to entering upon the performance of his or her duties. No member shall succeed himself on the Board."}},{"id":"PH-H3575-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Executive Officer and Secretary of the Board.— The Commissioner of Civil Service shall be the Executive Officer of the Board and he shall conduct the examinations given by it according to the rules and regulations promulgated by the Board and approved by the President of the Philippines. The members shall elect a Secretary among them, who shall take charge of the records. All the records of the Board, including examination papers, minutes of deliberations, and records of administrative proceedings and investigations shall be kept by the Civil Service Commission."}},{"id":"PH-H3575-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Compensation of the Board Members.— The Chairman and members of the Board shall each receive as compensation the sum of ten pesos for each applicant examined."}},{"id":"PH-H3575-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Removal of Board Members.— Any member of the Board may be removed by the President7 of the Philippines upon the recommendation of the Commissioner of Civil Service8 for continued neglect of duty, incompetence, unprofessional, unethical, immoral, or dishonorable conduct, for commission or toleration of irregularities in the examination, after having been given the opportunity to defend himself in a proper administrative investigation."}},{"id":"PH-H3575-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Rules and Regulations.— Subject to the approval of the President of the Philippines9 and with the advice of the Commissioner of Civil Service the Board shall set ethical and professional standards for the practice of social work in general, and adopt such rules and regulations as may be necessary to carry out the provisions of this Act. Such standards, rules and regulations shall take effect thirty (30) days after publication in the Official Gazette."}},{"id":"PH-H3575-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Annual Report.— The Board shall submit an annual report to the President of the Philippines and to Congress after the close of the fiscal year, giving a detailed account of the proceedings of the Board during the year and embodying such recommendations as the board may desire to make.\nExamination and Registration of Social Workers"}},{"id":"PH-H3575-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Practice of Social Work and Appointment as Social Workers.— Unless exempt from registration, no person shall practice or offer to practice social work in the Philippines as defined in this Act, or be appointed as a social worker or to any position calling for social worker in any social work agency whether private or government without holding a valid certificate of registration as a social worker issued by the Board of Examinees for Social Workers: Provided, That registration shall not be required of recognized social workers or authorities on social work who are residents and/or citizens of other countries called in for consultations in any agency working with the United Nations and/ or similar international social agencies: Provided, further, That no provisions of this Act shall be construed to prejudice permanently appointed social workers who are employed in private or government social work agencies at the date of approval of this Act, who shall continue to enjoy right to promotion and salary increases, refinement benefits and other previously acquired rights: Provided, Furthermore, That those who at the time of the effectivity on this Act, possess the qualifications enumerated in Section twelve and are actually engaged in the practice of social work for a period of five years in a social work agency recognized by the Community Chest, Council of Welfare Agencies, Philippine Youth Welfare Coordinating Council, or Social Welfare Administration, shall be exempted from taking the examination as provided herein if they register as social workers within a period of one year after the approval of this Act: Provided, Still Further, That those who before the effectivity of this Act are holding regular appointment to social work positions in the government service on a provisional status for lack of the educational qualifications required under this Act for the purpose of taking the Board examination and have rendered five years or more of continuous and satisfactory service in social work shall, within a period of ten years but not later than December thirty-first, nineteen hundred seventy-eight, be allowed to retain their positions in order to qualify as registered social workers under the provisions hereof: And Provided, finally, that any person who at the time of the effectivity of this amendatory Act possesses the qualifications enumerated in Section twelve hereof except that which is specified in subparagraph (d) of Section two hereof and who has been openly performing the functions of, or practising as, a social worker as defined in this Act for at least a total of ten years prior to the effectivity of this amendatory Act, shall be allowed to continue performing such functions or such practice in the same office or agency until he or she retires without the necessity of examination for registration provided that an affidavit affirming the circumstances of such continuous practice or a certification by the Civil Service to the same effect is filed with the Board."}},{"id":"PH-H3575-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Holding of Examinations.— Except as otherwise specifically allowed under the provisions of this Act, all applicants for registration as social workers shall be required to undergo a written examination which shall be given by the Board annually in Manila at such time and place as may be fixed by it, subject to the approval of the Commissioner of Civil Service and the President of the Philippines. Written or printed notices of such examination shall be mailed to each candidate who has filed his name and address with the Secretary of the Board at least thirty (30) days prior to the date of the examination."}},{"id":"PH-H3575-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Qualification of Applicants. — In order to be admitted to take the social work examination, an applicant must, at the time of filing his or her application therefore, establish to the satisfaction of the Board that:\na. He or she is a citizen of the Philippines;\nb. He or she is at least twenty-one years of age;\nc. He or she in good health and is of good moral character;\nd. He or she has received a diploma as a holder of a bachelor’s degree or master’s degree or its equivalent in social work from an institution, college or university duly accredited and legally constituted: Provided, That the provisions of Republic Act Numbered Twenty-two hundred and sixty insofar as cultural minorities are concerned be applied; and\ne. He or she has completed a minimum period of one thousand case hours of practical training in an established social work agency under the direct supervision of a fully trained and qualified social worker."}},{"id":"PH-H3575-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Scope of Examination.— The examination for the practice of social work in the Philippines shall consist of a written test, the scope of which shall be determined and prescribed by the Board, taking into consideration the curriculum of all the social work courses offered in schools legally constituted in the Philippines: Provided, That no change or alteration in or addition to the subjects for examination shall be made within two years from the date of the promulgation of said subjects. It shall be the duty of the Board to prepare the schedule of subjects for examinations and to submit the same to the President of the Philippines for approval through the Commissioner of Civil Service, and to publish the same, as approved, at least three months before the date of the examination wherein they are to be used. Any alteration or amendment that may be made in said schedule shall likewise be approved by the President of the Philippines."}},{"id":"PH-H3575-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Ratings in the Examination.— In order to pass the examination, a candidate must obtain a general rating of at least seventy percent in the written test, with no rating below fifty percent in any subject."}},{"id":"PH-H3575-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Report of Results of Examination.— The Board of Examiners for Social Workers shall, within one hundred twenty days after the examination, report the ratings obtained by each candidate to the Commissioner of Civil Service who shall, with his recommendation, submit such ratings to the President of the Philippines."}},{"id":"PH-H3575-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Oath of Social Workers.— All successful examinees shall be required to take a professional oath before the Board or before any person authorized to administer oaths, prior to entering upon the practice of social work in the Philippines."}},{"id":"PH-H3575-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Issuance of Certificates.— Certificates of registration as a social worker shall be issued to all applicants who pass the examination, after approval of her or his ratings by the President of the Philippines, and upon payment of the required fees. Every certificate of registration shall show the full name of the registrant and serial number, and shall bear the signatures of the members of the Board, attested to by the Secretary of the Board, and duly authenticated with the official seal of the Board of Examiners for Social Workers. The issuance of a certificate of registration by the Board to the registrant shall be evidence that the person named therein is entitled to all the rights and privileges of a registered social worker until said certificate, for just cause, is revoked temporarily or canceled."}},{"id":"PH-H3575-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Registration by Reciprocity.— A certificate of registration may be issued without examination to social workers registered under the laws of any foreign state or country: Provided, That the requirements for the registration or licensing of social workers in said foreign state or country, are substantially the same as those required and contemplated by this Act: And Provided, further, That the laws of such state or country grant the same privileges to Filipino social workers on the same basis as the subject or citizens of such foreign state or country."}},{"id":"PH-H3575-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Fees for Examination and Registration.— Applicants for examination for the social work profession shall pay an examination fee of fifty pesos. Successful applicants shall pay a registration fee of thirty pesos. All such fees shall be paid to the disbursing officer of the Civil Service Commission, and such officer shall pay from the receipts thereof, all the authorized expenses of the Board, including the compensation of its Chairman and members."}},{"id":"PH-H3575-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Refusal to Issue Certificates in Certain Cases.— The Board of Examiners for Social Workers shall refuse to issue a certificate of registration to any person convicted by a court of competent jurisdiction of any criminal offense involving moral turpitude, and to any person guilty of immoral or dishonorable conduct, or to one of unsound mind or suffering from an incurable or infectious disease. The Board shall give the applicant a written statement setting forth the reason or reasons for its action, which statement shall be incorporated in the records of the Board."}},{"id":"PH-H3575-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Revocation and Suspension of Certificates.— The Boards shall also have the power to revoke or suspend the validity of a certificate of registration of a social worker for any of the causes mentioned in the preceding section, or for unprofessional conduct, malpractice, incompetency, or serious ignorance of or negligence in the practice of social work, or for making use of fraud, deceit or falsity to obtain a certificate of registration. Certificates of registration shall be revoked only after due notice and hearing."}},{"id":"PH-H3575-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Reissuance of Revoked and Replacement of Lost Certificates.— The Board may, for reasons of equity and justice, and upon proper application and explanation therefore, issue another copy of the certificate upon payment of ten pesos. A new certificate of registration to replace any certificate lost, destroyed, or mutilated may be issued subject to the rules of the Board upon payment of ten pesos (₱10.00).\nRegistration of Social Work Agencies"}},{"id":"PH-H3575-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Registration with the Social Welfare Administration.— No social work agency as defined herein shall separate and be accredited as such unless it shall first have registered with the Social Welfare Administration which shall then issue the corresponding registration certificate: Provided, That existing social work agencies at the time of approval of this Act shall have a period of one year within which to secure the corresponding certificate of registration. Before any social work agency shall be duly registered, the following requirements must have been complied with to the satisfaction of the Social Welfare Administrator:\n1. That the applicant must be engaged mainly or generally in social work activity;\n2. That the applicant has employed a sufficient number of duly qualified and registered social workers to supervise and take charge of its social work function in accordance with accepted social work standards;\n3. That the applicant must show in a duly certified financial statement that at least sixty percent of its funds are disbursed for direct social work services; and\n4. That the applicant keeps a social work record of all cases and welfare activities handled by it."}},{"id":"PH-H3575-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Financial Aid by the Government Agency or Instrumentality.— No government agency or instrumentality shall give financial or other aid to any social work agency unless the agency has been duly registered with the Social Welfare Administration in accordance with the preceding section."}},{"id":"PH-H3575-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Revocation of Certificate of Registration.— The Certificate of Registration issued to any social work agency may be revoked if, after due investigation, the Social Welfare Administration finds, that it has failed to perform the function as social work agency, or it has violated existing laws, rules and regulations.\nSundry Provisions Relative to the Practice of Social Work"}},{"id":"PH-H3575-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Penal Provisions.— The following shall be punished by a fine of not less than five hundred pesos nor more than two thousand pesos, or imprisonment for not less than one month nor more than two years, or both, in the discretion of the court;\na. Any person who shall practice or offer to practice social work in the Philippines without being registered or exempted from registration in accordance with the provisions of this Act;\nb. Any person representing or attempting to use as his own, the certificate of registration of another;\nc. Any person who shall give any false or fraudulent evidence of any kind to the Board or any member thereof in obtaining a certificate of registration as a social worker;\nd. Any person who shall impersonate any registrant of like or different name;\ne. Any person who shall attempt to use a revoked or suspended certificate of registration;\nf. Any person who shall in connection with his or her name, otherwise assume, use or advertise any title or description tending to convey the impression that he or she is a social worker without holding a valid certificate;\ng. Any person who shall violate any provision of this Act;\nh. Any person, corporation or entity operating as a social work agency without the corresponding Certificate of Registration issued by the Social Welfare Administration. (Redesignated as subparagraph (h) by §6, Republic Act No. 5157)"}},{"id":"PH-H3575-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Separability Clause.— If any provision of this Act or the application of such provision to any person or circumstances is declared invalid, the Act or the application of such provision shall not be affected by such declaration."}},{"id":"PH-H3575-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Repealing Clause.— All Acts, executive orders, rules and regulations or part thereof inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H3575-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE V"},"text":{"en":"Effectivity.— This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Regulate the Practice of Social Work and the Operation of Social Work Agencies in the Philippines and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3576"] = {"id":"PH-H3576","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4374_1965.html","fetchedAt":"2026-10-06","articleCount":34,"structureMode":"ARTICLE","title":{"zh":"规范菲律宾大地测量工程执业法案","en":"An Act to Regulate the Practice of Geodetic Engineering in the Philippines","orig":"An Act to Regulate the Practice of Geodetic Engineering in the Philippines","vi":"Đạo luật Quy định Hành nghề Kỹ thuật Trắc địa tại Philippines","th":"พระราชบัญญัติกำกับการประกอบวิชาชีพวิศวกรรมมาตรวิทยาแผ่นดินในฟิลิปปินส์","id":"Undang-Undang Pengaturan Praktik Teknik Geodesi di Filipina","ms":"Akta Pengawalseliaan Amalan Kejuruteraan Geodesi di Filipina"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4374","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 34 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4374_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3576-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short Title of Act.— This Act shall be known as the \"Geodetic Engineering Law\"."}},{"id":"PH-H3576-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Geodetic Engineer.— Any person who is technically and legally qualified to practise geodetic engineering under this Act shall be known \"geodetic engineer\", which term shall supersede \"surveyor\", in accordance with this Act."}},{"id":"PH-H3576-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Creation and Composition of the Board.— There is hereby created a Board of Examiners for Geodetic Engineers hereinafter referred to as the Board, to be composed of a Chairman and two Members, all to be appointed by the President of the Philippines with the consent of the Commission on Appointments, upon the recommendation of the Commissioner of Civil Service from among the registered practising geodetic engineers of recognized standing in the Philippines as certified to by any officially recognized association of geodetic engineers in the Philippines and possessing the qualifications prescribed in section five of this Act. The first members of the Board shall be appointed within two years from the approval of this Act; Provided, That the present Board of Examiners for Surveyors shall continue to function in lieu of the new Board until the members of the latter shall have been appointed and qualified."}},{"id":"PH-H3576-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Powers and duties of the Board.— The Board is vested with the authority, conformably with the provisions of this Act, to:\n(a) Administer the provisions of this Act;\n(b) Administer oaths in connection with the administration of this Act;\n(c) Issue, suspend or revoke certificates of registration for the practice of geodetic engineering;\n(d) Study the conditions affecting geodetic engineering courses and training and the practice of the geodetic engineering profession in the Philippines, and exercise the powers conferred upon it by this and other Acts with a view to the maintenance of efficient, ethical, technical, moral and professional standards in the practice of geodetic engineering;\n(e) Study and examine, in cooperation with the Department of Education, the facilities of schools, colleges or universities seeking permission to open courses or already offering courses in geodetic engineering to see to it that the essential requirements, including the employment of qualified faculty members, are properly complied with;\n(f) Recommend the opening of colleges or schools in geodetic engineering to the Department of Education or other entity concerned with the granting of school permits or authorization;\n(g) Investigate violations of this Act and, for this purpose, issue subpoena and subpoena duces tecum to secure attendance of witnesses and the production of documents in connection with the charges presented to and/or any investigation pending before the Board; and if any person shall refuse to obey any subpoena so issued or shall refused to testify or produce any book, document, or other pertinent evidence required thereunder, the Board may petition the proper Court of First Instance setting forth the facts and thereupon such court shall, in a proper case, issue a subpoena to said person, requiring him to appear before the Board, and thereto testify and/or produce such books, papers, documents or other pertinent evidence as may be required by such subpoena. Any person failing or refusing to obey the subpoena or order of the said court shall be held liable in the same manner as for refusal to obey any other subpoena or order of the court.\n(h) Recommend or adopt, whenever necessary, such measures as may be deemed proper for the advancement of the profession and for the proper enforcement of this Act."}},{"id":"PH-H3576-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Qualification of Board Members.— Each member of the Board must, at the time of his appointment, be:\n(a) A citizen and resident of the Philippines;\n(b) At least thirty-one years of age and of good moral character;\n(c) A registered geodetic engineer under this Act;\n(d) Actually in active practice of the Geodetic Engineering or Surveying profession for at least ten years in or outside of the government service;\n(e) Not a member of the faculty of any school, institute, college or university where a regular course in Geodetic Engineering or Surveying is taught, or if he has been such a faculty member, he has stopped teaching therein for at least three consecutive years immediately preceding his appointment; and\n(f) Not pecuniarily interested, directly or indirectly, in any school, institute, college or university where a regular course in Geodetic Engineering is taught."}},{"id":"PH-H3576-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Office.— The members of the Board shall hold office for a term of three years: Provided, That the first appointee to the Board shall hold office for the following terms: the Chairman for three years, one member for two years, and one member for one year. Any vacancy occurring within the term of a member shall be filled for the unexpired portion of the term only. Each member of the Board shall qualify by taking the proper oath prior to the assumption of office."}},{"id":"PH-H3576-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Executive Officer and Secretary of the Board.— The Commissioner of Civil Service shall be the executive officer of the Board, and shall conduct the examination given by it according to the rules and regulations promulgated by him and approved by the President of the Philippines. The Secretary of the Board of Examiners appointed in accordance with section ten of Act Numbered Four Thousand Seven, as amended by Republic Act Numbered Five Hundred and Forty-six, shall also be the Secretary of the Board. All the records of the Board, including examination papers, minutes of deliberations and records of administrative proceedings and investigations, shall be kept by the Commissioner of Civil Service."}},{"id":"PH-H3576-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Compensation of the Board.— The members of the Board shall each receive as compensation a fee of ten pesos for each applicant examined and ten pesos for each certificates of registration granted without prior examination."}},{"id":"PH-H3576-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Removal of Board Members.— The President of the Philippines may, upon recommendation of the Commissioner of Civil Service, suspend or remove any member of the Board for continued neglect of duty, incompetence, commission or tolerance of irregularities in the examination, malpractice, or unprofessional or dishonorable conduct, after having given the member concerned an opportunity to be heard and/or defend himself in a proper administrative investigation."}},{"id":"PH-H3576-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Rules and Regulations.— The Board may, subject to the approval of the Commissioner of Civil Service and of the President of the Philippines, promulgate such rules, regulations, and code of ethics as may be necessary to carry out the provision of this Act. After its approval, the rules, regulations or code of ethics shall be published in the Official Gazette. Penal provisions may be included in said rules and/or regulations, the violations of which shall be punishable by a fine of not more than two hundred pesos or an imprisonment for not more than six months, or both, in the discretion of the court."}},{"id":"PH-H3576-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Annual Report.— The Board shall submit an annual report to the President of the Philippines after the close of each fiscal year, giving a detailed account of its proceedings during the year and embodying such recommendations as it may deem proper."}},{"id":"PH-H3576-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Inhibition against practice of Geodetic Engineering.— No person shall practice or offer to practice geodetic engineering in the Philippines as defined in this Act, or use the title \"Geodetic Engineer\" or any word, letter, figure or sign whatsoever, tending to convey the impression that he is a geodetic engineer, or advertise or indicate in any manner that he is qualified to perform the work of a geodetic engineer without holding a valid certificate of registration as geodetic engineer issued by the Board in accordance with this Act."}},{"id":"PH-H3576-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Definition and scope of terms.— Any person, except geodetic engineering or surveying students and graduates who perform geodetic engineering work under the supervision of a registered geodetic engineer-instructor for the purpose of training, shall be deemed to be practicing geodetic engineering within the meaning and intent of this Act, who shall, with or without, fee, salary or other reward or compensation:\n(a) Perform professional services as geodetic engineer; or\n(b) Survey and prepare plan of land for registration in the registry of property without a registered geodetic engineer’s supervision; or\n(c) Undertake any work in which a transit, theodolite, and/or tape is used, for purposes of property registration;\n(d) Survey and prepare topographic, hydrographic and economic maps for social, economic and engineering studies or planning; or\n(e) Be engaged as instructor or professor in a technical subject in any geodetic engineering course in any school or college; Provided, That this provision shall not apply to military or nautical schools."}},{"id":"PH-H3576-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Examination required.— Except as otherwise permitted under this Act, all applicants for registration for the practice of geodetic engineering shall undergo a technical examination as provided for herein."}},{"id":"PH-H3576-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Qualifications of Applicants.— In order to be admitted to the geodetic engineering examination, an applicant must, at the time of filing his application thereof, establish to the satisfaction of the Board that:\n(a) He is at least twenty-one years of age;\n(b) He is a citizen of the Philippines, or a foreigner qualified to take the examination under section thirty-one of this Act;\n(c) He is in good health and of good moral character; and\n(d) He is a holder of the degree of Bachelor of Science in Geodetic Engineering from any school, institute, college or university recognized by the Government: Provided, That said standard course includes Mathematics, Physical Sciences; Laws on Natural Resources, Land Registration and Property, and the Land Reform Code; Plane Surveying, including isolated, mineral and cadastral land surveys; Railroad Curves, and Earthworks; Hydrographic and Topographic Surveying; Geodesy, including Geodetic Surveying, Geodetic Astronomy, Geodetic Triangulation, Geodetic Levelling, Gravity Measurements, and Least Squares; Photogrammetry and Cartography: Provided, further, That within three years after the approval of this Act, holders of a certificate of Associate in Surveying, with at least one year field experience under a licensed geodetic engineer, shall be qualified to take the geodetic engineering examination."}},{"id":"PH-H3576-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Holding of Examination.— Examination for candidates desiring to practice geodetic engineering in the Philippines shall be given by the Board twice a year in the City of Manila or at such other place as may be deemed necessary and expedient by the Board, subject to the approval of the Commissioner of Civil Service and the President of the Philippines."}},{"id":"PH-H3576-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Scope of Examination.— The Examination of the practice of geodetic engineering in the Philippines shall consist of written tests, which shall cover mathematics, theory and practical problems in surveying including problems in isolated, cadastral and mineral land surveys, cartography, laws on property and registration of title thereto, geodesy and other subjects which the Board may prescribe for the standard curriculum as approved by the Department of Education."}},{"id":"PH-H3576-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Ratings in the Examination.— In order to pass the examination, a candidate must obtain an average rating of seventy per cent, with no rating below fifty percent in any subject: Provided, That an applicant, who fails to obtain a passing average rating but who obtained at least seventy percent in each of at least one-half (½) of the total subjects given in the examination, may be permitted to take within two years from the date of his first examination, another examination on the subjects in which he obtained a grade below seventy percent. Should the examinee still fail in the set of subjects repeated in the second examination, he shall be required to take all the subjects in the next examination."}},{"id":"PH-H3576-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Report of Results of Examination.— The Board shall, within one hundred and twenty days after the examination, report the result thereof to the Commissioner of Civil Service, who shall, with his recommendation, submit such result to the President of the Philippines for approval."}},{"id":"PH-H3576-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Issuance of Certificates.— A Certificate of registration for geodetic engineer shall be issued to any applicant who passes the examination after the approval of his ratings by the President of the Philippines and upon payment of the required fees: Provided, That upon payment of the required fees, the Board may issue within a period of not exceeding two years from the approval of this Act, a certificate of registration as geodetic engineer, without the necessity of undergoing the examination herein prescribed, to any applicant who, on the date of the approval of this Act:\n(a) Is a holder of a registration certificate as private, or mineral, or cadastral land surveyor granted under Act Numbered Thirty-six Hundred and Twenty-Six as Amended; or\n(b) Is a graduate of a recognized course in surveying and has passed the Civil Service examination as assistant surveyor, or surveyor, or assistant mineral land surveyor, or mineral land surveyor, or senior cartographer, or supervising computer, and has practiced field surveying for at least twenty years in and/or out of the government service; or\n(c) Is a commissioned line officer of the Bureau of Coast and Geodetic Survey or a retired officer of the said Bureau who have had at least five (5) years of continuous active service as a commissioned line officer at the time of his retirement.\nEvery certificate of registration shall show the full name of the registrant with a serial number, and shall be signed by the members of the Board, attested to by the Secretary of the Board of Examiners and duly authenticated by the official seal of the Board.\nThe certificate of registration issued by the Board to the registrant shall be evidence that the person named therein is entitled to the rights and privileges of a registered geodetic engineer while said certificate remains in force or unrevoked."}},{"id":"PH-H3576-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Oath of Geodetic Engineers.— All registrants under this Act shall be required to take a professional oath before the Board or before any person authorized to administer oaths, before commencing the practice of his profession."}},{"id":"PH-H3576-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Seal of Geodetic Engineers.— Each registered geodetic engineer shall obtain a seal of such design as the Board shall authorize and prescribe. Plans and technical descriptions prepared by or under the direct supervision of a registered geodetic engineer shall be stamped with said seal. The geodetic engineer shall be fully responsible for all plans, technical descriptions, and other documents under his seal or authorized signature. The Board shall make all necessary rules and regulations relating to the use of authorized signatures and seals on plans, maps, technical and lot descriptions, reports and other survey returns and documents registered by geodetic engineers."}},{"id":"PH-H3576-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Fees for examination and registration.— Every applicant for the examination shall pay an examination fee of forty-five pesos, and a registration fee of ten pesos.\nEvery applicant for registration without prior examination shall pay a fee of fifty-five pesos.\nThe fee for a duplicate certificate shall be ten pesos.\nEvery practicing Geodetic Engineer shall pay an annual registration fee of two pesos which shall be paid on or before April 30 of every ensuing year.\nAll fees shall be paid to the disbursing officer of the Board of Examiners, and such officer shall pay from the receipts thereof all the authorized expenses of the Board, including the compensation of each member."}},{"id":"PH-H3576-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Refusal to issue a certificate in certain cases.— The Board shall refuse to issue a certificate of registration to any person convicted by a court of competent jurisdiction of any crime involving moral turpitude, to any person of immoral or dishonorable conduct, and to any person of unsound mind, furnishing the party concerned with a written statement containing the reason or reasons for such action, which statement shall be incorporated in the records of the Board."}},{"id":"PH-H3576-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Revocation and suspension of certificates.— The Board shall also have the power to revoke or suspend the validity of a certificate of registration as Geodetic Engineer issued to any registrant for any of the causes mentioned in the preceding section, or for unprofessional or unethical conduct, malpractice, incompetence, or where fraud, deceit or false statement was employed in obtaining said certificate of registration."}},{"id":"PH-H3576-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Appeal from Judgment.— The decision of the Board of Examiners for Geodetic Engineers shall become final after thirty days from the date of its promulgation, unless within said period any interested party has perfected an appeal to the Office of the Commissioner of Civil Service by filing a notice of appeal. The decision of the Commissioner of Civil Service is appealable, within thirty days from receipt of a copy of such decision, to the Office of the President of the Philippines whose decision shall be final."}},{"id":"PH-H3576-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Reinstatement and replacement of Certificates.— The Board may, upon application and for reasons of equity and justice, reinstate the validity of a suspended certificate, or issue another certificate in lieu of one previously revoked, upon payment of the required fees, at least two years after such suspension or revocation.\nA new certificate of registration to replace any certificate lost, destroyed or mutilated, may be issued subject to the rules of the Board and upon payment of the required fee."}},{"id":"PH-H3576-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Corporation cannot register.— The practice of geodetic engineering is a professional service, admission to which shall be determined upon the basis of individual and personal qualifications. No firm, company, partnership, association or corporation may be registered or licensed as such for the practice of geodetic engineering: Provided, That this section shall not be construed as preventing any combination of geodetic engineers from using the term \"Geodetic Engineer\"; Provided, further, That majority of the members of the partnership, firm or association are properly registered and licensed geodetic engineers.\nMembers of the partnership, firm or association are responsible for their own individual acts."}},{"id":"PH-H3576-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Penal Provisions.— The following shall be punished by a fine of not less than two hundred pesos nor more than five thousand pesos, or by imprisonment for not less than six months nor more than six years, or both, in the discretion of the Court:\n(a) Any person not exempt from registration who shall practice geodetic engineering in the Philippines within the meaning of this Act, without holding a valid certificate of registration issued in accordance with this Act;\n(b) Any person who shall give any false or fraudulent statement to the Board in order to obtain a certificate of registration as geodetic engineer;\n(c) Any person who shall present or use as his own a certificate of registration issued to another under this Act:\n(d) Any person who shall use a revoked or suspended certificate of registration as geodetic engineer;\n(e) Any person who shall assume, use or advertise as geodetic engineer, or append to his name, letters or words tending to convey the impression that he is a registered geodetic engineer when in fact he is not duly registered with the Board as such;\n(f) Any geodetic engineer, or any person on his behalf, who shall stamp or seal any document with his seal after his certificate of registration has expired or has been suspended or revoked;\n(g) Any geodetic engineer who shall sign his name, affix his seal, or use any other method of signature on plans, technical descriptions, or other documents prepared by or under another geodetic engineer’s supervision, unless the same is prepared in such a manner as to clearly indicate the part or parts of such work actually performed by the former;\n(h) Any person, except the geodetic engineer in charge, who shall sign for any branch of the surveying work, or any function or surveying practice not actually performed by him; and\n(i) Any person who shall violate any provision of this Act."}},{"id":"PH-H3576-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Enforcement of this Act by officers of the law.— It shall be the duty of all duly constituted officers of the law, of the National Government or of any provincial, city or municipal government, to enforce the provisions of this Act and to prosecute any person violating the same. The Secretary of Justice shall act as legal adviser to the Board and shall render such legal assistance as may be necessary in carrying out the provisions of this Act."}},{"id":"PH-H3576-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Foreign Reciprocity.— No foreigner shall be admitted to examination or registration as geodetic engineer under this Act unless he proves in the manner provided for by the Rules of Court that, by specific provisions of law, the country of which he is a citizen, subject or national, admit Filipino citizens to the practice of geodetic engineering after an examination on terms of strict and absolute equality with the citizens, subjects or nationals of said country, including the unconditional recognition of prerequisite degrees issued by institutions of learning duly recognized by the Government of the Philippines."}},{"id":"PH-H3576-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Repealing Clause.— All laws, executive orders, rules, regulations or parts thereof in conflict with the provision of this Act, are hereby repealed or amended accordingly."}},{"id":"PH-H3576-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"Separability of Provisions.— If any provision of this Act or any portion thereof is declared unconstitutional by any competent court, the other provisions thereof shall not be affected thereby."}},{"id":"PH-H3576-A34","no":34,"noLabel":{"en":"Section 34."},"text":{"en":"Effectivity.— This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Regulate the Practice of Geodetic Engineering in the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3577"] = {"id":"PH-H3577","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4375_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第542号联邦法（即设立名称为菲律宾女童子军的公司并界定其权力与宗旨的法案）的法案","en":"An Act Amending Commonwealth Act Numbered Five Hundred Forty-Two Entitled \"An Act to Create a Corporation to be Known as the Girl Scouts of the Philippines, and to Define its Powers and Purposes\"","orig":"An Act Amending Commonwealth Act Numbered Five Hundred Forty-Two Entitled \"An Act to Create a Corporation to be Known as the Girl Scouts of the Philippines, and to Define its Powers and Purposes\"","vi":"Đạo luật sửa đổi Đạo luật Thịnh vượng chung số 542","th":"พระราชบัญญัติแก้ไขเพิ่มเติมพระราชบัญญัติเครือรัฐที่ 542","id":"Undang-Undang mengubah Undang-Undang Persemakmuran No. 542","ms":"Akta meminda Akta Komanwel No. 542"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4375","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4375_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3577-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provisions of Commonwealth Act Numbered Five hundred forty-two are hereby amended to read as follows:\n\"Sec. 1. Conception R. Gonzales, Trinidad F. Legarda, Emilia Q. Lim, Concepcion M. Gil, Marina Y. Vergas, Pilar Hidalgo Lim, Josefa Llanes Escoda, Helena Z. Benitez, Maria Aurora Quezon, Lulu Reyes, Lily de las Alas, Leni Alano, Erlinda Kalaw, Betty Magalona, Lourdes Ledesma, Minerva G. Laudico , all of Manila, Philippines, their associates and successors, are created a body corporate, by the name, style, and title of \"Girl Scouts of the Philippines\" (hereinafter called the corporation.) The principal office of the corporation shall be in the City of Manila, Philippines, and for administrative purposes, it shall be under the President of the Philippines.\"\n\"Sec. 2. The said corporation shall have perpetual succession, with power to sue and be sued; to hold such real and personal estate as shall be necessary for corporate purposes, and to receive real and personal property by gift, devise, or bequest; to adopt a seal; to have offices and conduct its business and affairs in the City of Manila and in the several provinces, cities, municipalities and barrios of the Philippines; to make an adopt by-laws, and generally to do all acts and exercise all powers of a corporation under Act 1459 as amended as may be necessary to carry into effect the provisions of this Act and promote the purposes of said corporation.\"\n\"Sec. 3. The purposes of this organization are to help girls from seven to eighteen years of age to realize the ideals of womanhood, as a preparation for their responsibilities in the home and service to the community and in the realization of this purpose the corporation shall be directing and coordinating head of the Girl Scout Movement in the Philippines, and shall fix and maintain standards for the movement which will inspire the rising generation with the highest ideals of citizenship, character, conduct, and attainment.\"\n\"Sec. 4. The Girl Scouts of the Philippines is nonsecretarian and nonpolitical but its units shall willingly cooperate with educational and other groups whose ideals and procedure are in accord with those conferred or authorized by this Act.\"\n\"Sec. 5. The governing body of the corporation shall be vested in a Central Board composed of twenty-four (24) members elected by the National Council to serve for a term of three years or until their successors shall have been elected and qualified. The National Council shall be composed of the members of the Central Board, Presidents of the Local Councils and the duly elected delegates from each Local Council. Each local Council shall be entitled to one delegate for every five hundred members. The number, qualifications, and terms of office of members of the executive board shall be prescribed by the by-laws. The persons mentioned in section one of this Act shall constitute the first central board and shall serve until their successors are elected and have qualified. Central board shall have the power to make and to amend the by-laws. Unless otherwise prescribed by this Act, the by-laws shall provide for the time, place and manner of calling and conducting regular or special meetings of the central board and the time and manner of calling and conducting regular or special meetings of the National Council; the number of members necessary to constitute a quorum for the transaction of business at meetings of the National Council and the central board; the qualifications and conditions upon which person may be admitted to the corporation and the conditions upon which members shall be entitled to vote; the qualifications and duties of the members of the central board and officers; the time for holding the election of the members of the central board and the mode and manner of giving notice thereof; the manner of election and the term of office of all officers elected by the central board; and such other matters not otherwise provided for by this Act as may be necessary for the proper or convenient transaction of the business of corporation. The central board shall, by resolution passed by a majority of the whole board, designate the officers of the corporation; namely: The National President, the First Vice-President, the Second Vice-President, the Secretary, the Treasurer and the Chairman of standing and special committees it may create to constitute an executive a governing committee, of which a majority shall constitute a quorum, which committee, to the extent provided in said resolution shall have and exercise the powers of the central board in the management of the affairs of the corporation, subject to its ratification, and may have the power to authorize the seal of the corporation to be affixed to all papers which may require it. The central board, by the affirmative vote of a majority of the whole board, may appoint any other standing and special Committees and such standing and special committees shall have and may exercise such powers as shall be conferred or authorized by the board. The central board shall elect a National President who shall be the executive officer of the corporation, a first Vice-President, a second Vice-President, a Secretary, a Treasurer, and an Assistant Treasurer.\"\n\"Sec. 6. A triennial meeting of the National Council, shall be held once in every three years after the year of incorporation, at such time and place as shall be prescribed in the by-laws, for the purpose of making reports and transacting such other business as may come before the meeting. Special meetings of the corporation may be called upon such notice as may be prescribed in the by-laws. The number of members which shall constitute a quorum at any annual or special meetings shall be prescribed in the by-laws. The central board shall have the power to hold their meetings and keep the seals, books, documents, and papers of the corporation within or without the City of Manila.\"\n\"Sec. 7. The corporation created by this Act shall adopt distinctive badges, uniforms, insignias, and other equipments and shall be made available to and used only by registered Girl Scouts or officials who have satisfactorily complied with the international requirements prescribed by the World Bureau of this Movement and which the Girl Scouts of the Philippines shall use in carrying out its program in accordance with the purposes of this Act. The corporation shall cause the registration of said badges, uniforms, insignias, and other equipments in accordance with the provisions of Republic Act Numbered One hundred sixty-six, and the patent office is hereby directed to cause said registration free of charge.\n\"Sec. 8. Any donation or contribution which from time to time may be made to the Girl Scouts of the Philippines by the Government or any of its subdivision, branches, offices, agencies or instrumentalities shall be administered by the central board in pursuance of this Act.\n\"All donations made to the Girl Scouts of the Philippines shall be free from the payment of taxes on donations, and the corporation shall be exempt from the payment of all taxes, duties, imposts and other charges.\"\n\"Sec. 9. On or before the first day of May of each year, the said corporation shall make and transmit to the President of the Philippines a report of its proceedings for the year ending December, thirty first preceding, including a full, complete, and itemized report of receipts and expenditures of whatever kind.\"\n\"Sec. 10. From and after the passage of this Act, it shall be unlawful for any person within the jurisdiction of the Philippines to falsely and fraudulently call herself as or represent herself to be a member of or an agent for, the Girl Scouts of the Philippines; and any person who violates any of the provisions of this Act shall be punished by imprisonment of not to exceed six months or a fine not exceeding five hundred pesos, or both, in the discretion of the court.\"\n\"Sec. 11. The provisions of Act 1459 as amended shall be applicable to this corporation for all matters not provided herein.\""}},{"id":"PH-H3577-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Commonwealth Act Numbered Five Hundred Forty-Two Entitled \"An Act to Create a Corporation to be Known as the Girl Scouts of the Philippines, and to Define its Powers and Purposes\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3578"] = {"id":"PH-H3578","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4376_1965.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"1940年菲律宾移民法","en":"The Philippine Immigration Act of 1940","orig":"An Act Amending Section Thirteen of Commonwealth Act Numbered Six Hundred Thirteen, Otherwise Known as \"The Philippine Immigration Act of 1940\" so as to Include as Non-Quota Immigrants Who May be Admitted into the Philippines, Natural Born Citizens Who Have Been Naturalized in a Foreign Country and Desire to Return for Permanent Residence","vi":"Đạo luật Nhập cư Philippines năm 1940","th":"พระราชบัญญัติคนเข้าเมืองฟิลิปปินส์ ค.ศ. 1940","id":"Undang-Undang Keimigrasian Filipina Tahun 1940","ms":"Akta Imigresen Filipina 1940"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4376","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4376_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3578-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section thirteen of Commonwealth Act Numbered Six hundred thirteen is hereby amended by adding a new paragraph to be known as Paragraph (g) to read as follows:\n\"(g) A natural born citizen of the Philippines, who has been naturalized in a foreign country, and is returning to the Philippines for permanent residence, including his spouse and minor unmarried children, shall be considered a non-quota, immigrant for purpose of entering the Philippine.\""}},{"id":"PH-H3578-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All Acts or parts of Acts inconsistent herewith are hereby repealed or modified accordingly."}},{"id":"PH-H3578-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"The Philippine Immigration Act of 1940","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3579"] = {"id":"PH-H3579","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4377_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"授权菲律宾慈善彩票办公室举办特别彩票以惠及菲律宾女童子军的法案","en":"An Act Authorizing the Philippine Charity Sweepstakes Office to Hold a Special Lottery for the Benefit of the Girl Scouts of the Philippines","orig":"An Act Authorizing the Philippine Charity Sweepstakes Office to Hold a Special Lottery for the Benefit of the Girl Scouts of the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4377","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4377_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3579-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Philippine Charity Sweepstakes Office is hereby authorized to hold one special lottery, the whole proceed of which, after deducting the prizes and expenses as provided for in Republic Act Numbered Eleven hundred and sixty-nine, as amended, shall be turned over to the Girl Scouts of the Philippines in support and maintenance of its \"Silver Jubilee Year\" on May 26, 1965 to May 26, 1966, and, its participation as hostess to the forthcoming Girl Scouts World Conference in 1966 to be held in Manila: Provided, That all disbursements from this fund shall be subject to the established rules and regulations governing disbursement of public funds."}},{"id":"PH-H3579-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Philippine Charity Sweepstakes Office to Hold a Special Lottery for the Benefit of the Girl Scouts of the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3580"] = {"id":"PH-H3580","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4378_1965.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"修订第 3779 号共和国法（即储蓄与贷款协会法）若干条款的法案","en":"An Act to Amend Certain Sections of Republic Act Numbered Three Thousand Seven Hundred and Seventy-Nine, Otherwise Known as the Savings and Loan Association Act","orig":"An Act to Amend Certain Sections of Republic Act Numbered Three Thousand Seven Hundred and Seventy-Nine, Otherwise Known as the Savings and Loan Association Act","vi":"Đạo luật sửa đổi một số điều của Đạo luật Cộng hòa số 3779 (Đạo luật Hiệp hội Tiết kiệm và Cho vay)","th":"พระราชบัญญัติแก้ไขเพิ่มเติมบางมาตราแห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 3779 (พระราชบัญญัติสมาคมออมทรัพย์และเงินกู้)","id":"Undang-Undang mengubah beberapa pasal Undang-Undang Republik No. 3779 (Undang-Undang Perhimpunan Tabungan dan Pinjaman)","ms":"Akta meminda beberapa seksyen Akta Republik No. 3779 (Akta Persatuan Simpanan dan Pinjaman)"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4378","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4378_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3580-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Paragraph (b) of Section four of Republic Act Numbered Three thousand seven hundred and seventy-nine is hereby amended to read as follows:\n\"(b) The Monetary Board shall fix the minimum paid-up capital of a savings and loan association organized as a stock corporation in such amount as said Board may consider necessary for the safe and sound operation of such association: Provided, However, That in no case shall such paid-up capital be less than one hundred thousand pesos: And Provided, further, That at least sixty per centum of the capital stock of a savings and loan association which may be established after the approval of this Act shall be owned by citizens of the Philippines. Such association is authorized to receive deposits from, and extend loans to, the general public.\""}},{"id":"PH-H3580-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Sections four-a and four-b, which read as follows, are hereby added after Section four of said Act:\n\"Sec. 4-a. Prohibition against inquiry into, or disclosure of deposits.— All deposits of whatever nature with savings and loan associations in the Philippines are hereby considered as of an absolutely confidential nature and may not be examined, inquired or looked into by any person, government official, bureau or office, except when the examination is conducted by the Monetary Board or the official of the Central Bank in charge of savings and loan associations or his deputies pursuant to the provisions of this Act, or upon written permission of the depositor, or in cases of impeachment, or upon order of a competent court in cases of bribery or dereliction of duty of public officials, or in cases where the money deposited or invested is the subject matter of the litigation.\n\"It shall be unlawful for any official or employee of a savings and loan association to disclose to any person any information concerning said deposits, except in the cases mentioned in the preceding paragraph of this section.\"\n\"Sec. 4-b. Deposit insurance.— Deposits in savings and loan associations shall be eligible for insurance coverage under Republic Act Numbered Three thousand five hundred and ninety-one, otherwise known as an act establishing the Philippine Deposit Insurance Corporation.\""}},{"id":"PH-H3580-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Paragraphs (a) and (f) of Section five of the same Act are hereby amended to read as follows:\n\"(a) To grant loans of not exceeding the amount deposited by the borrower plus his four month’s salary or regular income in the case of a permanent employee or wage earner, or seventy percent of the fair market value of any property acceptable as collateral on first mortgage that he may put up by way of security: Provided, That no loan shall have a maturity date of more than one year, except loans on the security of unencumbered real estate, for the purpose of building, acquiring, or repairing residential houses and/or the purchase of land on which to build such houses, which may be granted with maturity dates not exceeding ten years: And Provided, further, That in the case of a borrower who is a permanent employee or wage earner, the treasurer, cashier or paymaster of the office employing him is authorized, the provisions of any existing law, rule and regulation to the contrary notwithstanding, to make deductions from his salary, wage or income pursuant to the terms of his loan, to remit deductions to the savings and loan association, and to collect such reasonable fee for his services as may be authorized by rules promulgated by the Monetary Board. For the purpose of this Act, deposits made by an association to a bank shall not constitute a loan;\"\n\"(f) To borrow money or incur such obligations not exceeding twenty per centum of the total assets of the association, from any public lending institutions, such as the Development Bank of the Philippines, the Philippine National Bank, the Government Service Insurance System, the Social Security System, and from such private lending institutions other than another savings and loan association as may be approved by the Monetary Board; the Monetary Board may, in meritorious cases, raise the ceiling on the borrowing capacity of a savings and loan association to an amount not exceeding thirty per centum of its total assets.\n\"A savings and loan association may, subject to such rules as the Monetary Board may promulgated, also borrow from, or rediscount notes, bills of exchange and other commercial papers with the Central Bank. The rate of interest on such obligations or borrowings to be changed such associations shall not be more than that charged rural banks.\""}},{"id":"PH-H3580-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section seven of said Act is hereby amended to read as follows:\n\"Sec. 7. Prerequisite approval of articles of incorporation and by-laws.— The articles of incorporation and by-laws of a proposed savings and loan association shall not be filed in the Office of the Securities and Exchange Commissioner unless there is attached thereto a certificate of the Monetary Board approving such articles and by-laws: Provided, However, That this requirement shall not apply to savings and loan associations duly incorporated or registered prior to the approval of this Act and which are actually existing and operating as such: Provided, further, That such existing savings and loan associations shall file an information sheet within sixty days after the approval of this Act with the Central Bank in a form prescribed by the Monetary Board.\n\"No person, association, partnership or corporation shall do business, of hold itself out as doing business, as a savings and loan association, or shall use the term ‘savings and loan association’ or any other title or name tending to give the public the impression that it is engaged in the operations and activities of a savings and loan association unless so authorized under this Act.\""}},{"id":"PH-H3580-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The last paragraph of Section eight of said Act is hereby amended to read as follows:\n\"A filing fee of two hundred pesos shall be paid to the official of the Central Bank in charge of savings and loan associations with each application for approval of proposed article of incorporation and by-laws, but in the case of non-stock savings and loan associations, the filing fee shall be five pesos.\""}},{"id":"PH-H3580-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section nine of said Act is hereby amended to read as follows:\n\"Sec. 9. Hearing an application.— Upon receipt of an application to form a proposed stock savings and loan association, the Monetary Board shall give written notice to each existing stock association in the area or areas to be served by the proposed association, that an application has been made. In case the application is for the establishment of a nonstock association, such notice shall be given to each existing nonstock association in, or to employees of, the office, firm or entity in which the non-stock association is proposed to be established. The Notice shall state the name of the proposed association, and the time and place that a hearing will be held. The hearing shall be conducted not less than ten days after the mailing of the notice. Any person may appear at such hearing in person or by agent or attorney, and orally or in writing show cause why such application should not be approved. The official of the Central Bank in-charge of savings and loan associations or his duly authorized representative is hereby authorized to administer oaths to any applicant and witnesses in such hearing.\n\"If after public hearing, the Monetary Board believes that the requirements of this Act have been complied with and that no valid reasons exist for the disapproval of the application, it shall favorably endorse such application to the Securities and Exchange Commission who shall issue articles of incorporation to the association.\""}},{"id":"PH-H3580-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section eleven of said Act is hereby amended to read as follows:\n\"Sec. 11. Prior Licensing.— All associations, prior to transacting any business, shall procure a license to transact business from the Monetary Board. After due notice and hearing, the Monetary Board may revoke, or suspend for such period as if determines, the license of any association, the solvency of which is imperiled by losses or irregularities or of any association which wilfully violates any provisions of this Act or any regulation issued thereunder.\""}},{"id":"PH-H3580-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section fourteen of said Act is hereby amended to read as follows:\n\"Sec. 14. Qualifications of directors.— No person shall be eligible as director of an association unless he is a member, in case of nonstock associations, or an owner in his own right of stocks in the association with an aggregate par value of at least five thousand pesos, in case of stock associations: Provided, That at least two-thirds of the members of the board of directors of any stock savings and loan association which may be established after the approval of this Act shall be citizens of the Philippines.\""}},{"id":"PH-H3580-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Paragraph (c) of Section sixteen of said Act is hereby amended to read as follows:\n\"(c) Receipt or payment of bonuses of directors, officers or employees if such bonuses are based on the profits and not on the volume or number of loans made or on the interest of fees collected thereon.\""}},{"id":"PH-H3580-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Paragraph (b) of Section eighteen of said Act is hereby amended to read as follows:\n\"(b) No association shall directly or indirectly make any loans to any director or officer or employee of such association, either for himself or as agent or as partner of another, except in the case of a nonstock savings and loan association which may grant loans to any director, officer, or employee thereof: Provided, That the written approval of the majority of the directors of the nonstock association, excluding the director concerned shall be secured: And Provided, further, That the aggregate loans, direct or indirect, granted at any one time to such directors and officers shall not exceed twenty per centum of the total paid-up capital of the association. Any such approval shall be entered upon the records of the association and a copy of the written approval shall be transmitted immediately to the official of the Central Bank in charge of savings and loan associations.\""}},{"id":"PH-H3580-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section twenty-two of said Act is hereby amended to read as follows:\n\"Sec. 22. Reserves.— Every nonstock savings and loan association shall create a withdrawable share reserve which shall consists of three per centum of the aggregate capital contributions of the members.\n\"Five per centum of the net earnings of a stock savings and loan association shall be credited to a reserve account until the reserve equals five per centum of the total assets of the association and shall be available for meeting losses incurred by the association.\""}},{"id":"PH-H3580-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section twenty-three of said Act is hereby amended to read as follows:\n\"Sec. 23. When dividends not distributable.— The withdrawable share reserve shall be set up from the profits of the nonstock association, and no association shall pay any dividends or distribute any profits to its members if its withdrawable share reserve is less than, or if by such payment or distribution would be reduced below, the amount specified in Section twenty-two hereof.\""}},{"id":"PH-H3580-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Paragraph (c) of Section twenty-six of said Act is hereby amended to read as follows:\n\"(c) The Monetary Board finds that the association’s assets, after deducting all liabilities, do not equal or exceed the sum of the par value of its outstanding shares of stock or the amount contributed to the capital of the association;\""}},{"id":"PH-H3580-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Paragraphs (b) and (c) of Section twenty-eight of said Act are hereby amended to read as follows:\n\"(b) To supervise the operations and activities of savings and loan associations, which shall consist, among others (1) in placing limits to the maximum credit allowed any individual borrowers; (2) in determining the loan period and loan procedures; (3) in prescribing a higher rate of interest which associations may pay on deposits received by them, which shall not be more than one per centum over and above the rate which banks and banking institutions are authorized or shall be authorized to pay; (4) in imposing a uniform accounting system and manner of keeping the accounts and records of savings and loan associations; (5) in instituting periodic surveys of loan and lending procedures, audits, test check of each and other transactions of savings and loan associations; and (6) whenever necessary, in conducting training courses for personnel of savings and loan associations;\"\n\"(c) To conduct at least once every year, and whenever necessary, any inspection, examination or investigation of the books and records, business affairs, administration, and financial condition of any savings and loan association with or without prior notice but always with fairness and reasonable opportunity for the association or any of its officials to give their side of the case. Whenever an inspection, examination or investigation is conducted under this grant of power, the person authorized to do so may seize books and records and keep them under his custody after giving proper receipts therefor; may make any marking or notation or any paper, record, document or book to show that it has been examined and verified; and may padlock or seal shelves, vaults, safes, receptacles or similar containers and prohibit the opening thereof without first securing authority therefor, for as long as may be necessary in connection with the investigation or examination being conducted. The official of the Central Bank in charge of savings and loan associations and his deputies are hereby authorized to administer oaths to any director, officer or employee of any association under the supervision of the Monetary Board.\n\"Stock savings and loan associations which are subject to examination by the Monetary Board, shall, after having been in operation for five years, reimburse the Central Bank for the cost of maintaining the department of savings and loan associations, and, for this purpose, shall pay to the Central Bank, within the first thirty days of each year after the fifth year of their existence, an annual fee in an amount to be determined by the Monetary Board in the manner provided in the next paragraph of this subsection.\n\"The fee to be paid by each stock savings and loan association shall be an amount equal to a prescribed percentage of its average total assets during the preceding years, as shown on its end-of-month balance sheets, after deducting its cash on hand and amounts due from banks, including the Central Bank: Provided, However, That said percentage may not exceed one twentieth of one per cent. If the total of the maximum fees authorized under this paragraph should be insufficient to defray the entire costs of the department, the difference shall be borne by the Central Bank;\""}},{"id":"PH-H3580-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Paragraphs (a), (b) and (d) of Section twenty-nine of said Act are hereby amended to read as follows:\n\"(a) Any owner, agent, manager, or other officer in charge of any savings and loan association who, being thereunto required in writing by the Monetary Board or by the official of the Central Bank in charge of savings and loan associations to comply with the requirements of this Act, shall wilfully refuse any lawful examination into the affairs of such institution shall be punished by a fine of not more than ten thousand pesos or by imprisonment of not more than two years, or both, in the discretion of the court.\n\"(b) The willful making of a false statement to the Monetary Board or to the official of the Central Bank in charge of savings and loan associations or to his examiners shall be punished by a fine not to exceed fifteen thousand pesos or by imprisonment of not more than three years, or both, in the discretion of the court.\n\"(d) Whenever a savings and loan association persists in violating its charter or by-laws or any law, or orders, instructions, rules or regulations legally issued by the Monetary Board or whenever a savings and loan association persists in carrying on its business in an unlawful or unsafe manner, the Board shall, by the Solicitor General, and without prejudice to the penalties provided in the preceding paragraph of this section, file a petition in the Court of First Instance praying the assistance of the court to compel the savings and loan association to discontinue the violations or practices objected to in the petition of the Board. The Monetary Board may, with the approval of the Court, take such action as the court may deem necessary to compel the savings and loan association complained against to discontinue the violations or practices set forth in the Board’s petition, and, if necessary, the Board may, under order of the court, direct the official of the Central Bank in charge of savings and loan associations to liquidate the business of the institution.\""}},{"id":"PH-H3580-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Sections of Republic Act Numbered Three Thousand Seven Hundred and Seventy-Nine, Otherwise Known as the Savings and Loan Association Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3581"] = {"id":"PH-H3581","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4379_1965.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在菲律宾大学设立大众传播研究所，为其建筑、设施与运营费用提供资金并为其他目的法案","en":"An Act Establishing an Institute of Mass Communications in the University of the Philippines, Providing Funds for a Building, Facilities and Operating Expenses Thereof, and for Other Purposes","orig":"An Act Establishing an Institute of Mass Communications in the University of the Philippines, Providing Funds for a Building, Facilities and Operating Expenses Thereof, and for Other Purposes","vi":"Đạo luật thành lập Đại học Institute of Mass Communications in Philippines, và cho các mục đích khác","th":"พระราชบัญญัติจัดตั้งมหาวิทยาลัย Institute of Mass Communications in Philippines และเพื่อวัตถุประสงค์อื่น","id":"Undang-Undang membentuk Universitas Institute of Mass Communications in Philippines, dan untuk tujuan lain","ms":"Akta menubuhkan Universiti Institute of Mass Communications in Philippines, dan untuk tujuan lain"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 4379","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4379_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3581-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established an Institute of Mass Communications in the University of the Philippines which shall provide professional and advanced training, research and extension services in the various media of communications, including the press, radio and television, and to inculcate and foster awareness of the ethical and social significance of, as well as responsibility in the use of these media."}},{"id":"PH-H3581-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Any provision of law to the contrary notwithstanding, appointments to the teaching and research positions in the Institute may be on a part-time basis and personnel already in the government service appointed to its training or research staff shall receive honoraria at rates to be fixed by the Board of Regents of the University."}},{"id":"PH-H3581-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is hereby authorized to the appropriated out of the funds in the National Treasury not otherwise appropriated, the sum of four hundred fifty thousand pesos for a building necessary for the training, research and public service activities of the Institute: Provided, That the amount of two hundred thousand pesos shall be appropriated annually in the General Appropriations Act beginning with the fiscal year nineteen hundred sixty-six-nineteen hundred sixty-seven for the support of the Institute."}},{"id":"PH-H3581-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing an Institute of Mass Communications in the University of the Philippines, Providing Funds for a Building, Facilities and Operating Expenses Thereof, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3582"] = {"id":"PH-H3582","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4380_1965.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"进一步修订经修正的第2260号共和国法第9条的法案","en":"An Act to Further Amend Section Nine of Republic Act Numbered Twenty-Two Hundred Sixty, as Amended","orig":"An Act to Further Amend Section Nine of Republic Act Numbered Twenty-Two Hundred Sixty, as Amended","vi":"Đạo luật sửa đổi thêm Điều 9 của Đạo luật Cộng hòa số 2260 như đã được sửa đổi","th":"พระราชบัญญัติแก้ไขเพิ่มเติมอีกมาตรา 9 แห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 2260 ซึ่งแก้ไขเพิ่มเติมแล้ว","id":"Undang-Undang mengubah lagi Pasal 9 Undang-Undang Republik No. 2260 sebagaimana diubah","ms":"Akta meminda lagi Seksyen 9 Akta Republik No. 2260 sebagaimana dipinda"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4380","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4380_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3582-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section nine of Republic Act Numbered Twenty-two hundred and sixty as amended by Republic Act Numbered Thirty-six hundred and seventy-five is hereby further amended to read as follows:\n\"Sec. 9. Wage and Position Classification Office. The Wage and Position Classification Office shall be responsible for the classification of positions in the civil service and shall standardize the salaries of the group or groups of positions to be classified: Provided , That the range of minimum and maximum salaries allowable for civil service eligibilities shall be:\nEligibilities\nMinimum\nMaximum\nFirst Grade\nP3,000\nNo limit Second Grade 2,400 P7,200 Third Grade 2,160 4,800 Senior Stenographer 3,000 No limit Junior Stenographer 2,160 7,200 Senior Typist 3,000 6,720 Junior Typist 2,160 5,040\""}},{"id":"PH-H3582-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All Acts, executive orders, administrative orders, rules and regulations, or parts thereof inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H3582-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965"}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Amend Section Nine of Republic Act Numbered Twenty-Two Hundred Sixty, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3583"] = {"id":"PH-H3583","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4381_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第133号共和国法（即《授权在特定条件下向任何个人、公司或协会抵押私人不动产》）第1条的法案","en":"An Act to Amend Section One of Republic Act Numbered One Hundred and Thirty-Three, Entitled \"An Act to Authorize the Mortgage of Private Real Property in Favor of Any Individual, Corporation, or Association Subject to Certain Conditions\"","orig":"An Act to Amend Section One of Republic Act Numbered One Hundred and Thirty-Three, Entitled \"An Act to Authorize the Mortgage of Private Real Property in Favor of Any Individual, Corporation, or Association Subject to Certain Conditions\"","vi":"Đạo luật sửa đổi Điều 1 của Đạo luật Cộng hòa số 133","th":"พระราชบัญญัติแก้ไขเพิ่มเติมมาตรา 1 แห่งพระราชบัญญัติแห่งสาธารณรัฐที่ 133","id":"Undang-Undang mengubah Pasal 1 Undang-Undang Republik No. 133","ms":"Akta meminda Seksyen 1 Akta Republik No. 133"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4381","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4381_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3583-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered One hundred and thirty-three is hereby amended to read as follows:\n\"Sec. 1. Any provision of law to the contrary notwithstanding, private real property may be mortgaged in favor of any individual, corporation, or association, but the mortgage or his successor in interest, if disqualified to acquire or hold lands of the public domain in the Philippines, shall not take possession or enjoy the fruits of the mortgaged property during the existence of the mortgage and shall not bid or take part in any sale of such real property in case of foreclosure.\""}},{"id":"PH-H3583-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Section One of Republic Act Numbered One Hundred and Thirty-Three, Entitled \"An Act to Authorize the Mortgage of Private Real Property in Favor of Any Individual, Corporation, or Association Subject to Certain Conditions\"","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H3584"] = {"id":"PH-H3584","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4382_1965.html","fetchedAt":"2026-10-06","articleCount":92,"structureMode":"ARTICLE","title":{"zh":"设立Bago市","en":"An Act Creating the City of Bago","orig":"An Act Creating the City of Bago","vi":"Đạo luật thành lập Thành phố Bago","th":"พระราชบัญญัติจัดตั้งเมือง Bago","id":"Undang-Undang membentuk Kota Bago","ms":"Akta mewujudkan Bandaraya Bago"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 4382","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 92 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4382_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 93 条，缺 59）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3584-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act shall be known as the Charter of Bago City.\nGeneral Provisions"}},{"id":"PH-H3584-A2","no":2,"noLabel":{"en":"Section 2."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Territory of the City of Bago.— The City of Bago which is hereby created shall comprise the present territorial jurisdiction of the Municipality of Bago in the Province of Negros Occidental."}},{"id":"PH-H3584-A3","no":3,"noLabel":{"en":"Section 3."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Corporate character of the city.— The City of Bago shall constitute a political body corporate and shall be endowed with the attribute of perpetual succession and possessed of the powers which pertain to a municipal corporation, to be exercised in conformity with the provisions of this Charter."}},{"id":"PH-H3584-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Seal and general powers of the city.— The city shall have a common seal, and may alter the same at pleasure. It may take, purchase, receive, hold, lease, convey and dispose of real and personal property for the general interest of the city, condemn private property for public use, contract and be contracted with, sue and be sued, prosecute and defend to final judgment and execution cases wherein said city is a party, and exercise all the powers hereinafter conferred."}},{"id":"PH-H3584-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"ARTICLE I"},"text":{"en":"The city not liable for damages.— The city shall not be liable or held liable for damages or injuries to persons or property arising from the failure of the municipal board, the mayor, or any other officer or employee, to enforce the provisions of this Charter, or any other law or ordinance or from negligence of said municipal board, mayor or other city officers or employees while enforcing or attempting to enforce the provisions thereof: Provided, However, That nothing herein contained shall prevent any aggrieved party from filing a personal action in the proper court against any official or employee of the city government for any act or omission in the performance of his duties."}},{"id":"PH-H3584-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"ARTICLE I"},"text":{"en":"Jurisdiction of the City.— The jurisdiction of the City of Bago for police purposes shall be co-extensive with its territorial jurisdiction, and for the purposes of protecting and insuring the purity of the water supply of the city, such police jurisdiction shall also extend over all territory within the drainage area of such water supply, or within one hundred meters of any reservoir, conduit, canal, aqueduct or pumping station used in connection with the city water service. The city court shall have concurrent jurisdiction with the justice of the peace court of the respective municipalities, to try crimes and misdemeanors committed within said drainage areas, or within said spaces of one hundred meters. The court first taking jurisdiction of such an offense shall thereafter retain exclusive jurisdiction thereof. The police force of the several municipalities concerned shall have concurrent jurisdiction with the police force of the city for the maintenance of good order and the enforcement of ordinances throughout said zones, areas and spaces. But any license that may be issued within said zones, areas or spaces shall be granted by the proper authorities of the municipality concerned, and the fees arising therefrom shall accrue to the treasury of the said municipality concerned and not to that of the city.\nThe Mayor"}},{"id":"PH-H3584-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"ARTICLE II"},"text":{"en":"The Mayor.— The mayor shall be elected at large by the qualified voters of the city. He shall be at least thirty years of age, a resident of the city at least one year prior to his election, and a qualified voter therein: Provided, That the first election for mayor shall be held at the general election for provincial and municipal official next following the approval of this Act. He shall hold office for four years, unless sooner removed for just cause and with due process of law.\nHe shall receive a salary of not exceeding five thousand four hundred pesos per annum. With the approval of the President of the Philippines, the mayor may be provided, in addition to his salary, a noncommutable allowance of not exceeding two thousand pesos per annum."}},{"id":"PH-H3584-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"ARTICLE II"},"text":{"en":"The Vice-Mayor.— There shall be a vice-mayor who shall perform the duties of the mayor, in the event of the sickness, absence, or other temporary incapacity of the mayor, or in the event of the definite vacancy in the position of mayor, until said office is filled in accordance with law. The vice-mayor shall also preside over the meetings of the municipal board, but he shall have no right to vote except in case of tie. If, for any reason, the vice-mayor is temporarily incapacitated for the performance of the duties of the mayor, or said office of the vice-mayor is vacant, the duties of the mayor shall be performed by the councilor who received the highest number of votes in the last election. The acting mayor shall have the same powers and duties as the mayor.\nThe vice-mayor shall perform such other duties as may be assigned to him by the mayor or prescribed by law or ordinance. He shall be elected in the same manner as the mayor and shall at the time of his election possess the same qualifications as the mayor. For services as acting mayor, the vice-mayor shall receive a compensation equivalent to the salary of the mayor during such period."}},{"id":"PH-H3584-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"ARTICLE II"},"text":{"en":"General powers and duties of the Mayor.— Unless otherwise provided by law, the mayor shall have immediate control over the executive and administrative functions of the different departments of the city, subject to the authority and supervision of the President. He shall have the following general powers and duties:\n(a) To comply with and enforce and give the necessary orders for the faithful enforcement and execution of the provisions of this Charter and other laws and ordinances in effect within the jurisdiction of the city;\n(b) To safeguard all the lands, buildings, records, moneys, credits and other properties and rights of the city, and, subject to the provisions of this Charter, have control over all its property;\n(c) To see that all the taxes and other revenues of the city are collected, and applied in accordance with appropriations to the payment of the municipal expenses;\n(d) To cause to be instituted judicial proceedings to recover property and funds of the city wherever found, to cause to be defended all suits against the city, and otherwise to protect the interests of the city. The mayor may, in the interest of the service and with the approval of the department head of the National Government first had, transfer officers and employees not appointed by the President of the Philippines from one section, division or service to another section, division or service within the same department without changing the compensation they receive;\n(e) To see that the executive officer and employees of the city properly discharge their respective duties;\n(f) To examine and inspect the books, records, and papers of all officers, agents, and employees of the city over whom he has executive supervision and control at least twice a year, and whenever occasion arises. For this purpose, he shall be provided by the municipal board with such clerical or other assistance as may be necessary;\n(g) To give such information and recommend such measures to the board as he shall deem advantageous to the city;\n(h) To represent the city in all its business matters and sign in its behalf all its bonds, contracts, and obligations made in accordance with law and ordinance;\n(i) To submit to the municipal board at least two months before the beginning of each fiscal year a budget of receipts and expenditures of the city;\n(j) To receive, hear, and decide, as he may deem proper, the petitions, complaints, and claims of the residents concerning all cases of municipal matters of an administrative or executive character;\n(k) To grant or refuse, municipal licenses or permits of all classes and to revoke the same for violation of the conditions upon which they were granted, or if acts prohibited by law or municipal ordinance are being committed under the protection of such licenses or in the premises in which the business for which the same has been granted is carried on, or for any other good reason of general interest;\n(l) To exempt, with the concurrence of the division superintendent of schools, deserving poor pupils from the payment of schools fees or of any part thereof;\n(m) To take such emergency measures as may be necessary to avoid fires and floods and to mitigate the effects of storms and other public calamities;\n(n) To submit an annual report to the President of the Philippines; and\n(o) To perform such other duties and exercise such other executive powers as may be prescribed by law or ordinance."}},{"id":"PH-H3584-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"ARTICLE II"},"text":{"en":"Secretary to the Mayor.— The mayor shall appoint one secretary who shall hold office at the pleasure of the mayor and who shall receive a compensation, to be fixed by ordinance approved by the President of the Philippines, at not exceeding three thousand three hundred pesos per annum.\nThe secretary shall have charge and custody of all records and documents of the city and of any office or department thereof for which provision is not otherwise made; shall keep the corporate seal and affix the same with his signature to all ordinances and resolutions signed by the mayor and to all other official documents and papers of the government of the city as may be required by law or ordinance; shall attest all executive orders, proclamations, ordinances and resolutions signed by the mayor; shall, upon request, furnish certified copies of all city records, and documents in his charge which are not of a confidential character and shall charge twenty centavos for each one hundred words, including the certificates, such fees to be paid directly to the city treasurer; and shall perform such other duties as the mayor may require of him.\nThe Municipal Board"}},{"id":"PH-H3584-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Constitution and organization of the municipal board—Compensation of members thereof .— The municipal board shall be the legislative body of the city and shall be composed of the vice-mayor, who shall be its presiding officer, and eight councilors who shall be elected at large by popular vote during every election for provincial and municipal officials in conformity with the provisions of the Revised Election Code. The said presiding officer shall vote only in case of tie. In case of sickness, absence, suspension or other temporary disability of any member of the board, or if necessary to maintain a quorum, the President of the Philippines may appoint a temporary substitute belonging to the same political party, who shall possess all the rights and perform all the duties of a member of the board until the return to duty of the regular incumbent.\nIf any member of the municipal board should be a candidate for office in any election, he shall be disqualified to act with the board in the discharge of the duties conferred upon it relative to election matters, and in such case, the other members of the board shall discharge said duties without his assistance, or they may choose a disinterested elector of the city to act with the board in such matters in his stead.\nThe members of the municipal board shall receive a per diem in such amount as may be fixed by ordinance but in no case to exceed twenty pesos for each day of attendance of the session of the board. The presiding officer shall receive a per diem of thirty pesos."}},{"id":"PH-H3584-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Qualifications, suspensions and removal of members of the board.— The members of the municipal board shall, at the time of their election, be qualified electors of the city, residents therein for at least one year immediately prior to their election, and not less than twenty-three years of age. Elections for members of the board shall be held on the date of the regular election for provincial and municipal offices, and elected members shall assume office on the first day of January next following their election, upon qualifying, and shall hold office for four years and until their successors shall have been duly elected and qualified. The eight candidates receiving the greatest number of votes shall be declared elected.\nThe members of the municipal board may be suspended of removed from office under the same circumstances, in the same manner, and with the same effect, as elective provincial officers and the provisions of law providing for the suspension or removal of elective provincial officers are hereby made applicable to the said members of the board.\nVacancies in the municipal board shall be filled in accordance with the provisions of the Revised Election Code."}},{"id":"PH-H3584-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Appointment, salary and duties of secretary of the board.— The board shall have a secretary who shall be chosen by the board and who shall serve during the term of office of the members thereof. The compensation of the secretary shall be fixed by ordinance, approved by the President of the Philippines, at not exceeding one thousand nine hundred twenty pesos per annum. A vacancy in the office of the secretary shall be filled temporarily for the unexpired term in like manner.\nThe secretary shall be in charge of the records of the municipal board. He shall keep a full record of the proceedings of the board, and file all documents relating thereto; shall record in a book kept for that purpose, all ordinances, and all resolutions and motions directing the payment of money or creating liability, enacted or adopted by the board, with the dates of passage of the same and of the publication of ordinances; shall keep a seal, circular in form, with the inscription, \"Municipal Board-City of Bago\", and affix the same, with his signature, to all ordinances and other official acts of the board, and shall present the same for signature to the presiding officer of the Board; shall cause each ordinance to be published as herein provided; shall upon request, furnish copies of all records of public character in his charge under the seal of his office and charge twenty centavos for each one hundred words, including the certificate, the fees to be paid directly to the city treasurer; and shall keep his office and all records therein which are not of a confidential character open to public inspection during usual business hours."}},{"id":"PH-H3584-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Methods of transacting business by the board—Veto; authentication and publication of ordinances.— Unless the President of the Philippines orders otherwise, the board shall hold one ordinary session for the transaction of business during each week on a day which shall be fixed by resolution, and such extraordinary sessions, not exceeding thirty days during any one year, as may be called by the mayor. It shall sit with open doors, unless otherwise ordered by an affirmative vote of five members. It shall keep a record of its proceedings and determine its rule of procedure not herein set forth. Five members of the board shall constitute a quorum for the transaction of business. But a smaller number may adjourn from day to day and may compel the immediate attendance of any member absent without good cause by issuing to the police of the city an order for his arrest and production at the session under such penalties as shall have been previously prescribed by ordinances. Five affirmative votes shall be necessary for the passage of any ordinance, or of any resolution or motion directing the payment of money or creating liability, but any other measure shall prevail upon the majority votes of the members present at any meeting duly called and held. The ayes and nays shall be taken and recorded upon the passage of all ordinances, upon all resolutions or motions directing the payment of money or creating liability, and at the request of any member, upon any other resolution or motion. Each approved ordinance, resolution or motion shall be sealed with the seal of the board, signed by the presiding officer and the secretary of the board and recorded in a book kept for the purpose, and shall, on the day following its passage, be posted by the secretary at the main entrance of the city hall, and shall take effect and be in force on and after the tenth day following its passage unless otherwise stated in said ordinance, resolution or motion or vetoed by the mayor as hereinafter provided. A vetoed ordinance, if repassed, shall take effect ten days after the veto is overridden by the required votes unless otherwise stated in the ordinance or again disapproved by the mayor within said time.\nEach ordinance and each resolution or motion directing the payment of money or creating liability enacted or adopted by the board shall be forwarded to the Mayor for his approval. Within ten days after the receipt of the ordinance, resolution, or motion, the mayor shall return it with his approval or veto. If he does not return it within that time, it shall be deemed to be approved. If he returns it with his veto, his reasons therefor in writing shall accompany it. It may then be again enacted by the affirmative votes of seven members of the board, to override the veto, and the ordinance or resolution becomes finally approved. The mayor shall have the power to veto any particular items of an appropriations ordinance, or of an ordinance, resolution or motion directing the payment of money or creating liability, but the veto shall not effect item or items to which he does not object. The item or items objected to shall not take effect except in the manner heretofore provided in this section as to ordinances, resolutions, and motions returned to the board with his veto, but should an item or items in an appropriation ordinance be disapproved by the mayor, the corresponding item or items in the appropriation ordinance of the previous year shall be deemed restored unless otherwise expressly directed in the veto."}},{"id":"PH-H3584-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"ARTICLE III"},"text":{"en":"General powers and duties of the board.— Except as otherwise provided by law, and subject to the conditions and limitations thereof, the municipal board shall have the following legislative powers:\n(a) To provide for the levy and collection of taxes for general and special purposes in accordance with law, including specifically the power to levy real property tax not to exceed two per centum ad valorem;\n(b) To make all appropriations for the expenses of the government of the city;\n(c) To fix, with the approval of the department head, the number and salaries of officials and employees of the city not otherwise provided for in this Act;\n(d) To authorize, with the approval of the department head, the free distribution of medicines to the employees and laborers of the city whose salary or wage does not exceed sixty pesos per month or two pesos and fifty centavos per day; and of fresh or evaporated native milk to indigent mothers residing in the city and of less of age residing in the city, the distribution to be made under the direct supervision and control of the mayor;\n(e) To fix the tariff of fees and charges for all services rendered by the city or any of its departments, branches or officials;\n(f) To provide for the erection and maintenance or the rental of the necessary buildings for the use of the city;\n(g) To establish and maintain schools as provided by law and, with the approval of the Director of Public Schools, to fix reasonable tuition fees for instruction therein;\n(h) To establish or aid in the establishment and maintenance of vocational schools and institutions of higher learning conducted by the national government or any of its subdivisions and agencies, and, with the approval of the Director of Public Schools, to fix reasonable tuition fees for instruction in the vocational schools and in those higher educational institutions supported by the city;\n(i) To provide for and maintain an efficient police force and make all necessary police ordinances, with a view to the confinement and reformation of vagrants, disorderly persons, mendicants, prostitutes, and persons convicted of violating any of the ordinances of the city;\n(j) To provide for and maintain an efficient fire force and provide engine houses, fire engines, hose trucks, hooks, and ladders, and other equipment for the prevention and extinguishment of fires, and to regulate the management and use of the same;\n(k) To establish fire zones, determine the kinds of buildings or structures that may be erected within their limits, regulate the manner of constructing and repairing the same, and fix the fees for permits for the construction, repair, or demolition of buildings and structures;\n(l) To regulate the use of lights in stables, shops, and other buildings and places and to regulate and restrict the issuance of permits for the building of bonfires and the use of firecrackers, skyrockets, and other pyrotechnic display, and to fix the fees for such permits;\n(m) To make regulations to protect the public from conflagration and to prevent and mitigate the effects of famine, floods, storms and other public calamities, and provide relief for persons suffering from same;\n(n) To regulate and fix the amount of the license fees for the following: hawkers, peddlers and hucksters, not including hucksters or peddlers who sell only native vegetables, fruits or foods, personally carried by the hucksters or peddlers; auctioneers, plumbers, barbers, collecting agencies, mercantile agencies, advertising agencies, beauty parlors, massagists, tattooers, jugglers, acrobats, hotels, clubs, restaurants, cafes, lodging houses, boarding houses, livery garages, livery stables, boarding stables, dealers in large cattle, public billiard tables, laundries, cleaning and dyeing establishments, public warehouses, circuses and other similar parades, public vehicles, race tracks, horse races, bowling alleys, shooting galleries, merry-go-rounds, pawnshops, dealer in second hand merchandise, junk dealers, brewers, distillers, rectifiers, money changers and brokers, public ferries, theaters, and theatrical performances, places of amusement, and the keeping, preparation and sale of meat, poultry, fish, game, butter, cheese, lard, vegetables, bread, and other provisions;\n(o) To tax and fix the license fees for dealers of automobiles or accessories or both, and retail dealers of other merchandise, which dealers are not yet subject to the payment of any municipal tax, for the purpose of taxation. These retail dealers shall be classified as: (A) retail dealers in general merchandise; and (B) retail dealers exclusively engaged in the sale of: (a) textiles, including knitted goods, (b) hardwares, including glasswares, cooking utensils, electrical goods and construction materials, (c) groceries, including toilet articles except perfumery, (d) drugs, including medicines and perfumeries, (e) books, including stationery, paper, and office supplies, (f) jewelry, (g) slippers, and (h) arms, ammunitions and sporting goods;\n(p) To tax, fix the license fees for, regulate the business and fix the location of, match factories, blacksmith shops, foundries, steam boilers, lumberyards, shipyards, the storage and sale of gunpowder, tar, pitch, resin, coal, oil, gasoline, benzine, turpentine, hemp, cotton, nitroglycerine, petroleum, or any of the products thereof, and all other highly combustible or explosive material, and other establishments likely to endanger the public safety or give rise to conflagration or explosion, and, subject to the rules and regulations issued by the Director of Health Services in accordance with law, tanneries, renderies, tallow chandleries, embalmers, and funeral parlors, bone factories and soap factories;\n(q) To regulate the method of using steam engines and boilers, and all other motive powers other than marine steam engines, or boilers or those belonging to the Government of the Philippines; to provide for the inspection thereof and fix a reasonable fee for such inspection, and to regulate and fix the fees for the license of the engineers engaged in operating the same;\n(r) To enact ordinances for the maintenance and preservation of peace and good morals;\n(s) To regulate and fix the license fees for the keeping of dogs, to authorized their impounding and destruction when running at large, contrary to ordinances, and to tax and regulate the keeping or training of fighting cocks;\n(t) To establish and maintain municipal pounds; to regulate, restrain and prohibit the running at large of domestic animals, and provide for the distraining, impounding and sale of the same for the penalty incurred, and the cost of the proceedings; and to impose penalties upon the owners of said animals for the violation of any ordinances in relation thereto;\n(u) To prohibit, and provide for the punishment of, cruelty to animals;\n(v) To provide regulations for the weighing and measuring of bricks, lumber, coal, and other articles of merchandise;\n(w) To regulate, fix the location of, and fix the license fees for the establishment and operation of night clubs, dancing schools, dance halls, cabarets, cockpits and other places of amusement;\n(x) Subject to the provisions of existing law, to provide for the laying out, construction and improvement, and to regulate the use of streets, avenues, alleys, sidewalks, wharves, piers, parks, cemeteries, and other public places; to provide for lighting, cleaning, and sprinkling of streets and public places; to regulate, fix license fees for, and prohibit the use of the same for processions, signs, signposts, awnings, awning posts, the carrying or displaying of banners, placards, advertisements, or hand bills, or the flying of signs, flags, or banners, whether along, across, over or from buildings, along the same; to prohibit the placing, throwing, depositing, or leaving of obstacles of any kind, offal, garbage, refuse or other offensive matter or matters liable to cause damage in the streets and other public places, and to provide for the collection and disposition thereof; to provide for the inspection of, fix the license fee for, and regulate the openings in the same for the laying of gas, water, sewer, and other pipes, the building and repair of the tunnels, sewers, and drains, and all structures in and under the same, and the erecting of poles and the stringing of wires therein; to provide for and regulate crosswalks, curbs, and gutters therein; to name streets without a name and provide for and regulate the numbering of houses and lots fronting thereon or in the interior of the blocks; to regulate traffic and sale upon the streets and other public places; to provide for the abatement of nuisances in the same and punish the author or owners thereof; to provide for the construction and maintenance, and regulate the use of bridges, viaducts, and culverts; to prohibit or regulate ball playing, kite flying, hoop rolling and other amusements which may annoy persons using the streets and public places, or frighten horses or other animals; to regulate the speed of horses and other animals, motor and other vehicles, cars, and locomotives within the limits of the city; to regulate the locating, constructing, and laying of the tracks of electric and other forms of railroads in the streets or other public places of the city as may be authorized by law; unless otherwise provided by law, to provide for and change the location, grade, and crossing of railroads and to compel any such railroad to raise or lower its tracks to conform to such provisions and changes; and to require railroad companies to fence their property, or any part thereof, and to construct and repair ditches, drains, sewers and culverts along and under their tracks, so that the natural drainage of the streets and adjacent property shall not be obstructed;\n(y) To provide for the construction and maintenance of, and regulate the navigation on, canals and water courses within the city and provide for the clearing and purification of the same; unless otherwise provided by law, to provide for the construction and maintenance, and regulate the use of public landing places, wharves, piers, docks and levees, and of those of private ownership; and to provide for or regulate the drainage and filling of private premises when necessary in the enforcement of sanitary rules and regulations issued in accordance with law;\n(z) Subject to the provisions of the Public Service Law, to fix the charges to be paid by all water craft landing at or using public wharves, docks, levees, or landing places owned, operated, managed or controlled by the city;\n(aa) To provide for the maintenance of waterworks for the purpose of supplying water to the inhabitants of the city, and for the purification of the source of supply and the places through which the same passes, and to regulate the consumption and use of the water; to fix, subject to the provisions of the Public Service Law, and provide for the collection of rents therefor; and to regulate the construction, repair, and use of hydrants, pumps, cisterns, and reservoirs;\n(bb) To provide for the establishment and maintenance and regulate the use of public drains, sewers, latrines, and cesspools;\n(cc) Subject to the rules and regulations issued by the Director of Health Services in accordance with law, to provide the establishment, maintenance and regulation, and to fix the fees for the use of public stables, laundries and baths, and public markets, and to prohibit the establishment or operation within the city limits of public markets by any person, entity, association, or corporation other than the city;\n(dd) To establish or authorized the establishment of slaughterhouses, to provide for their veterinary of sanitary inspection, to regulate the use of the same, and to charge reasonable slaughter fees. No fees shall be charged for veterinary or sanitary inspection of meat from large cattle or other domestic animals slaughtered outside the city, when such inspection was had at the place where the animals were slaughtered;\n(ee) To provide measures preventing discrimination or the exclusion of any race or races in or from any institution, establishment, or service open to the public within the city limits; to regulate and provide for the inspection of all gas, electric, telephone, and street railway conduits, mains, motor, and other apparatus, and provide for the condemnation, substitution, or removal of the same when defective or dangerous;\n(ff) To declare, prevent, and provide for the abatement of nuisances; to regulate the ringing of bells and the making of loud or unusual noises; to provide that owners, agents, or tenants of buildings or premises keep and maintain the same in sanitary condition, and that, in case of failure to do so within sixty days from the date of serving a written notice, the city health officer shall cause the same to be kept in sanitary condition, the cost thereof to be assessed to the owner to the extent of not to exceed sixty per centum of the assessed value, which cost shall constitute a lien against the property, and to regulate or prohibit or fix the license fees for the use of property on or near public ways, grounds, or places, or elsewhere within the city, for a display of electric signs, for the erection or maintenance of billboards or structures of whatever material erected, maintained, or used for the display of posters, signs or other pictorial or reading matter, except signs displayed at the place where the profession or business advertised thereby is in whole or part conducted;\n(gg) To provide for the enforcement of the rules and regulations issued by the Director of Health Services, and by ordinance, to prescribe penalties for violation of such rules and regulations;\n(hh) To extend its ordinances over all water within the city, over any boat or other floating structures thereon and, for the purpose of protecting and insuring the purity of the water supply of the city, over all territory within the drainage area of such water supply, and within one hundred meters of any reservoir, conduit, canal, aqueduct, or pumping station used in connection with the city water service;\n(ii) To tax, fix the license fee for, and regulate the sale, trading in or disposal of, alcoholic or malt beverages, wines and mixed or fermented liquors, including tuba, basi, tapuy, offered for retail sale;\n(jj) To regulate any other business or occupation, not specifically mentioned in the preceding paragraphs, and to impose a license fee upon all persons engaged in the same or who enjoy privileges in the city;\n(kk) To grant fishing and fisheries privileges subject to the provisions of the Fisheries Act;\n(ll) To fix the date of the holding of fiesta in the city not oftener than once a year and to alter, not oftener than once in three years, the date fixed for the celebration thereof; and (mm) To enact all ordinances it may deem necessary and proper for the sanitation and safety, the furtherance of the prosperity, and the promotion of the morality, peace, good, order, comfort, convenience, and general welfare of the city and its inhabitants, and such others as may be necessary to carry into effect and discharge the powers and duties conferred by this Charter, and to fix the penalties for the violation of ordinances, which shall not exceed a two hundred peso fine or six months imprisonment, or both such fine and imprisonment for a single offense."}},{"id":"PH-H3584-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"ARTICLE III"},"text":{"en":"Restrictive provisions.— No commercial sign, signboard, or billboard shall be erected or displayed on public lands, premises, or buildings. If after due investigation, and having given the owners an opportunity to be heard, the mayor shall decide that any sign, signboard, or billboard displayed or exposed in public view is offensive to the sight or is otherwise a nuisance, he may order the removal of such sign, signboard, or billboard, and if the same is not removed within ten days after he has issued such order, he may himself cause its removal, and the sign, signboard, or billboard shall thereupon be forfeited to the city and the expenses incident to the removal of the same shall become a lawful charge against any person or property liable for the creation or display thereof.\nDepartments and Offices of the City"}},{"id":"PH-H3584-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"City departments.— There shall be a finance department, an engineering department, a law department, a health department, a police and fire department, and an assessment department. Unless otherwise provided by law, the mayor shall have general supervisory control over all the city departments.\nThe municipal board may from time to time make such readjustment of the duties of the several departments as the public interest may demand, and, with the approval of the President, may consolidate any department, division, or office of the city with any other department, division or office."}},{"id":"PH-H3584-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Powers and duties of heads of departments.— Each head of department of the city government shall be in control of such department under the direction and supervision of the mayor and shall possess such powers as may be prescribed herein or by ordinance. He shall certify to the correctness of all payrolls and vouchers of his department covering the payment of money before payment, except as herein otherwise expressly provided. At least four months before the beginning of each fiscal year, he shall prepare and present to the mayor an estimate of the receipts and appropriation necessary for the operation of his department during the ensuing fiscal year and shall submit therewith such information for purposes of comparison as the mayor may desire. He shall submit to the mayor as often as required reports covering the operation of his department.\nIn case of the absence or sickness, or inability to act for any other reason, of the head of one of the city departments, the officer next in charge of that department shall act in his place with authority to sign all necessary papers, vouchers and requisitions and similar documents."}},{"id":"PH-H3584-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Appointment, removal and salaries of officials and employees.— The President of the Philippines shall appoint with the consent of the Commission on Appointments, the judge and auxiliary judge of the city court, the city treasurer, the city engineer, the city attorney, the city health officer, the chief of police and fire department, and other heads of such city departments as may be created. Said officers shall not be suspended nor removed except in the manner and for causes provided by law.\nAll other officers and employees of the city whose appointments are not otherwise provided for by law shall be appointed by the mayor upon recommendation of the corresponding city department head in accordance with the Civil Service Law, and they shall be suspended or removed in accordance with law."}},{"id":"PH-H3584-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Officers not to engage in certain transactions.— It shall be unlawful for any city officer, directly or indirectly, individually or as a member of firm, to engage in any business transaction with the city, or with any of its authorized officials, boards, agents, or attorneys, whereby money is to be paid, directly or indirectly, out of the resources of the city to such person or firm; or to purchase any real estate or other property belonging to the city, or which shall be sold for taxes or assessments, or by virtue of legal process at the suit of the city; or to be surety for any person having a contract or doing business with the city, for the performance of which security may be required; or to be surety on the official bond of any officer of the city and shall not be financially interested in any transaction or contract in which the National Government or any instrumentality or subdivision thereof is an interested party."}},{"id":"PH-H3584-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"ARTICLE IV"},"text":{"en":"Statement of assets.— Before assuming office, every official and regular employee of the city government shall file in the office of the city attorney a sworn statement of his assets and property holdings.\nFinance Department"}},{"id":"PH-H3584-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"ARTICLE V"},"text":{"en":"The City Treasurer—His powers, duties and compensation.— There shall be a city treasurer, who shall have charge of the department of finance and shall act as chief fiscal officer and financial adviser of the city and custodian of its funds. He shall receive a salary not exceeding four hundred two hundred pesos per annum. He shall have the following general powers and duties:\n(a) He shall collect all taxes due the city, all licenses authorized by law or ordinance, all rents due for lands, markets and other property owned by the city, further charges of whatever nature fixed by law or ordinance, and shall receive and issue receipts for all costs, fees, fines, and forfeitures imposed by the city court;\n(b) He shall collect all miscellaneous charges made by the engineering department and by other departments of the city government, and all charges made by the city engineer for inspections, permits, licenses, and the installations, maintenance and services rendered in the operation of the private privy system;\n(c) He shall collect, as deputy of the Commissioner of Internal Revenue, by himself or through deputies, all taxes and charges imposed by the Government of the Republic of the Philippines upon property or persons in the City of Bago, depositing daily such collections in any depository bank of the Government;\n(d) Unless otherwise specifically provided by law or resolution, he shall perform in and for the city the duties imposed by law or resolution upon provincial treasurers generally, as well as the other duties imposed upon him by law;\n(e) He shall purchase and issue all supplies, equipment or other property required by the city, through the purchasing agent, or otherwise, as may be authorized, subject to the general provisions of law relating thereto;\n(f) He shall be accountable for all funds and property of the city and shall render such accounts in connection therewith as may be prescribed by the Auditor General;\n(g) He shall deposit daily all city funds and collection in any bank duly designated as Government depository; and\n(h) He shall disburse the funds of the city in accordance with duly authorized appropriations, upon properly executed vouchers bearing the approval of the chief of the department concerned, and on or before the twentieth day of each month, he shall furnish the mayor and the municipal board for their administrative information a statement of the appropriation, expenditures and balances of all funds and accounts as of the last day of the month preceding;\nLaw Department"}},{"id":"PH-H3584-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"ARTICLE VI"},"text":{"en":"The City Attorney and Register of Deeds ex-officio—His compensation, powers and duties.— The city attorney who shall discharge his duties under the general supervision of the Secretary of Justice shall be the chief legal adviser of the city. He shall receive a salary of not exceeding three thousand six hundred pesos per annum. He shall act as city register of deeds ex officio with an additional compensation of six hundred pesos per annum. He shall have the following powers and duties:\n(a) He shall personally of through his representatives represent the city in all civil cases wherein the city or any officer thereof, in his official capacity, is a party, and shall prosecute and defend all civil actions related or connected with any city officer or interest;\n(b) He shall, when directed by the mayor, institute and prosecute in the city’s interest all suits or any bond, lease, or other contract and upon any breach or violation thereof;\n(c) He shall, when requested, attended meetings of the board, draw ordinances, contracts, bonds, leases, and other instruments involving any interest of the city and inspect and pass upon any such instrument already drawn;\n(d) He shall give his opinion in writing, when requested by the mayor or the board or any of the heads of the city departments, upon any question relating to the city or the rights or duties of any city officer thereof;\n(e) He shall, whenever it is brought to his knowledge that any city officer or employee is guilty of neglect or misconduct in office, or that any person, firm, or corporation holding or exercising any franchise or public privilege from the city, has failed to comply with any condition, or to pay any consideration mentioned in the grant of such franchise or privilege, investigate or cause to be investigated the same report to the mayor;\n(f) He shall investigate all charges of crimes, misdemeanors and violations of laws and city ordinances and prepare the necessary information or make the necessary complaints against the persons accused. He may conduct such investigations by taking oral evidence of reputed witnesses and for this purpose may, by subpoena or subpoena duces tecum, summon witnesses to appear and testify under oath before him, or to produce documents and other evidence before him, and the attendance of, or the production of documents and other evidence by an absent or recalcitrant witness may be enforced by application to the city court or the court of first instance;\n(g) He shall have charge of the prosecution of all crimes, misdemeanors and violations of laws and city ordinances triable in the Court of First Instance of Negros Occidental and the city court, and shall discharge all the duties in respect to criminal prosecutions enjoined by law upon provincial fiscals;\n(h) He shall cause to be investigated the causes of sudden deaths which have not been satisfactorily explained and when there is suspicion that the cause arose from unlawful acts or omissions of other persons or from foul play. For that purpose he may cause autopsies to be made in case it is deemed necessary and shall be entitled to demand and receive for the purpose of such investigations or autopsies the aid of the health officer;\n(i) He shall at all times render such professional services as the mayor or board may require, and shall have such powers and perform such duties as may be prescribed by law or ordinance; and\n(j) He shall perform the duties prescribed by law for registers of deeds.\nEngineering Department"}},{"id":"PH-H3584-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"The City Engineer—His powers and duties.— There shall be a city engineer, who shall be in charge of the department of engineering and public works. He shall receive a salary not exceeding four thousand two hundred pesos per annum. He shall have the following powers and duties:\n(a) He shall have charge of all the surveying and engineering work of the city, and shall perform such services in connection with public improvements, or any work entered upon or proposed by the city, or any department thereof, as may require the skill and experience of a civil engineer;\n(b) He shall ascertain, record, and establish monuments, of the city survey and from thence extend the survey of the city, and locate, establish and survey all city property and also private property abutting on the same, whenever directly by the mayor;\n(c) He shall prepare and submit plans, maps, specifications and estimates for buildings, streets, bridges, docks, and other public works and supervise the construction and repair of the same;\n(d) He shall make such tests and inspections of engineering materials used in construction and repair as may be necessary to protect the city from the use of materials of a poor or dangerous quality;\n(e) He shall have the care of all public buildings, including markets and slaughterhouses and all buildings rented for city purposes, and of any system now or hereafter established by the city for lighting the streets, public places or public buildings;\n(f) He shall have the care of all public streets, parks, and bridges, and shall maintain, clean, sprinkle and regulate the use of the same for all purposes as provided by ordinance; shall collect and dispose of all garbage, refuse, the contents of closets, vaults, and cesspools, and all other offensive and dangerous substances within the city;\n(g) He shall have the care and custody of all public docks, wharves, piers, levees, and landing places owned by the city;\n(h) He shall prevent the encroachment of private buildings and fences on the streets and public places of the city;\n(i) He shall have general supervision and inspection of all private docks, wharves, piers, levees and landing places and other property bordering on the harbor, rivers, esteros and waterways of the city, and shall issue permits for the construction, repair and removal of the same;\n(j) He shall have the care and custody of the public system of waterworks and sewers, and all sources of water supply, and shall control, maintain and regulate the use of the same, in accordance with the ordinance relating thereto; shall inspect and regulate the use of all private systems for supplying water to the city and its inhabitants, and all private sewers and their connection with the public sewer system;\n(k) He shall supervise the laying of mains and connections for the purpose of supplying gas to the inhabitants of the city;\n(l) He shall inspect and report upon the conditions of public property and public works whenever required by the mayor;\n(m) He shall supervise and regulate the location and use of engines, boilers, forges, and other manufacturing and heating appliances in accordance with law and ordinance relating thereto. He is authorized to charge fees at rates to be fixed by the board with the approval of the department head, for the sanitation and transportation services and supplies furnished by his department;\n(n) He shall inspect and supervise the construction, removal, and safety of private buildings, and regulate and enforce the numbering of houses, in accordance with the ordinance of the city;\n(o) With the previous approval of the mayor in each case, he shall order the removal of buildings and structures erected in violation of the ordinances; shall order the removal of the materials employed in the construction or repair of any building or structure made in violation of said ordinances; shall cause buildings and structures dangerous to the public to be made secure or torn down; and\n(p) He shall file and preserve all maps, plans, notes, surveys, and other papers and documents pertaining to his office."}},{"id":"PH-H3584-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"ARTICLE VII"},"text":{"en":"Execution of authorized public works and improvement.— All repair or construction of any work or public improvement, except parks, boulevards, streets or alleys, involving an estimated cost of three thousand pesos or more shall be awarded by the mayor, upon the recommendation of the city engineer, to the lowest responsible bidder after public advertisement by posting notices of the call for bids in conspicuous place in the city hall and other public places, and by publication in the Official Gazette, both for not less than ten days: Provided, However, That of the Philippines, upon the recommendation of the Secretary of Public Works and Communications, execute by administration and such public work costing three thousand pesos or more.\nIn case of public works involving an expenditure of less than three thousand pesos, it shall be discretionary with the city engineer either to proceed with the work himself or to let the contract to the lowest bidder after such publication and notice as shall be deemed appropriate or as may be, by regulations, prescribed.\nHealth Department"}},{"id":"PH-H3584-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"ARTICLE VIII"},"text":{"en":"The City Health Officer—His salary, powers and duties.— There shall be a city health officer, who shall have charge of the health department. He shall receive a salary not exceeding four thousand two hundred pesos per annum. The city health officer shall have the following general powers and duties:\n(a) He shall have general supervision over the health and sanitary condition of the city;\n(b) He shall execute and enforce all laws, ordinances and regulations relating to the public health;\n(c) He shall recommend to the municipal board the passage of such ordinances as he may deem necessary for the preservation of the public health;\n(d) He shall cause to be prosecuted all violations of sanitary laws or ordinances or regulations;\n(e) He shall make sanitary inspections and may be aided therein by such members of the police force of the city or the national police as shall be designated as sanitary police by the chief of police or proper national police officer and such sanitary inspector as may be authorized by laws;\n(f) He shall keep a civil register for the city and shall record therein all births, marriages and deaths with their respective dates; and\n(g) He shall perform such other duties not repugnant to law or ordinance, with reference to the health and sanitation of the city as the Director of Health Services shall direct.\nPolice and Fire Department"}},{"id":"PH-H3584-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"The Chief of Police—His powers, duties and compensation.— There shall be a chief of police who shall have charge of the police and fire department. He shall receive a salary not exceeding three thousand six hundred pesos per annum. He shall have the following general powers and duties:\n(a) He may issue supplemental regulations not incompatible with law or general regulations promulgated by the proper department head of the national government, in accordance with law, for the governance of the city police and detective force;\n(b) He shall quell riots, disorders, disturbances of the peace, and shall arrest and prosecute through the city attorney violations of any law or ordinance; shall exercise police supervision over all land and water within the police jurisdiction of the city; shall be charged with the protection of the rights of person and property wherever found within the jurisdiction of the city, and shall arrest when necessary to prevent the escape of the offender, violators of any law or ordinance, and all who obstruct or interfere with him in the discharge of his duty; shall have charge of the city prison; shall be responsible for the safekeeping of all prisoners until they shall be released from custody, in accordance with law, or delivered to the warden of the proper prison or penitentiary;\n(c) He may take good and sufficient bail for the appearance before the judge of the city court of any person arrested for violation of any city ordinance;\n(d) He shall have authority within the police limits of the city to serve and execute criminal processes of any court;\n(e) He shall be the deputy sheriff of the city, and as such, he shall, personally or by representative, attend the sessions of the city court, and shall execute promptly and faithfully all writs and processes of said court;\n(f) He shall have charge of the fire-engine houses, fire engines, hose trucks, hooks and ladders, and all other fire apparatus;\n(g) He shall have full police powers in the vicinity of fires;\n(h) He shall have authority to remove or demolish any building or other property whenever it shall become necessary to prevent the spreading of fire or to protect adjacent property;\n(i) He shall investigate and report to the mayor upon the origin and cause of all fires occurring within the city;\n(j) He shall inspect all buildings erected or under construction or repair within the city and determine whether they provide sufficient protection against fire and comply with the ordinances relating thereto;\n(k) He shall have charge of the city’s fire alarm service;\n(l) He shall supervise and regulate the stringing, grounding, and installation of wires for all electrical connections with a view to avoid conflagrations, interference with public traffic or safety, or the necessary operation of the police and fire department;\n(m) He shall supervise the manufacture, storage and use of petroleum, gas, acetylene, gunpowder and other highly combustible matters and explosives; and\n(n) He shall have such other powers and perform such other duties as may be prescribed by law or ordinance."}},{"id":"PH-H3584-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Chief of the detective service.— There shall be a chief of the detective service who shall, under the chief of police, have charge of the detective work of the department and of the detective force of the city, and shall perform such other duties as may be assigned to him by the chief of police or prescribed by law or ordinance.\nThe chief of detective service shall receive a salary not exceeding one thousand eight hundred pesos per annum."}},{"id":"PH-H3584-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"ARTICLE IX"},"text":{"en":"Peace officers—Their powers and duties.— The mayor, the chief of police, the chief of the detective service, and all officers and members of the city police and detective force shall be peace officer. Such peace officers are authorized to serve and execute all processes of the city court and criminal processes of all other courts to whomsoever directed within the jurisdictional limits of the city or within the police limits as hereinabove defined, within the same territory, to pursue and arrest, without warrant, any person found in suspicious places or under suspicious circumstances reasonably tending to show that such person has committed, or is about to commit, any crime or breach of the peace; to arrest or cause to be arrested, without warrant, any offender when the offense is committed in the presence of a peace officer or within his view; in such pursuit or arrest to enter any building, ship, boat or vessel or take into custody any person therein suspended of being concerned in such crime or breach of the peace, and any property suspected of having been stolen, and to exercise such other powers and perform such other duties as may be prescribed by law or ordinance. They shall detain and arrest a person only in accordance with the provisions of existing laws relative to such detention until he can be brought before the proper magistrate. Whenever the mayor shall deem it necessary to avert danger or to protect life and property, in case of riot, disturbance, or public calamity, or when he has reason to fear any serious violation of law and order, he may call upon the provincial commander or other members of the Armed Forces of the Philippines.\nAssessment Department"}},{"id":"PH-H3584-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"ARTICLE X"},"text":{"en":"The City Treasurer as City Assessors ex officio—His powers and duties.— The city treasurer shall act as the city assessor ex officio with an additional compensation of six hundred pesos per annum and shall have charge of the department of assessment. He and his authorized deputies are empowered to administer any oath authorized in connection with the valuation of real estate for the assessment and collection of taxes. He shall make the list of the taxable real estate in the city, arranging in the order of the lot and block numbers, the names of the owners thereof, with a brief description of the property opposite each such name and the cash value thereof. In making this list, the city assessor shall take into consideration any sworn statement made by the owners of the property, but shall not be prevented thereby from considering other evidence on the subject and exercising his own judgment in respect thereto. For the purpose of completing this list, he and his representatives may enter upon the real estate for the purpose of examining and measuring it, and may summon witnesses, administer oaths to them and subject them to examination concerning the ownership and the amount of real estate and its cost value. He may, if necessary, examine the records of the office of the Register of Deeds of the Province of Negros Occidental showing the ownership of real estate in the city."}},{"id":"PH-H3584-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Real estate exemption from taxation.— The following shall be exempted from taxation:\n(a) Lands or buildings owned by the Republic of the Philippines, the Province of Negros Occidental or the City of Bago and burying grounds, churches and their adjacent parsonages and convents and lands or buildings used exclusively for religious, charitable, scientific or educational purposes, and not for profit; but such exemption shall not extend to lands or buildings held for investment, though income therefrom be devoted to religious, charitable, scientific or educational purposes;\n(b) Lands or buildings which are the only real property of the owner, and the value of which does not exceed two thousand pesos; and\n(c) Machinery, which term shall embrace machines, mechanical contrivances, instruments, appliances and apparatus attached to the real estate, used for industrial, agricultural or manufacturing purposes, during the first five years of the operation of the machinery."}},{"id":"PH-H3584-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Declaration to be made by persons acquiring or improving real estate.— It shall be the duty of each person who, at any time, acquires real estate in the city, and of each person who constructs or adds to any improvements on real estate owned by him in the city, to prepare and present to the city assessor within a period of sixty days next succeeding such acquisition, construction or addition, a sworn declaration setting forth the value of the real estate acquired or the improvement constructed or addition made by him and a description of such property sufficient to enable the city assessor readily to identify the same. Any person having acquired real estate who fails to make and present the declaration herein required within the said period of sixty days shall be deemed to have waived his right to notice of the assessment of such property and the assessment of the same in the name of its former owner shall, in all cases, be valid and binding on all persons interested and for all purposes, as though the same has been assessed in the name of its present owner."}},{"id":"PH-H3584-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Action when owner makes no returns, or is unknown, or ownership is in dispute or in doubt, or when land and improvements are separately owned.— If the owner of any parcel of real estate shall fail to make a return thereof, or if the city assessors is unable to discover the owner of any real estate, he shall nevertheless list the same for taxation, and charge the tax against the true owner, if known, and if unknown, then as against an unknown owner. In case of doubt or dispute as to ownership of real estate, the taxes shall be levied against the possessor or possessors thereof. When it shall appear that there are separate owners of the land and the improvements thereon, a separate assessment of the property of each shall be made."}},{"id":"PH-H3584-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Action in case estate has escaped taxation.— If it shall come to the knowledge of the city assessor that any taxable real estate in the city has escaped listing, it shall be his duty to list and assess the same at the time and in the manner provided in the next succeeding section and to charge against the owner thereof the taxes due for the current year and the last preceding one year, and the taxes thus assessed shall be legal and collectible by all the remedies herein provided, and if the failure of the city assessor to assess such taxes at the time when they should have been assessed was due to any fault or negligence on the part of the owner of such property, the penalties shall be added to such back taxes as though they had been assessed at the time when they should have been assessed."}},{"id":"PH-H3584-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"ARTICLE X"},"text":{"en":"When assessment may be increased or reduced.— The city assessor shall, during the first fifteen days of January of each year, add to this list of taxable real estate in the city the value of the improvements placed upon such property during the preceding year, and any property which is taxable and which has theretofore escaped taxation. He may during the same period revise and correct the assessed value of any or all parcels of real estate in the city which are not assessed at their true money value, by reducing or increasing the existing assessment as the case may be."}},{"id":"PH-H3584-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Publication of complete list and proceedings thereon.— The city assessor shall, after the list shall have been completed, inform the public by notice published for seven days in a newspaper of general circulation in the city, if any, and by notice posted for seven days at the main entrance of the city hall, that the list is on file in his office and may be examined by any person interested therein, and that upon the date fixed in the notice which shall not be later than the tenth day of February, the city assessor will be in his office for the purpose of hearing complaints as to the accuracy of the listing of the property and the assessed value thereof. He shall further notify in writing each person the amount of whose tax will be changed by such proposed change, by delivering or mailing at least thirty days in advance of the date fixed in the notice, such notification to such person or his authorized agent at the last known address of such owner or agent in the Philippines.\nIt shall be his duty carefully to preserve and record in his office copies of said notice. On the day fixed in his notice, and five days thereafter, he shall be present in his office to hear all complaints filed within the period by persons against whom taxes have been assessed as owners of real estate, and he shall make his decision forthwith and enter the same in well-bounded book, to be kept by him for that purpose, and if he shall determined that injustice had been done or errors have been committed, he is authorized to amend the list in accordance with his findings."}},{"id":"PH-H3584-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"ARTICLE X"},"text":{"en":"City assessor ex officio to authenticate list of real estate assessed.— The city assessor shall authenticate each list of real estate valued and assessed by him as soon as the same is completed, by signing the following certificate at the foot thereof:\n\"I hereby certify that the foregoing list contains a true statement of the piece or pieces of taxable real estate belonging to each person named in the list, and its true cash value, and that no real estate taxable by law in the City of Bago has been omitted from the list according to the best of my knowledge and belief.\n____________________ (Signature) City Assessor\""}},{"id":"PH-H3584-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Time and manner of appealing to Board of Appeals.— In case any owner of real estate or his authorized agent shall feel aggrieved by any decision of the city assessor under the preceding sections of this Article such owner or agent may, within thirty days after the entry of such decision, appeal to the Board of Tax Appeals. The appeal shall be perfected by filing a written notice of the same with the city assessor, and it shall be the duty of that officer forthwith to transmit the appeal to the Board of Tax Appeals with all written evidence in his possession relating to such assessment and valuation."}},{"id":"PH-H3584-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Composition and compensation of Board of Tax Appeals.— There shall be a Board of Tax Appeals which shall be composed of five members to be appointed by the President of the Philippines with the consent of the Commission on Appointments. Three members of the Board shall be selected from among government officials in the city other than those in charge of assessment and they shall serve without additional compensation. The two other members shall be selected from among property owners in the city and they shall each receive a compensation of ten pesos for each day of session actually attended. The chairman of the Board shall be designated in the appointment and shall have the power to designate any city official or employee to serve as the secretary of the Board without additional compensation.\nThe members of the Board of Tax Appeals shall hold office for a term of two years unless sooner removed by the President of the Philippines."}},{"id":"PH-H3584-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Oath to be taken by members of the Board of Tax Appeals.— Before organizing as such, the members of the Board of Tax Appeals shall take the following oath before the City Judge or some other officer authorized to administer oaths:\n\"I do solemnly swear (or affirm) that I will hear and determine well and truly all matters and issues between taxpayers and the city assessor submitted for my decision. So help me God. (In case of affirmation the last four words are to be stricken out.) ____________________ (Signature) Member of the Board of Tax Appeals\" \"Subscribed and sworn to (or affirmed) before me this ________ day of ________, 19___.\n____________________ (Signature and title of officer administering oath)\""}},{"id":"PH-H3584-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Proceedings before the Board of Tax Appeals and the department head.— The Board of Tax Appeals shall hold such number of sessions as may be authorized by the Secretary of Finance, shall hear all appeals duly transmitted to it, and shall decide the same forthwith. It shall have authority to cause to be amended the listing and valuation of the property in respect to which any appeal has been perfected by order signed by the board or a majority thereof, and transmit it to the city assessor who shall amend the tax list in conformity with said order. It shall also have power to revise and correct, with the approval of the department head first had, any and all erroneous or unjust assessments and valuation for taxation, and make a correct and just assessment and state the true valuation in each case when it decides that the assessment previously made is erroneous or unjust. The assessment when so corrected shall be as lawful and valid for all purposes as though the assessment had been made within the time herein prescribed. Such assessment and revaluation shall be made on due notice to the individual concerned who shall be entitled to be heard by the Board of Tax Appeals before any reassessment or revaluation is made. The decision of the Board of Tax Appeals shall be final unless the department head declares the decision reopened for review by him, in which case, he may make such revision or revaluation as in his opinion the circumstances justify. Such revision when approved by the President of the Philippines shall be final."}},{"id":"PH-H3584-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Taxes on real estate—Extension and remission of the tax.— A tax, the rate of which shall not exceed two per centum ad valorem to determined by the municipal board, shall be levied annually on or before the second Monday of January on the assessed value of all real estate in the city subject to taxation. All taxes on real estate for any year shall be due and payable annually on the first day of January and from this date such taxes together with all penalties accruing thereto, shall constitute a lien on the property subject to such taxation.\nSuch lien shall be superior to all other liens, mortgages or encumbrances of any kind whatsoever; and shall be enforceable against the property whether in the possession of the delinquent or any subsequent owner, and can only be removed by the payment of the tax and penalty.\nAt the option of the taxpayer, the tax for any year may be paid in two installments to be fixed annually by the municipal board simultaneously with the rate per centum ad valorem taxation: Provided, That the time limit for the first and second installments shall be set at not later than the thirty-first day of May and the thirtieth day of October of each year, respectively.\nAny person, who on the last day set for the payment of the real estate tax as provided in the preceding paragraphs, shall be within the premises of the city hall willing and ready to pay the tax but is unable to effect it on account of the large number of taxpayer therein present, shall be furnished a properly prescribed card which will entitle him to pay the tax without penalty on the following day.\nThe words \"paid under protest\" shall be written upon the face of the real estate tax receipt upon the request of any person willing to pay the tax under protest. Confirmation in writing of an oral protest shall be made within thirty days.\nAt the expiration of the time for the payment of the real estate tax without penalty, the taxpayer shall be subject, from the first day of delinquency, to the payment of a penalty at the rate to two per centum for each full month of delinquency that has expired, on the amount of the original tax due, until the tax shall have been paid in full or until the property shall have been forfeited to the city as provided in this Act: Provided, That in no case shall the total penalty exceed twenty-four per centum of the original tax due.\nIn the event that the crop is extensively damaged or that a great lowering of the prices of products is registered in any year, or that a similar disaster extends throughout the province, or for other good and sufficient reason, the municipal board may, by resolution passed on or before the thirty-first day of December of such year, extend the time for the collection of the tax on real estate in the city for a period not to exceed three months, or remit wholly or in part the payment of the tax or penalty for the ensuing year, but such resolution shall have to specify clearly the grounds for such extension or remission and shall not take effect until it shall have been approved by the department head.\nThe President of the Philippines may, in his discretion, remit or reduce the real estate taxes for any year in the city if he deems this to be in the public interest."}},{"id":"PH-H3584-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Seizure of the personal property for delinquency in payment of the tax.— After a property shall have become delinquent in the payment of taxes and said taxes and the corresponding penalties shall remain unpaid ninety days after payment thereof shall have become due, the city treasurer or his deputy, if he desires to compel payment through seizure of any personal property of any delinquent person or persons, shall issue a duly authenticated certificate, based on the records of his office, showing the fact of delinquency and the amount of the tax and penalty due from said delinquent person or persons or from each of them. Such certificate shall be sufficient warrant for the seizure of the personal property belonging to the delinquent person or persons in question not exempt from seizure; and these proceedings may be carried out by the city treasurer, his deputy, or any other officer authorized to carry out legal proceedings."}},{"id":"PH-H3584-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Personal property exempt from seizure and sale for delinquency.— The following personal property shall be exempt from seizure, sale and execution for delinquency in the payment of the real estate tax:\n(a) Tools and implements necessarily used by the delinquent in his trade or employment;\n(b) One horse, cow or carabao, or other beast of burden, such as the delinquent may select, and necessarily used by him in his ordinary occupation;\n(c) His necessary clothing and that of his family;\n(d) Household furniture and utensils necessary for housekeeping and used for that purpose by the delinquent such as he may select of a value not exceeding one hundred pesos;\n(e) Provisions of individual or family use sufficient for four months;\n(f) The professional libraries of lawyers, judges clergymen, physicians, engineers, school teachers, and music teachers, not exceeding five hundred pesos in value;\n(g) The fishing boat and net, not exceeding the total value of one hundred pesos, the property of any fisherman, by the lawful use of which he earns a livelihood; and\n(h) Any article or material which forms part of a home or of any improvement on any real estate."}},{"id":"PH-H3584-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"ARTICLE X"},"text":{"en":"The owner may redeem personal property before sale.— The owner of the personal property seized may redeem the same from the collecting officer at any time after seizure and before sale by tendering to him the amount of the tax, the penalty, and the cost incurred up to the time of tender. The cost to be charged in making such seizure and sale shall only embrace the actual expenses of seizure and preservation of the property pending the sale and no charge shall be imposed for the services of the collecting officer or his deputy."}},{"id":"PH-H3584-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Sale of seized personal property.— Unless redeemed as hereinbefore provided, the property seized through the proceedings under Section forty-three hereof, shall, after due advertisement, be exhibited for sale at public auction and so much of the same as shall satisfy the tax, penalty and cost of seizure shall be sold to the highest bidder. The purchaser at such sale shall acquire an indefeasible title to the property sold.\nThe advertisement shall state the time, place and cause of sale, and be posted for ten days prior to the date of the auction, at the main entrance of the city hall and at a public and conspicuous place in the district where the property was seized.\nThe sale shall take place at the discretion of the city treasurer or his deputy, either at the main entrance of the city hall or at the district where such property was seized. If no satisfactory bid is offered in the aforementioned district, another auction shall be had upon notice published anew."}},{"id":"PH-H3584-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Return of officer-Disposal of surplus.— The officer directing the sale under the preceding section shall forthwith make return of his proceedings and note thereof shall be made by the city treasurer upon his records. Any surplus resulting from the sale, over and above the tax, penalty and cost, and any property remaining in possession of the officer, shall be returned to the taxpayer on account of whose delinquency the sale has been made."}},{"id":"PH-H3584-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Vesting title to real estate in the city government.— Upon the expiration of one year from the date on which the taxpayer has been delinquent, and in the event of continued default in the payment of the penalty, all private rights, titles and interests in and to the real estate on which said tax is delinquent, shall be indefeasibly vested in the city government, subject only to the rights of redemption and repurchase hereinafter provided for: Provided, That the title acquired by said city government to real estate shall not be superior to the title thereto of the original owner prior to the seizure thereof."}},{"id":"PH-H3584-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Redemption of real estate before the seizure.— At any time after the delinquency shall have occurred, but not after the expiration of ninety days from the date of publication of the advertisement provided for in the next succeeding section, the owner or his lawful representative, or any person having any lien, right, or any other legal or equitable interest in the said property, may pay the taxes and penalties accrued and thus redeem the property. Such redemption shall operate to divest the city government of its title to the property in question and to revert the same to the original owner, but when such redemption shall be mad by a person other than the owner, the payment shall constitute a lien on the property, and the person making such payment shall be entitled to recover the same from the original owner, or if he be a lessee, he may retain the amount of said payment from the proceeds of any income due to the owner of such property: Provided, That the person exercising the right of redemption shall not acquire a title to said property better than that of the original owner prior to the seizure."}},{"id":"PH-H3584-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Notice of seizure of real estate.— Notice of seizure of real estate shall be given by posting notices at the main entrance of the city hall, the provincial building and all the municipal buildings in the Province of Negros Occidental in English and Spanish and in the dialect commonly used in the locality and a copy of said notice shall be sent by registered mail to the owner of the property. A copy of said notice shall also be posted on the property subject to seizure. Such notice shall state the name of the delinquent person, the date on which such delinquency commenced, the amount of the taxes and penalties then due, and shall state that unless such taxes and penalties are paid within ninety days from the date of the publication of such notice, the forfeiture of the delinquent real estate to the city government shall become absolute."}},{"id":"PH-H3584-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Ejectment of occupants of seized property.— After the expiration of ninety days from the date of the publication of the notice of delinquency provided for in the next preceding section, the city treasurer, or his deputy, may issue to the mayor or to other officers authorized by law to execute and enforce the laws, a certificate describing the parcel of real estate on which the taxes have been declared delinquent, stating the amount of taxes due, and the penalties and costs accrued by reason of the delinquency, and requesting him to eject from said property all the tenants and occupants thereof. Upon receiving such certificate, the mayor or any other official authorized to enforce the law, shall forthwith have all the tenants and occupants who refuse to recognize the title of the city expelled from the property in question, and to that end, he may use the police force: Provided, That if the property so seized is or includes a residential home, the occupant thereof shall be given sufficient time, not exceeding ten days from the date of the notice of ejectment, to vacate the premises."}},{"id":"PH-H3584-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Redemption of real property before sale.— After the title to the property shall have become vested in the city government in the manner provided for in Section forty-eight hereof, and at any time prior to the sale or the execution of the contract of sale by the city treasurer to a third party, the original owner or his legal representative or any person having any lien, right, or other legal interest or equity in said property, shall have the right to redeem the entire property in question, by paying the full amount of taxes and penalties due thereon at the time of the seizure, and if the city treasurer shall have entered into a lease of the property, the redemption shall be made subject to said lease: Provided, That the payment of the sale may, at the discretion of the purchaser, be made on installment, extending over a period not exceeding twelve months, but the initial payment, which must be made on the date of the filing of the application for redemption, and every subsequent payment, shall not be less than twenty-five per centum of the entire sum due, and shall in no case be less than two pesos, unless the total or the balance of the amount due on all seized property from the taxpayer is less than two pesos. The purchaser may occupy the property after paying the first installment and the usual taxes on the property shall be payable in the year after that in which the application for redemption was approved. Any failure of the purchaser to pay an installment on the date it is due shall have the effect of a forfeiture to the city government of any partial payment made by said purchaser, and in case he has taken possession of the property, he shall forthwith surrender the same to the city government. In case the purchaser should fail to relinquish possession of said property, the city treasurer or his deputy shall forthwith adopt measures to eject therefrom all the tenants or occupants thereof as provided for in this Act: Provided, That the original owner of any real estate seized prior to the approval of this Act, who redeems the same within six months subsequent to its approval, is hereby released from any obligation he may have to the Government for rent for the use of such property: Provided, further, That the provision of this section shall apply to redemption of real estate seized for delinquency in the payment of taxes thereon and not redeemed up to the date of the approval of this Act."}},{"id":"PH-H3584-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Notice of sale of real estate at public auction.— At any time after the forfeiture of any real estate shall have become absolute, the treasurer, pursuant to the rules of procedure to be promulgated by the department head, may announce the sale of the real estate seized on account of delinquency in the payment of taxes thereon, for the redemption of which no application has been filed. Such announcement shall be made by posting a notice for three consecutive weeks at the main entrances of the city hall and of all the municipal buildings of the province, in either English or Spanish, and in the dialect commonly used in the locality, and by publishing the same once a week during three consecutive weeks in newspaper of general circulation in the city. Copies of such notice shall be sent immediately by registered mail to the delinquent taxpayer at the latter’s home address, if known. The notice shall state the amount of the taxes and penalties so due, the time and place of sale, the name of the taxpayer against whom the taxes are levied, and the approximate area, the lot number and the location by district and street and the street number and district or barrio where the real estate to be sold is located."}},{"id":"PH-H3584-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Sale of real estate-Conditions.— At any time during the sale or prior thereto the taxpayer may stay the proceedings by paying the taxes and penalties to the city treasurer or his deputy. Otherwise the sale shall proceed and shall be held either at the main entrance of the city hall or on the premises of the real estate to be sold as the city treasurer or his deputy may determine. The payment of the sale price may, at the option of the purchaser, be made on installments covering a period not exceeding twelve months, but the initial payment which shall be made at the time of the sale, and such subsequent payment shall not be less than twenty-five per centum of the sale price, and shall in no case be less than two pesos, unless the total or the balance of the amount due on all seized property in the name of the taxpayer is less than two pesos. The purchaser may occupy the property after paying the first installment, and the usual taxes on the property shall be payable in the year following that in which the sale took place. Any failure of the purchaser to pay the total price of the sale within twelve months from the date thereof, shall be sufficient ground for its cancellation, and any part payment made shall revert to the city government, and if the purchaser has taken possession of the property, he shall forthwith surrender the same to the city government. In case the purchaser should fail to relinquish possession of the property, the city treasurer or his deputy shall immediately take steps to eject the tenants or occupants of the property, in accordance with the procedure prescribed in Section fifty-one of this Act.\nThe city treasurer or his deputy shall make a report of the sale to the municipal board within five days after the sale and shall make the same appear on its records. The purchaser at this sale shall receive from the city treasurer or his deputy a certificate showing the proceedings of the sale, describing the property sold, stating the name of the purchaser, the sale price, the condition of payment, the amount paid and the exact amount of the taxes and penalties."}},{"id":"PH-H3584-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Redemption of real estate after sale.— Within one year from and after the date of sale, the delinquent taxpayer or any other person in his behalf, shall have the right to redeem the property sold by paying to the city treasurer or his deputy the amount of the taxes, penalties costs and interests at the rate of twelve per centum per annum on the purchase price, if paid in whole, or on any portion thereof as may have been paid by the purchaser and such payment shall invalidate the certificate of sale issued to the purchaser, if any, and shall entitle the person making such payment to a certificate to be issued by the city treasurer or his deputy, stating that he has thus redeemed the property, and the city treasurer or his deputy, upon the return by the purchaser of the certificate of sale previously issued to him, shall forthwith refund to the purchaser the entire sum paid by him with interest at twelve per centum per annum, as provided for herein, and such property shall thereafter be free from the lien of such taxes and penalties."}},{"id":"PH-H3584-A56","no":56,"noLabel":{"en":"Section 56."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Execution of deed of final sale.— In case the delinquent taxpayer shall not redeem the property sold as herein provided within one year from the date of the sale, and the purchaser shall then have paid the total purchase price, the city treasurer, as grantor, shall execute a deed in form and effect sufficient to convey to the purchaser so much of the real estate against which the taxes have been assessed as has been sold, and said deed shall succinctly recite all the proceedings upon which the validity of the sale depends. Any balance remaining from the proceeds upon which the validity of the sale after deducting the amount of the taxes and penalties due, and the cost, if any, shall be returned to the original owner or his representatives."}},{"id":"PH-H3584-A57","no":57,"noLabel":{"en":"Section 57."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Taxes and penalties which shall be paid upon redemption or repurchase.— The taxes and penalties to be paid by way of redemption or repurchase, shall comprise in all cases only the original tax by virtue of the failure to pay which the seizure was made, and its incidental penalties, up to the date of the forfeiture of the real estate to the Government."}},{"id":"PH-H3584-A58","no":58,"noLabel":{"en":"Section 58."},"chapter":{"en":"ARTICLE X"},"text":{"en":"Taxes-Legal Procedure.—\n(a) The assessment of a tax shall constitute a lawful indebtedness of the taxpayer to the city which may be enforced by a civil action in any court of competent jurisdiction, and this remedy shall be in addition to all remedies provided by law.\n(b) No court shall entertain any suit assailing the validity of a tax assessed under this Charter until the taxpayer shall have paid, under protest, the taxes assessed against him; nor shall any court declare any tax invalid by reason of irregularities or informalities in the proceedings of the officers charged with the assessment or collection of the taxes or of failure to perform their duties within the time specified for their performance, unless such irregularities, informalities or failure shall have impaired the substantial rights of the taxpayer.\n(c) No court shall entertain any suit assailing the validity of the tax sale of land under this Charter until the taxpayer shall have paid into the court the amount for which the land was sold, together with interest at the rate of twelve per centum per annum upon the sum from the date of sale to the time of instituting the suit. The money so paid into court shall belong and shall be delivered to the purchaser at the tax sale, if the deed is declared invalid, and shall be returned to the depositor, should he fail in his action.\n(d) No court shall declared any such sale invalid by reason of any irregularities or informalities in the proceedings of the officer charged with the duty of making the sale, or by reason of failure by him to perform his duties within the time herein specified for their performance, unless such irregularities, informalities or failure shall have impaired the substantial right of the taxpayer.\nTax Allotment and Special Assessment for Public Improvements\nSection 5 9. Allotment of internal revenue and other taxes.— Of the internal revenue accruing to the National Treasury under Chapter II, Title XII of Commonwealth Act Numbered Four hundred and sixty-six, and other taxes collected by the national government and allotted to the various provinces, as well as the national aid for schools, the City of Bago shall receive a share equal to what it would receive if it were a regularly organized province."}},{"id":"PH-H3584-A60","no":60,"noLabel":{"en":"Section 60."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Power to levy special assessments for certain purposes.— The municipal board may, by ordinance, provide for the levying and collection, by special assessment of the lands comprised within the district or section of the city specially benefited, of a part not to exceed sixty per centum of the cost of laying out, opening, constructing, straightening, widening, extending, grading, paving, curbing, walling, deepening or otherwise establishing, repairing, enlarging, or improving public avenues, roads, streets, alleys, sidewalks, parks, plazas, bridges, landing places, wharves, piers, docks, levels, reservoirs, waterworks, water mains, water course, esteros, canals, drains and sewer, including the cost of acquiring the necessary land and public improvements thereon, as hereinafter provided.\nIn case of national public works, the municipal board, as an agency of the national government shall, when the President of the Philippines so directs it, provide for the levying and collection by special assessment of the lands within the section or district of the city specially benefited of the cost or a part thereof to be determined by the President, of laying out, opening, constructing, straightening, widening, extending, grading, paving, curbing, walling, or deepening, or otherwise repairing, enlarging or improving national roads and other national public works within the city, including the cost of acquiring the necessary land and improvements thereon."}},{"id":"PH-H3584-A61","no":61,"noLabel":{"en":"Section 61."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Property subject to special assessment.— All lands comprised within the district or section benefited, except those owned by the Republic of the Philippines, shall be subject to the payment of the special assessment."}},{"id":"PH-H3584-A62","no":62,"noLabel":{"en":"Section 62."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Basis of apportionment.— The amount of the special assessment shall be apportioned and computed according to the assessed valuation of such lands as shown in the books of the city assessors. If the property has not been declared for taxation purposes, the city assessor shall immediately declare it for the owner and assess its value, and such value shall be the basis of the apportionment and computation of the special assessment due thereon."}},{"id":"PH-H3584-A63","no":63,"noLabel":{"en":"Section 63."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Ordinance levying special assessment.— The ordinance providing for the levying and collection of a special assessment shall describe with reasonable accuracy the nature, extent and location of the work to be undertaken; the probable cost of the work; the percentage of the cost to be defrayed by special assessment; the district or section which shall be subject to the payment of the special assessment, the limit whereof shall be stated by metes and bounds if practicable, and by other reasonable accurate means if otherwise, and the period, which shall not be less than five nor more than ten years, in which said special assessment shall be payable without interest. One uniform rate per centum for all lands in the entire district or section subject to the payment of all the special assessment need not be established, but different rates for different parts or sections of the city, according as said property will derive greater or less benefit from the proposed work, may be fixed.\nIt shall be the duty of the city engineer to make the plans, specifications, and estimates of the public works contemplated to be undertaken."}},{"id":"PH-H3584-A64","no":64,"noLabel":{"en":"Section 64."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Publication of proposed ordinance levying special assessment.— The proposed special assessment ordinance shall be published, with a list of the owners of the lands affected thereby, once a week for four consecutive weeks in any newspaper published in the city, one in English, one in Spanish and one in the local dialect, if there be any, and in default of local papers, in any newspaper of general circulation in the city. The said ordinance in English, Spanish and the local dialect shall also be posted in places where public notices are generally posted in the city and also in the district or section where the public improvement is constructed or contemplated to be constructed.\nThe secretary of the municipal board shall, on application, furnish a copy of the proposed ordinance to each landowner affected, or his agent and shall, if possible, send to all of them a copy of said proposed ordinance by ordinary mail or otherwise."}},{"id":"PH-H3584-A65","no":65,"noLabel":{"en":"Section 65."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Protest against special assessment.— Not later than ten days after the last publication of the ordinance and the list of landowners, as provided in the preceding section, the landowners affected, if they composed a majority whose holding represent more than one-half of the total assessed value of said lands, may file with the municipal board a protest against the enactment of the ordinance. The protest shall be duly signed by them and shall set forth the address of the signers and the arguments in support of their objection or protest against the special assessment established in the ordinance. If no protest is filed within the time and under the condition above specified, the ordinance shall be considered approved as published."}},{"id":"PH-H3584-A66","no":66,"noLabel":{"en":"Section 66."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Hearing of protest.— The municipal board shall designate a date and place for the hearing of the protest filed in accordance with the next preceding section and shall give reasonable time to all protestants who have given their addresses and to all landowners affected by any protest or protests, and shall order the publication once a week for two consecutive weeks, of a notice of the place and date of the hearing in the same manner herein provided for the publication of the proposed special assessment ordinance. All pertinent arguments and evidence presented by the landowners interested or their attorney shall be attached to the proper records. After the hearing, the municipal board shall either modify its ordinance or approve it in toto and send notice of its decision to all interested parties who have given their addresses, and shall order the publication of the ordinance as approved finally together with a list of the owners of the parcels of land affected by the special assessment, three times weekly, for two consecutive weeks, in the same manner hereinabove prescribed. The ordinance finally passed by said body shall be sent to the mayor with all the papers pertaining thereto, for his approval or veto as in the case of other city ordinances. If the mayor approves it, the ordinance shall be published as above provided, but if he vetoes it, the procedure in similar cases provided in this Act shall be observed."}},{"id":"PH-H3584-A67","no":67,"noLabel":{"en":"Section 67."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"When ordinance is to take effect.— Upon the expiration of thirty days from the date of the last publication of the ordinance as finally approved, the same shall be effective in all respects, if no appeal therefrom is taken to the proper authorities in the manner hereinafter prescribed."}},{"id":"PH-H3584-A68","no":68,"noLabel":{"en":"Section 68."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Appeals.— Any time before the ordinance providing for the levying and collection of special assessment becomes effective in accordance with the preceding section, appeals from such special assessment may be filed with the President of the Philippines in the case of public works undertaken or contemplated to the undertaken by the national government, and with the Secretary of Finance in the case of public works undertaken or contemplated to be undertaken by the city. In all cases, the appeal shall be in writing and signed by at least a majority of the owners of the lands situated in the special assessment zone whose holdings represent more than one-half of the total assessed value of the lands affected. The appellants shall immediately give the board a written notice of the appeal and the secretary of said board shall, within ten days after receipt of the notice of appeal, forward to the officers who has jurisdiction to decide the appeal an excerpt from the minutes of the board relative to the proposed special assessment and all the documents in connection therewith."}},{"id":"PH-H3584-A69","no":69,"noLabel":{"en":"Section 69."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Decision of the appeal.— Only appeals made within the time in the manner prescribed in this Act shall be entertained, and the officer to whom the appeal is made may call for further hearing or decide the same in accordance with its merits as shown in the papers or documents submitted to him. All appeals shall be decided within sixty days after receipt by the appellate officer of the docket of the case, and such decision shall be final."}},{"id":"PH-H3584-A70","no":70,"noLabel":{"en":"Section 70."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Fixing of amount of special assessment.— As soon as the ordinance is in full force and effect, the city treasurer shall determine the amount of the special assessment which the owners of each parcel of land comprised within the zone described in the ordinance levying the same is to pay each year during the prescribed period, and shall send to each of such landowners a written notice thereof by ordinary mail. If upon completion of the public works it should appear that the actual cost thereof is smaller or greater than the estimated cost, the city treasurer shall without delay proceed to correct the assessment by increasing or decreasing, as the case may be, the special tax on each of land affected, for the balance of the unpaid annual installments. If all annual installments have already been paid, the city treasurer shall fix the amount of credit to be allowed to, or the additional special tax to be levied upon, the land, as the case may be. In all cases, he shall give notice of such rectification to the parties interested."}},{"id":"PH-H3584-A71","no":71,"noLabel":{"en":"Section 71."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Payment of special assessment.— All sums due from any landowner or owners as a result of any action taken pursuant to this article shall be payable to the city treasurer in the same manner as the annual ordinary tax levied upon real property, and shall be subject to the same penalties for delinquency and be enforced by the same means as said annual ordinary tax; and all said sums, together with any of said penalties shall, from the dates on which they are assessed, constitute special lien on said land, with the sole exception of the lien for the non-payment of the ordinary real property tax. If, upon recomputation of the amount of special assessment in accordance with the next preceding section, it appears that the landowner has paid more than what is correctly due from him, the amount paid in excess shall be refunded to him immediately upon demand; in the other case, the landowner shall have one year within which to pay without penalty the amount still due from him. Said period shall be counted from the date the landowner receive the proper notice."}},{"id":"PH-H3584-A72","no":72,"noLabel":{"en":"Section 72."},"chapter":{"en":"ARTICLE XI"},"text":{"en":"Disposition of proceeds.— The proceeds of the special assessment and penalties thereon shall be applied exclusively to the purposes for which the assessments were levied. It shall be the duty of the city treasurer to turn over to the National Treasury all collections made by him from special assessment levies for national public works.\nCity Budget"}},{"id":"PH-H3584-A73","no":73,"noLabel":{"en":"Section 73."},"chapter":{"en":"ARTICLE XII"},"text":{"en":"Annual Budget.— At least three months before the beginning of each fiscal year, the city treasurer shall present to the mayor a certified detailed statement by department of all receipts and expenditures of the city pertaining to the preceding fiscal year, and to the first seven months of the current fiscal year, together with an estimate of the receipts and expenditures for the remainder of the current fiscal year, and he shall submit with this statement of detailed estimate of the revenues and receipts of the city from all sources for the ensuing fiscal year. Upon the receipt of this statement and estimate, and the estimates of department heads as required by Section eighteen of this Charter, the mayor shall formulate and submit to the municipal board at least two and a half detailed budget covering the estimated necessary expenditures for the said ensuing fiscal year, which shall be the basis of the annual appropriation ordinance: Provided, However, That in no case shall the aggregate amount of such appropriation exceed the estimate of revenues and receipts submitted by the city treasurer as provided above: Provided, further, That not less than fifteen per cent of the expected revenues of the city for any fiscal year shall be appropriated for public improvements of the said fiscal year."}},{"id":"PH-H3584-A74","no":74,"noLabel":{"en":"Section 74."},"chapter":{"en":"ARTICLE XII"},"text":{"en":"Supplemental Budget.— Supplemental budget formulated in the same manner as the annual budget may be adopted when special or unforeseen circumstances make such action necessary."}},{"id":"PH-H3584-A75","no":75,"noLabel":{"en":"Section 75."},"chapter":{"en":"ARTICLE XII"},"text":{"en":"Failure to enact an appropriation ordinance.— Whenever the board fails to enact an appropriation ordinance for any fiscal year before the end of the previous fiscal year, the several sums appropriated in the last appropriation ordinance, for the objects and purposes therein specified shall be deemed to be reappointed for the several objects and purposes specified in said last appropriation ordinance, and shall go into effect on the first day of the new fiscal year as the appropriation ordinance for the year, until a new appropriation ordinance is duly enacted.\nThe City Court"}},{"id":"PH-H3584-A76","no":76,"noLabel":{"en":"Section 76."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Regular, auxiliary and acting judge of city court.— There shall be a city court for the City of Bago for which there shall be appointed a city judge and an auxiliary city judge.\nThe city judge may, upon proper application, be allowed a vacation of not more than thirty days every year with salary. The auxiliary city judge shall discharge the duties of the city judge in case of absence, incapacity or inability of the latter until he assumes his post, or until a new judge shall have been appointed. During his incumbency the auxiliary city judge shall enjoy the powers, emoluments and privileges of the city judge who shall not receive any remuneration therefor except the salary to which he is entitled by reason of his vacation provided for in the Charter.\nIn case of absence, incapacity or inability of both the city judge and the auxiliary city judge, the Secretary of Justice shall designate the municipal judge of any of the adjoining municipalities to preside over the city court, and he shall hold the office temporarily until the regular incumbent or the auxiliary judge thereof shall have resumed office, or until another judge shall have been appointed in accordance with the provisions of this Charter. The municipal judge so designated shall receive his salary as municipal judge plus seventy per cent of the salary of the city judge whose office he has temporarily assumed.\nThe city judge shall receive a salary not exceeding four thousand two hundred pesos per annum. He shall have his residence in the city."}},{"id":"PH-H3584-A77","no":77,"noLabel":{"en":"Section 77."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Clerk and employee of the city court.— There shall be a clerk of the city court who shall be appointed by the mayor in accordance with Civil Service Law, rules and regulations, and who shall receive a compensation, to be fixed by ordinance approved by the President of the Philippines, at not exceeding one thousand five hundred pesos per annum. He shall keep the seal of the court and affix it to all orders, judgments, certificates, records, and other documents issued by the court. He shall keep a docket of the trials in the court, in which he shall record in a summary manner the names of the parties and the various proceedings in civil cases, and in the criminal cases, the name of the defendant, the charge against him, the names of the witnesses, the date of the arrest, the appearance of the defendant, together with the fines and costs adjudged or collected in accordance with judgment. He shall have the power to administer oaths. The clerk of the city court shall, at the same time, be sheriff of the city and shall as such have the same powers and duties conferred by existing law to provincial sheriffs. The municipal board may provide for such number of clerks in the office of the clerk of the city court as the needs of the service may demand."}},{"id":"PH-H3584-A78","no":78,"noLabel":{"en":"Section 78."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Jurisdiction of city court.— The city court shall have the same jurisdiction in civil and criminal cases and the same incidental powers as are at present conferred upon them by law. It shall have concurrent jurisdiction with the Court of First Instance over all criminal cases arising under the laws relating to gambling and management of lotteries, to assaults where the intent to kill is not charged or evident upon the trial, to larceny, embezzlement and estafa where the amount of money or property stolen, embezzled or otherwise involved does not exceed the sum or value of two hundred pesos, to the sale of intoxicating liquors, to falsely impersonating an officer, to malicious mischief, to trespass on government or private property, and to threatening to take human life. It may also conduct preliminary investigation for any offense, without regard to the limits of punishment and may release or commit and bind over any person charged with such offense to secure his appearance before the proper court."}},{"id":"PH-H3584-A79","no":79,"noLabel":{"en":"Section 79."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Incidental power of city court.— The city court shall have power to administer oaths and to give certificates thereof; to issue summons, writs, warrants, executions and all other processes necessary to enforce its orders and judgments; to compel the attendance of witnesses; to punish contempts of court by fine or imprisonment, or both, within the limitation imposed by law; and require of any person arrested a bond for good behavior or to keep the peace, or for the further appearance of such person before a court of competent jurisdiction. But no such bond shall be accepted, unless it be executed by the person in whose behalf it is made with sufficient surety or sureties to be approved by said court."}},{"id":"PH-H3584-A80","no":80,"noLabel":{"en":"Section 80."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Procedure in city court in prosecution for violation of law and ordinance.— In a prosecution for the violation of any ordinance, the first process shall be summons; except that a warrant for the arrest of the offender may be issued in the first instance upon the affidavit of any person that such ordinance has been violated, and that the person making the complaint has reasonable grounds to believe that the party charged is guilty thereof, which warrant shall conclude: \"Against the ordinances of the city in such cases made and provided.\" All proceedings and prosecutions for offenses against the laws of the Philippines shall conform to the rules relating to process, pleading, practice, and procedure for judiciary of the Philippines, and such rules shall govern the city court and its officers in the cases insofar as the same may be applicable."}},{"id":"PH-H3584-A81","no":81,"noLabel":{"en":"Section 81."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Costs, fees, fines and forfeitures in city court.— There shall be taxed against and collected from the defendant, in case of his conviction in the city court, such costs and fees as may be prescribed by law in criminal cases in municipal courts. All costs, fines and forfeitures shall be collected by the clerk of the court, who shall keep a docket of those imposed and of those collected, and shall pay collections of the same to the city treasurer, for the benefit of the city, on the next business day after the same are collected, and take receipts therefor. The city judge shall examine said docket each day, compare the same with the amount receipted for by the city treasurer and satisfy himself that all such costs, fees, fines and forfeitures have been duly accounted for."}},{"id":"PH-H3584-A82","no":82,"noLabel":{"en":"Section 82."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"No person sentenced by city court to be confined without commitment.— No person shall be confined in prison by sentence of the city court until the warden or officer of the prison shall receive a written commitment showing the offense for which the prisoner was tried, the date of trial, the exact terms of the judgment or sentence, and the date of the order of the commitment. The clerk shall, under seal of the court, issue such a commitment in each case of sentence to imprisonment."}},{"id":"PH-H3584-A83","no":83,"noLabel":{"en":"Section 83."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Procedure on appeal from city court to Court of First Instance.— An appeal shall lie to the Court of First Instance in all cases where fine or imprisonment, or both, is imposed by the city court. The party desiring to appeal shall, before six o’clock post meridian of the fifteenth day after notice of judgment by the city court, file with the clerk of the court a written statement that he appeals to the Court of First Instance. The filing of such statement shall perfect the appeal. The judge of the court from whose decision appeal is taken shall, within five days after the appeal is taken, transmit to the clerk of the Court of First Instance a certified copy of the record of proceedings and all the original papers and processes in the case. A perfected appeal shall operate to vacate the judgment of the city court, and the action when duly entered in the Court of First Instance, shall stand for trial de novo upon its merits as though the same had never been tried. Pending an appeal, the defendant shall remain in custody unless released in the discretion of the judge of the city court or of the judge of the Court of First Instance upon sufficient bail in accordance with procedure in force, to await the judgment of the appellate court.\nAppeals in civil cases shall be governed by the ordinance procedure established by law."}},{"id":"PH-H3584-A84","no":84,"noLabel":{"en":"Section 84."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Judicial notice of ordinance.— All courts sitting in the city shall take judicial notice of the ordinances passed by the municipal board."}},{"id":"PH-H3584-A85","no":85,"noLabel":{"en":"Section 85."},"chapter":{"en":"ARTICLE XIII"},"text":{"en":"Attendance in court, permission to pursue other vocation.— The city or auxiliary city judge when discharging the duties of the city judge shall be present at least four hours on each business day in his office or at the place where the court is held, but he may, after office hours, with the permission of the Secretary of Justice, pursue any other vocation or hold any other office or position.\nBureaus Performing Municipal Duties"}},{"id":"PH-H3584-A86","no":86,"noLabel":{"en":"Section 86."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"General Auditing Office-City Auditor.— The city auditor under the supervision of the Auditor General, shall receive and audit all accounts of the city, in accordance with the provisions of law relating to government account and accounting. He shall be appointed by the Auditor General and shall receive a salary of three thousand nine hundred pesos per annum, payable half by the national government and half from the funds of the city."}},{"id":"PH-H3584-A87","no":87,"noLabel":{"en":"Section 87."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"The Bureau of Supply Coordination.— The purchasing agent shall purchase and supply in accordance with law all supplies, equipment, materials and property of every kind, except real estate for the use of the city and its departments and offices. But contracts for completed work of any kind for the use of the city, or any of its departments or offices, involving both labor and materials, where the materials are furnished by the contractor shall not be deemed to be within the purview of this section."}},{"id":"PH-H3584-A88","no":88,"noLabel":{"en":"Section 88."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"The Bureau of Public Schools.— The Director of the Bureau of Public Schools shall exercise the same jurisdiction and power in the city as elsewhere in the Philippines and the division superintendent of schools for the Province of Negros Occidental shall have all the powers and duties in respect to the schools of the city as are vested in division superintendents in respect to schools of their divisions."}},{"id":"PH-H3584-A89","no":89,"noLabel":{"en":"Section 89."},"chapter":{"en":"ARTICLE XIV"},"text":{"en":"Reports to the mayor concerning schools— Construction and custody of school buildings.— The division superintendent of schools shall make a quarterly report of the condition of the schools and school buildings of the City of Bago to the mayor, and such recommendations as seems to him wise in respect to the number of teachers, their salaries, new buildings to be erected, and all other similar matters, together with the amount of city revenues which should be expended in paying teachers, and improving the schools or school buildings of the city.\nTransitory Provisions"}},{"id":"PH-H3584-A90","no":90,"noLabel":{"en":"Section 90."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"Change of government.— The city government provided for in this Charter shall be organized on such a date as may be fixed by the President of the Philippines.\nThe incumbent mayor, vice-mayor and members of the municipal council of the Municipality of Bago shall continue in office as the mayor, vice-mayor and members of the municipal board of the city, respectively, until the expiration of their present terms of office."}},{"id":"PH-H3584-A91","no":91,"noLabel":{"en":"Section 91."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"Election of Provincial Governor and Members of the Provincial Board of Negros Occidental.— The voters of the City of Bago shall be qualified and entitled to vote in the election of the Provincial Governor and the members of the Provincial Board of the Province of Negros Occidental."}},{"id":"PH-H3584-A92","no":92,"noLabel":{"en":"Section 92."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"Representative District.— Until otherwise provided by law, the City of Bago shall continue as part of the Second Representative District of the Province of Negros Occidental."}},{"id":"PH-H3584-A93","no":93,"noLabel":{"en":"Section 93."},"chapter":{"en":"ARTICLE XV"},"text":{"en":"This Act shall take effect on January one, nineteen hundred sixty-six, if a majority of the qualified voters of the Municipality of Bago shall accept it in a plebiscite to be held on November nine, nineteen hundred sixty-five, under the supervision of the Commission on Elections.\nApproved: June 19, 1965."}}],"pack":"ph-p50"};
  FT["PH-H3585"] = {"id":"PH-H3585","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1965/ra_4383_1965.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"增加北三宝颜省助理省检察官人数，为此修订《行政法典》第1674条（经修正）的法案","en":"An Act Increasing the Number of Assistant Provincial Fiscals for the Province of Zamboanga del Norte, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","orig":"An Act Increasing the Number of Assistant Provincial Fiscals for the Province of Zamboanga del Norte, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 4383","issuingBody":"Congress of the Philippines","promulgatedDate":"1965-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1965/ra_4383_1965.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H3585-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provision of Section sixteen hundred seventy-four of the Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Zamboanga del Norte, is further amended to read as follows:\n\"Zamboanga del Norte, three assistant provincial fiscals, who shall be assigned to the different branches of the Court of First Instance of Zamboanga del Norte in proportion to the number of cases pending in each such branch;\""}},{"id":"PH-H3585-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect on January first, nineteen hundred sixty-six.\nApproved: June 19, 1965."}}],"pack":"ph-p50","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Number of Assistant Provincial Fiscals for the Province of Zamboanga del Norte, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
